(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("ammianus-2-b", [{"sp": "HDR", "t": "Res Gestae (Libri XX–XXV)"}, {"sp": "HDR", "t": "Liber XX", "st": "20"}, {"sp": "N", "t": "Haec per Illyricum perque Orientem rerum series fuit. Consulatu vero Constantii deciens, terque Iuliani, in Britanniis cum Scottorum Pictorumque gentium ferarum excursus, rupta quiete condicta, loca limitibus vicina vastarent, et implicaret formido provincias, praeteritarum cladium congerie fessas, hiemem agens apud Parisios Caesar distractusque in sollicitudines varias, verebatur ire subsidio transmarinis, ut rettulimus ante fecisse Constantem, ne rectore vacuas relinqueret Gallias, Alamannis ad saevitiam etiam tum incitatis et bella.", "st": "20.1"}, {"sp": "N", "t": "Ire igitur ad haec ratione vel vi componenda, Lupicinum placuit, ea tempestate magistrum armorum, bellicosum sane et castrensis rei peritum, sed supercilia erigentem ut cornua, et de tragico (quod aiunt) cothurno strepentem, super quo diu ambigebatur, avarus esset potius an crudelis.", "st": "20.1"}, {"sp": "N", "t": "Moto igitur velitari auxilio, Aerulis scilicet et Batavis, numerisque Moesiacorum duobus, adulta hieme dux ante dictus Bononiam venit, quaesitisque navigiis, et omni imposito milite, observato flatu secundo ventorum, ad Rutupias sitas ex adverso defertur, petitque Lundinium, ut exinde suscepto pro rei qualitate consilio, festinaret ocius ad procinctum.", "st": "20.1"}, {"sp": "N", "t": "Quae cum ita geruntur, post Amidae oppugnationem Ursicinum ad commilitium principis ut peditum magistrum reversum, (successisse enim eum Barbationi praediximus), obtrectatores excipiunt, primo disseminantes mordaces susurros, dein propalam ficta crimina subnectentes.", "st": "20.2"}, {"sp": "N", "t": "Quibus imperator assensus, ex opinione pleraque aestimans, et insidiantibus patens, Arbitionem et Florentium officiorum magistrum quaesitores dederat spectaturos, quas ob res oppidum sit excisum.", "st": "20.2"}, {"sp": "N", "t": "Quibus apertas probabilesque refutantibus causas, veritisque ne offenderetur Eusebius, cubiculi tunc praepositus, si documenta suscepissent perspicue demonstrantia, Sabiniani pertinaci ignavia haec accidisse, quae contigerunt, a veritate detorti, inania quaedam, longeque a negotio distantia, scrutabantur.", "st": "20.2"}, {"sp": "N", "t": "Qua iniquitate percitus qui audiebatur, “Etsi me ‘inquit’ despicit imperator, negotii tamen ea est magnitudo, ut non nisi iudicio principis nosci possit et vindicari; sciat tamen velut quodam praesagio, quod dum maeret super his quae apud Amidam gesta emendata didicit fide, dumque ad spadonum arbitrium trahitur, defrustandae Mesopotamiae proximo vere ne ipse quidem cum exercitus robore omni, opitulari poterit praesens.”", "st": "20.2"}, {"sp": "N", "t": "Relatis adiectisque cum interpretatione maligna compluribus, iratus ultra modum Constantius, nec discusso negotio, nec patefieri quae scientiam eius latebant, permissis, appetitum calumniis, deposita militia digredi iussit ad otium, Agilone ad eius locum immodico saltu promoto, ex Gentilium et Scutariorum tribuno.", "st": "20.2"}, {"sp": "N", "t": "Eodem tempore per Eoos tractus caelum subtextum caligine cernebatur obscura, et a primo aurorae exortu ad usque meridiem, intermicabant iugiter stellae; hisque terroribus accedebat, quod cum lux caelestis operiretur, e mundi conspectu penitus lance abrepta, defecisse diutius solem pavidae mentes hominum aestimabant; primo attenuatum in lunae corniculantis effigiem, deinde in speciem auctum semenstrem, posteaque in integrum restitutum.", "st": "20.3"}, {"sp": "N", "t": "Quod alias non evenit ita perspicue, nisi cum post inaequales cursus iter menstruum lunae ad idem revocatur initium, certis temporum intervallis, id est cum in domicilio eiusdem signi tota reperitur luna sub sole, liniamentis obiecta rectissimis, atque in his paulisper consistit minutis, quae geometrica ratio partium partes appellat.", "st": "20.3"}, {"sp": "N", "t": "Ac licet utriusque sideris conversiones et motus, ut scrutatores causarum intellegibilium adverterant, in unum eundemque finem, lunari cursu impleto, perenni distinctione conveniunt, tamen sol non semper his diebus obducitur, sed cum luna e regione (velut libramento quodam igneo) orbi et aspectui nostro opponitur media.", "st": "20.3"}, {"sp": "N", "t": "Ad summam tum sol occultatur, splendore suppresso, cum ipse et lunaris globus astrorum omnium infimus, parili comitatu obtinentes circulos proprios, salvaque ratione altitudinis interiectae, iunctim locati, ut scienter et decore Ptolemaeus exponit, ad dimensiones venerint, quas ἀναβιβάζοντας et καταβιβάζοντας ἐκλειπτικοὺς συνδέσμους (coagmenta videlicet defectiva.) Graeco dictitamus sermone. Et si contigua eisdem iuncturis praestrinxerint spatia, dilutior erit defectus.", "st": "20.3"}, {"sp": "N", "t": "Si vero articulis ipsis inhaeserint, qui coactius ascensus vinciunt et descensus, offunditur densioribus tenebris caelum, ut crassato aere ne proxima quidem et apposita cernere queamus.", "st": "20.3"}, {"sp": "N", "t": "Sol autem geminus ita videri existimatur, si erecta solito celsius nubes, aeternorumque ignium propinquitate collucens, orbis alterius claritudinem tamquam e speculo puriore formaverit.", "st": "20.3"}, {"sp": "N", "t": "Nunc veniamus ad lunam. Apertum et evidentem ita demum sustinet luna defectum, cum pleno lumine rotundata, solique contraria, ab eius orbe centum octoginta partibus (id est signo septimo) disparatur. Et quamquam hoc per omne plenilunium semper eveniat, non semper deficit tamen.", "st": "20.3"}, {"sp": "N", "t": "Sed quoniam circa terrenam mobilitatem locata, et a caelo totius pulchritudinis extima, non numquam ferienti se subserit lanci, obiectu metae noctis in conum desinentis angustum, latet parumper umbrata, tumque nigrantibus involvitur globis, si sol ut sphaerae inferioris curvamine circumfusus, mole obsistente terrena, radiis eam suis illustrare non possit, quam numquam habere proprium lumen, opiniones variae collegerunt.", "st": "20.3"}, {"sp": "N", "t": "Et cum ad idem signum aequis partibus soli concurrent, obscuratur (ut dictum est) penitus hebetato candore, Graece σύνοδος dicitur.", "st": "20.3"}, {"sp": "N", "t": "Nasci autem putatur et tunc lunae cum parva declinatione velut e perpendiculo, superiectum gerit solem. Exortus vero eius adhuc gracilescens, primitus mortalitati videtur, cum ad secundum relicto sole migraverit signum. Progressa itaque porrectius, iamque abunde nitens cornutae habitu μηνοειδής est appellata. Cum autem sole longo coeperit interstitio summoveri, et ad quartum pervenerit signum, radiis eius ad se conversis, maius concipit lumen, et fit Graeco sermone διχόμηνις, quae forma semiorbem ostendit.", "st": "20.3"}, {"sp": "N", "t": "Procedens deinde iam disiunctissime, quintoque signo arrepto, figuram monstrat amphicyrti, utrimque prominentibus gibbis. E regione vero cum normaliter steterit contra, lumine pleno fulgebit, domicilium septimi retinens signi, et in eodem tum etiam agens, paululumque progressa, minuitur, quem habitum vocamus ἀπόκρουσιν, et usque easdem formas repetit senescendo, traditurque doctrina multiplici congruente, non nisi tempore intermenstrui deficere visam usquam lunam.", "st": "20.3"}, {"sp": "N", "t": "Quod autem solem nunc in aethere, nunc in mundo inferiore, versari praediximus, sciendum est siderea corpora quantum ad universitatem pertinet) nec occidere nec oriri, sed ita videri nostris obtutibus, constitutis in terra, spiritus cuiusdam interni motu suspensa: rerumque magnitudini instar exigui subditum puncti, nunc caelo infixas suspicere stellas, quarum ordo est sempiternus, aliquotiens humana visione languente, discedere suis sedibus arbitrari. Verum ad instituta iam revertamur.", "st": "20.3"}, {"sp": "N", "t": "Properantem Constantium Orienti ferre suppetias, turbando prope diem excursibus Persicis, ut perfugae concinentes exploratoribus indicabant, urebant Iuliani virtutes, quas per ora gentium diversarum fama celebrior effundebat, magnorum eius laborum factorumque vehens adoreas celsas, post Alamanniae quaedam regna prostrata, receptaque oppida Gallicana, ante direpta a barbaris et excisa, quos tributarios ipse fecit et vectigales.", "st": "20.4"}, {"sp": "N", "t": "Ob haec et similia percitus, metuensque ne augerentur in maius, stimulante (ut ferebatur) praefecto Florentio, Decentium tribunum et notarium misit, auxiliares milites exinde protinus abstracturum, Aerulos et Batavos, cumque Petulantibus Celtas, et lectos ex numeris aliis trecentenos, hac specie iussos accelerare, ut adesse possint armis primo vere movendis in Parthos.", "st": "20.4"}, {"sp": "N", "t": "Et super auxiliariis quidem et trecentenis, cogendis ocius proficisci, Lupicinus conventus est solus, transisse ad Britannias nondum compertus, de Scutariis autem et Gentilibus excerpere quemque promptissimum, et ipse perducere Sintula iubetur, Caesaris stabuli tunc tribunus.", "st": "20.4"}, {"sp": "N", "t": "Conticuit hisque acquieverat Iulianus, potioris arbitrio cuncta concedens. Illud tamen nec dissimulare potuit nec silere: ut illi nullas paterentur molestias, qui relictis laribus transrhenanis, sub hoc venerant pacto, ne ducerentur ad partes umquam transalpinas, verendum esse affirmans, ne voluntarii barbari militares, saepe sub eius modi legibus assueti transire ad nostra, hoc cognito deinceps arcerentur. Sed loquebatur in cassum.", "st": "20.4"}, {"sp": "N", "t": "Tribunus enim parvi querellas Caesaris ducens, Augusti iussis obtemperabat, et lecta expeditiore manu vigore, corporumque levitate praestanti, cum eisdem profectus est, spe potiorum erectis.", "st": "20.4"}, {"sp": "N", "t": "Et quia sollicitus Caesar, quid de residuis mitti praeceptis agi deberet, perque varias curas animum versans, attente negotium tractari oportere censebat, cum hinc barbara feritas, inde iussorum urgeret auctoritas, maximeque absentia magistri equitum augente dubietatem, redire ad se praefectum hortatus est, olim Viennam specie annonae parandae digressum, ut se militari eximeret turba.", "st": "20.4"}, {"sp": "N", "t": "Perpendebat enim ad relationem suam, quam olim putabatur misisse, abstrahendos e Galliarum defensione pugnaces numeros barbarisque iam formidatos.", "st": "20.4"}, {"sp": "N", "t": "Qui cum suscepisset Caesaris litteras, monentis petentisque ut venire acceleraret, rem publicam consiliis iuvaturus, obstinatissime detrectabat, hac ratione pavore mente confusa, quod aperte scripta significabant, ab imperatore nusquam diiungi debere praefectum, in ardore terribilium rerum. Adiectumque est quod si procurare dissimulasset, ipse propria sponte proiceret insignia principatus, gloriosum esse existimans iussa morte oppetere, quam ei provinciarum interitum assignari. Sed vicit praefecti propositum pertinax, his quae rationabiliter poscebantur, parere, contentione maxima reluctantis.", "st": "20.4"}, {"sp": "N", "t": "Inter has tamen moras absentis Lupicini, motusque militares timentis praefecti, Iulianus consiliorum adminiculo destitutus, ancipitique sententia fluctuans, id optimum factu existimavit: et sollemniter cunctos e stationibus egressos, in quibus hiemabant, maturare disposuit.", "st": "20.4"}, {"sp": "N", "t": "Hocque comperto, apud Petulantium signa famosum quidam libellum humi proiecit occulte, inter alia multa etiam id continentem: “Nos quidem ad orbis terrarum extrema ut noxii pellimur et damnati, caritates vero nostrae Alamannis denuo servient, quas captivitate prima post internecivas liberavimus pugnas.”", "st": "20.4"}, {"sp": "N", "t": "Quo textu ad comitatum perlato lectoque, Iulianus contemplans rationabiles querellas, cum familiis eos ad orientem proficisci praecepit, clabularis cursus facultate permissa, et cum ambigeretur diutius qua pergerent via, placuit notario suggerente Decentio, per Parisios omnes transire, ubi morabatur adhuc Caesar nusquam motus. Et ita est factum.", "st": "20.4"}, {"sp": "N", "t": "Eisdemque adventantibus, in suburbanis princeps occurrit, et ex more laudans quos agnoscebat, factorumque fortium singulos monens, animabat lenibus verbis, ut ad Augustum alacri gradu pergerent ire, ubi potestas est ample patens et larga, praemia laborum adepturi dignissima.", "st": "20.4"}, {"sp": "N", "t": "Utque honoratius procul abituros tractaret, ad convivium proceribus corrogatis, petere (siquid in promptu esset) edixit. Qui liberaliter ita suscepti, dolore duplici suspensi discesserunt et maesti, quod eos fortuna quaedam inclemens et moderato rectore et terris genitalibus dispararet. Hocque angore impliciti, ut in stativis solati cessarunt.", "st": "20.4"}, {"sp": "N", "t": "Nocte vero coeptante, in apertum erupere discidium, incitatisque animis, ut quemque insperata res afflictabat, ad tela convertuntur et manus, fremituque ingenti omnes petiverunt palatium, et spatiis eius ambitis, ne ad evadendi copiam quisquam perveniret, Augustum Iulianum horrendis clamoribus concrepabant, eum ad se prodire destinatius adigentes, exspectareque coacti, dum lux promicaret, tandem progredi compulerunt. Quo viso iterata magnitudine sonus, Augustum appellavere consensione firmissima.", "st": "20.4"}, {"sp": "N", "t": "Et ille mente fundata, universis resistebat et singulis, nunc indignari semet ostendens, nunc manus tendens oransque et obsecrans, ne post multas felicissimasque victorias, agatur aliquid indecorum, neve intempestiva temeritas et prolapsio, discordiarum materias excitaret. Haecque adiciebat, tandem sedatos leniter allocutus:", "st": "20.4"}, {"sp": "N", "t": "“Cesset ira—quaeso—paulisper: absque dissensione, vel rerum appetitu novarum, impetrabitur facile quod postulatis. Quoniam dulcedo vos patriae retinet, et insueta peregrinaque metuitis loca, redite iam nunc ad sedes nihil visuri (quia displicet) transalpinum. Hocque apud Augustum, capacem rationis et prudentissimum, ego competenti satisfactione purgabo.”", "st": "20.4"}, {"sp": "N", "t": "Conclamabatur post haec ex omni parte nihilo minus, uno parique ardore nitentibus universis, maximoque contentionis fragore, probrosis conviciis mixto, Caesar assentire coactus est. Impositusque scuto pedestri, et sublatius eminens, nullo silente, Augustus renuntiatus, iubebatur diadema proferre, negansque umquam habuisse, uxoris colli decus vel capitis poscebatur.", "st": "20.4"}, {"sp": "N", "t": "Eoque affirmante, primis auspiciis non congruere aptari muliebri mundo, equi phalera quaerebatur, uti coronatus speciem saltem obscuram, superioris praetenderet potestatis. Sed cum id quoque turpe esse asseveraret, Maurus nomine quidam, postea comes, qui rem male gessit apud Succorum angustias, Petulantium tune hastatus, abstractum sibi torquem, quo ut draconarius utebatur, capiti Iuliani imposuit confidenter, qui trusus ad necessitatem extremam, iamque periculum praesens vitare non posse advertens, si reniti perseverasset, quinos omnibus aureos, argentique singula pondo promisit.", "st": "20.4"}, {"sp": "N", "t": "Hisque gestis, haut minore quam antea cura constrictus, futuraque celeri providens corde, nec diadema gestavit, nec procedere ausus est usquam, nec agere seria quae nimis urgebant.", "st": "20.4"}, {"sp": "N", "t": "Sed cum ad latebras secessisset occultas, accidentium varietate perterritus Iulianus, aliqui palatii decurio, qui ordo est dignitatis, pleniore gradu signa Petulantium ingressus atque Celtarum, facinus indignum turbulente exclamat, pridie Augustum eorum arbitrio declaratum, clam interemptum.", "st": "20.4"}, {"sp": "N", "t": "Hocque comperto, milites quos ignota pari sollicitudine movebant et nota, pars crispantes missilia, alii minitantes nudatis gladiis, diverso vagoque (ut in repentino solet) excursu, occupavere volucriter regiam, strepituque immani excubitores perculsi, et tribuni et domesticorum comes Excubitor nomine, veritique versabilis perfidiam militis, evanuere metu mortis subitae dispalati.", "st": "20.4"}, {"sp": "N", "t": "Viso tamen otio summo, quieti stetere paulisper armati, et interrogati, quae causa esset inconsulti motus et repentini, diu tacendo haesitantes super salute principis novi, non antea discesserunt, quam adsciti in consistorium, fulgentem eum augusto habitu conspexissent.", "st": "20.4"}, {"sp": "N", "t": "His tamen auditis, etiam illi quos antegressos rettulimus, ducente Sintula, cum eo iam securi Parisios revertuntur: edictoque ut futura luce cuncti convenirent in campo, progressus princeps ambitiosius solito, tribunal ascendit, signis aquilisque circumdatus et vexillis, saeptusque tutius armatarum cohortium globis.", "st": "20.5"}, {"sp": "N", "t": "Cumque interquievisset paulisper, dum alte contemplatur praesentium vultus, alacres omnes visos et laetos, quasi lituis verbis (ut intellegi possit) simplicibus incendebat:", "st": "20.5"}, {"sp": "N", "t": "“Res ardua poscit et flagitat, propugnatores mei reique publicae fortes et fidi, qui mecum pro statu provinciarum vitam saepius obiecistis, quoniam Caesarem vestrum firmo iudicio ad potestatum omnium columen sustulistis, perstringere pauca summatim, ut remedia permutatae rei iusta colligantur et cauta.", "st": "20.5"}, {"sp": "N", "t": "“Vixdum adulescens specie tenus purpuratus (ut nostis), vestrae tutelae nutu caelesti commissus, numquam a proposito recte vivendi deiectus sum, vobiscum in omni labore perspicuus, cum dispersa gentium confidentia, post civitatum excidia, peremptaque innumera hominum milia, pauca quae semiintegra sunt relicta cladis immensitas persultaret. Et retexere superfluum puto, quotiens hieme cruda rigentique caelo, quo tempore terrae ac maria opere Martio vacant, indomitos antea, cum iactura virium suarum reppulimus Alamannos.", "st": "20.5"}, {"sp": "N", "t": "“Id sane nec praetermitti est aequum nec taceri, quod cum prope Argentoratum illuxisset ille beatissimus dies, vehens quodam modo Galliis perpetuam libertatem, inter confertissima tela me discurrente, vos vigore ususque diuturnitate fundati, velut incitatos torrentes, hostes abruptius inundantes, superastis ferro prostratos, vel fluminis profundo submersos, paucis relictis nostrorum, quorum exequias honestavimus, celebri potius laude quam luctu.", "st": "20.5"}, {"sp": "N", "t": "“Post quae opinor tanta et talia, nec posteritatem tacituram de vestris in rem publicam meritis, quae gentibus cunctis plene iam cognita sunt, si eum quem altiore fastigio maiestatis ornastis, virtute gravitateque, siquid adversum ingruerit, defendatis.", "st": "20.5"}, {"sp": "N", "t": "“Ut autem rerum integer ordo servetur, praemiaque virorum fortium maneant incorrupta, nec honores ambitio praeripiat clandestina, id sub reverenda consilii vestri facie statuo, ut neque civilis quisquam iudex, nec militiae rector, alio quodam praeter merita suffragante, ad potiorem veniat gradum, non sine detrimento pudoris, eo qui pro quolibet petere temptaverit discessuro.”", "st": "20.5"}, {"sp": "N", "t": "Hac fiducia spei maioris animatus inferior miles, dignitatum iam diu expers et praemiorum, hastis feriendo clipeos sonitu assurgens ingenti, uno prope modum ore dictis favebat et coeptis.", "st": "20.5"}, {"sp": "N", "t": "Statimque ne turbandae dispositioni consultae, tempus saltem breve concederetur, pro actuariis obsecravere Petulantes et Celtae, recturi quas placuisset provincias, mitterentur; quo non impetrato, abiere nec offensi nec tristes.", "st": "20.5"}, {"sp": "N", "t": "Nocte tamen, quae declarationis Augustae praecesserat diem, iunctioribus proximis rettulerat imperator, per quietem aliquem visum, ut formari Genius publicus solet, haec obiurgando dixisse: “Olim Iuliane vestibulum aedium tuarum observo latenter, augere tuam gestiens dignitatem, et aliquotiens tamquam repudiatus abscessi: si ne nunc quidem recipior, sententia concordante multorum, ibo demissus et maestus. Id tamen retineto imo corde quod tecum non diutius habitabo.”", "st": "20.5"}, {"sp": "N", "t": "Haec dum per Gallias agerentur intente, truculentus rex ille Persarum, incentivo Antonini adventu Craugasii duplicato, ardore obtinendae Mesopotamiae flagrans, dum ageret cum exercitu procul Constantius, armis multiplicatis et viribus, transmisso sollemniter Tigride, oppugnandam adoritur Singaram, milite usuique congruis omnibus, ut existimavere qui regionibus praeerant, abunde munitam.", "st": "20.6"}, {"sp": "N", "t": "Cuius propugnatores viso hoste longissime, clausis ocius portis, ingentibus animis per turres discurrebant et minas, saxa tormentaque bellica congerentes, cunctisque praestructis, stabant omnes armati, multitudinem parati propellere, si moenia subire temptasset.", "st": "20.6"}, {"sp": "N", "t": "Adventans itaque rex cum per optimates suos propius admissos, pacatiore colloquio flectere defensores ad suum non potuisset arbitrium, quieti diem integrum dedit, et matutinae lucis exordio, signo per flammeum erecto vexillum, circumvaditur civitas a quibusdam vehentibus scalas, aliis componentibus machinas, plerisque obiectu vinearum pluteorumque tectis, iter ad fundamenta parietum quaerentibus subvertenda.", "st": "20.6"}, {"sp": "N", "t": "Contra haec oppidani superstantes propugnaculis celsis, lapidibus eminus telorumque genere omni ad interiora ferocius se proripientes arcebant.", "st": "20.6"}, {"sp": "N", "t": "Et pugnabatur eventu ancipiti diebus aliquot, hinc inde multis amissis et vulneratis: postremo fervente certaminum mole, et propinquante iam vespera, inter machinas plures admotus aries robustissimus, orbiculatam turrim feriebat ictibus densis, unde reseratam urbem obsidio superiore docuimus.", "st": "20.6"}, {"sp": "N", "t": "Ad quam conversa plebe dimicabatur artissime, facesque cum taedis ardentibus et malleolis, ad exurendum imminens malum undique convolabant, nec sagittarum crebritate nec glandis hinc inde cessante. Vicit tamen omne prohibendi commentum acumen arietis, coagmenta fodiens lapidum recens structorum, madoreque etiam tum infirmium.", "st": "20.6"}, {"sp": "N", "t": "Dumque adhuc ferro certatur et ignibus, turri collapsa, cum patuisset iter in urbem, nudato propugnatoribus loco, quos periculi disiecerat magnitudo, Persarum agmina undique ululabili clamore sublato, nullo cohibente cuncta oppidi membra complebant, caesisque promiscue paucissimis, residui omnes mandatu Saporis vivi comprehensi, ad regiones Persidis ultimas sunt asportati.", "st": "20.6"}, {"sp": "N", "t": "Tuebantur autem hanc civitatem legiones duae (prima Flavia primaque Parthica), et indigenae plures cum auxilio equitum, illic ob repentinum malum clausorum, qui omnes (ut dixi) vinctis manibus ducebantur, nullo iuvante nostrorum.", "st": "20.6"}, {"sp": "N", "t": "Nisibin enim sub pellibus agens pars maior exercitus custodibat, intervallo perquam longo discretam, alioqui numquam labenti Singarae vel temporibus priscis, quisquam ferre auxilium potuit, aquarum penuria cunctis circum arentibus locis. Et licet ad praesciscendos adversos subitosque motus, id munimentum opportune locavit antiquitas, dispendio tamen fuit rei Romanae, cum defensorum iactura aliquotiens interceptum.", "st": "20.6"}, {"sp": "N", "t": "Exciso itaque oppido, rex Nisibin prudenti consilio vitans, memor nimirum quae saepius ibi pertulerat, dextrum latus itineribus petit obliquis, Bezabden, quam Phaenicham quoque institutores veteres appellarunt, vi vel promissorum dulcedine illectis defensoribus retenturus, munimentum impendio validum in colle mediocriter edito positum, vergensque in margines Tigridis, atque ubi loca suspecta sunt et humilia, duplici muro vallatum. Ad cuius tutelam tres legiones sunt deputatae, secunda Flavia secundaque Armeniaca, et Parthica itidem secunda cum sagittariis pluribus Zabdicenis, in quorum solo tunc nobis obtemperantium hoc est municipium positum.", "st": "20.7"}, {"sp": "N", "t": "Primo igitur impetu, cum agmine cataphractorum fulgentium, rex ipse sublimior ceteris castrorum ambitum circumcursans, prope labra ipsa fossarum venit audentius, petitusque ballistarum ictibus crebris et sagittarum, densitate opertus armorum in modum testudinis contextorum, abscessit innoxius.", "st": "20.7"}, {"sp": "N", "t": "Ira tamen tum sequestrata, caduceatoribus missis ex more, clausos blandius hortabatur, ut vitae speique consulturi, obsidium deditione solverent opportuna, reseratisque portis egressi, supplices victori gentium semet offerrent.", "st": "20.7"}, {"sp": "N", "t": "Quibus adire propius ausis, defensores moenium ideo pepercerunt, quod cohaerenter sibi iunctos duxerant eisdem notos ingenuos Singarae captos: eorum enim miseratione, telum nemo contorsit, nec super pace respondit.", "st": "20.7"}, {"sp": "N", "t": "Deinde datis indutiis diei totius et noctis, ante alterius lucis initium Persarum populus omnis adortus avide vallum, acriter minans ac fremens, ubi ad ipsa moenia confidenter accessit, dimicabat vi magna resistentibus oppidanis.", "st": "20.7"}, {"sp": "N", "t": "Eaque re sauciabantur plerique Parthorum, quod pars scalas vehentes, alii opponentes vimineas crates, velut caeci pergebant introrsus, nec nostris innocui. Sagittarum enim nimbi crebrius volitantes, stantes confertius perforabant, partibusque post solis occasum aequa iactura digressis, appetente postridie luce, ardentius multo quam antea pugnabatur, hinc inde concinentibus tubis, nec minores strages utrubique visae sunt, ambobus obstinatissime colluctatis.", "st": "20.7"}, {"sp": "N", "t": "Verum secuto die otio communi assensu post aerumnas multiplices attribute, cum magnus terror circumsisteret muros, Persaeque paria formidarent, Christianae legis antistes exire se velle gestibus ostendebat et nutu, acceptaque fide quod redire permitteretur incolumis, usque ad tentoria regis accessit.", "st": "20.7"}, {"sp": "N", "t": "Ubi data copia dicendi quae vellet, suadebat placido sermone discedere Persas ad sua, post communes partis utriusque luctus, formidari etiam maiores affirmans forsitan adventuros. Sed perstabat in cassum, haec multaque similia disserendo, efferata vesania regis obstante, non ante castrorum excidium digredi pertinaciter adiurantis.", "st": "20.7"}, {"sp": "N", "t": "Perstrinxit tamen suspicio vana quaedam episcopum (ut opinor), licet asseveratione vulgata multorum, quod clandestine colloquio Saporem docuerat, quae moenium appeteret membra, ut fragilia intrinsecus et invalida. Hocque exinde veri simile visum est, quod postea intuta loca carieque nutantia, cum exsultatione maligna, velut regentibus penetralium callidis, contemplabiliter machinae feriebant hostiles.", "st": "20.7"}, {"sp": "N", "t": "Et quamquam angustae calles difficiliorem aditum dabant ad muros, aptatique arietes aegre promovebantur, manualium saxorum, sagittarumque metu arcente, nec ballistae tamen cessavere nec scorpiones, illae tela torquentes, hi lapides crebros, qualique simul ardentes pice et bitumine illiti, quorum assiduitate per proclive labentium, machinae haerebant velut altis radicibus fixae, easque malleoli et faces iactae destinatius exurebant.", "st": "20.7"}, {"sp": "N", "t": "Sed cum haec ita essent, caderentque altrinsecus multi, ardebant magis oppugnatores, naturali situ et ingenti opere munitum oppidum ante brumale sidus excindere, rabiem regis non ante sedari posse credentes. Quocirca nec multa cruoris effusio, nec confixi mortiferis vulneribus plurimi, ceteros ab audacia parili revocabant.", "st": "20.7"}, {"sp": "N", "t": "Sed diu cum exitio decernentes, postremo periculis obiectavere semet abruptis, et agitantes arietes denso saxorum molarium pondere, fomentisque ignium variis ire protinus vetabantur.", "st": "20.7"}, {"sp": "N", "t": "Verum unus aries residuis celsior, umectis taurinis opertus exuviis, ideoque minus casus flammeos pertimescens aut tela, antegressus omnes erepsit nisibus magnis ad murum, vastoque acumine coagmenta lapidum fodiens, turrim laxatam evertit. Qua sonitu lapsa ingenti, superstantes quoque repentina ruina deiecti, diffractique vel obruti, mortibus interiere diversis et insperatis, inventoque tutiore ascensu, armata irruit multitudo.", "st": "20.7"}, {"sp": "N", "t": "Trepidis deinde superatorum auribus ululantium undique Persarum intonante fragore, artius proelium intra muros exarsit, hostium nostrorumque catervis certantibus comminus, cum confertis inter se corporibus hinc indeque stricto mucrone, nulli occurrentium parceretur.", "st": "20.7"}, {"sp": "N", "t": "Magna denique mole, ancipiti diu exitio renitentes obsessi, postremo plebis immensae ponderibus effuse disiecti sunt. Et post haec iratorum hostium gladii quicquid inveniri poterat concidebant, abreptique sinibus matrum parvuli ipsaeque matres trucidabantur, nullo quid ageret respectante. Inter quae tam funesta gens rapiendi cupidior, onusta spoliorum genere omni, captivorumque examen maximum ducens, tentoria repetivit exsultans.", "st": "20.7"}, {"sp": "N", "t": "Rex tamen gaudio insolenti elatus, diuque desiderio capiendae Phaenichae flagrans, munimenti perquam tempestivi, non ante discessit quam labefactata murorum parte reparata firmissime, alimentisque affatim conditis, armatos ibi locaret, insignis origine, bellique artibus claros. Verebatur enim quod accidit, ne amissionem castrorum ingentium ferentes aegre Romani, ad eadem obsidenda viribus magnis accingerentur.", "st": "20.7"}, {"sp": "N", "t": "Latius se proinde iactans, additaque spe quicquid aggredi posset adipiscendi, interceptis castellis aliis vilioribus, Virtam adoriri disposuit, munimentum valde vetustum, ut aedificatum a Macedone credatur Alexandro, in extreme quidem Mesopotamiae situm, sed muris velut sinuosis circumdatum et cornutis, instructioneque varia inaccessum.", "st": "20.7"}, {"sp": "N", "t": "Quod cum omni arte temptaret, nunc promissis defensores alliciens, nunc poenas cruciabiles minitans, aliquotiens struere aggeres parans, obsidionalesque admovens machinas, multis acceptis vulneribus quam illatis, omisso vano incepto, tandem abscessit.", "st": "20.7"}, {"sp": "N", "t": "Haec eo anno inter Tigrim gesta sunt et Euphraten. Quae cum frequentibus nuntiis didicisset Constantius, expeditiones metuens Parthicas, hiemem apud Constantinopolim agens, impensiore cura limitem instruebat eoum omni apparatu bellorum, armaque et tirocinia cogens, legionesque augens iuventutis validae supplementis, quarum statariae pugnae per orientales saepius eminuere procinctus, auxilia super his Scytharum poscebat, mercede vel gratia, ut adulto vere profectus e Thraciis, loca suspecta protinus occuparet.", "st": "20.8"}, {"sp": "N", "t": "Inter quae Iulianus apud Parisios hibernis locatis, summa coeptorum quorsum evaderet pertimescens haeserat anxius, numquam assensurum Constantium factis multa volvendo considerans, apud quem sordebat ut infimus et contemptus.", "st": "20.8"}, {"sp": "N", "t": "Circumspectis itaque trepidis rerum novarum exordiis, legatos ad eum mittere statuit, gesta docturos, eisque concinentes litteras dedit, quid actum sit quidve fieri oporteat deinceps, monens apertius et demonstrans.", "st": "20.8"}, {"sp": "N", "t": "Quamquam eum haec dudum comperisse opinabatur, relatu Decentii olim reversi, et cubiculariorum recens de Galliis praegressorum, qui ad Caesarem aliqua portavere sollemnia. Et quamquam nova referret, non repugnanter tamen nec arrogantibus verbis quicquam scripsit, ne videretur subito redundasse tumore. Erat autem litterarum sensus huius modi:", "st": "20.8"}, {"sp": "N", "t": "“Ego quidem propositi mei fidem non minus moribus quam foederum pacto (quoad fuit) unum semper atque idem sentiens conservavi, ut effectu multiplici claruit evidenter.", "st": "20.8"}, {"sp": "N", "t": "“Iamque inde uti me creatum Caesarem pugnarum horrendis fragoribus obiecisti, potestate delata contentus, currentium ex voto prosperitatum, nuntiis crebris (ut apparitor fidus), tuas aures implevi, nihil usquam periculis meis assignans, cum documentis assiduis constet, diffusis permixtisque passim Germanis, in laboribus me semper visum omnium primum, in laborum refectione postremum.", "st": "20.8"}, {"sp": "N", "t": "“Sed bona tua venia dixerim, siquid novatum est nunc (ut existimas): in multis bellis et asperis, aetatem sine fructu conterens miles, olim deliberatum implevit, fremens, secundique impatiens loci rectorem, cum nullas sibi vices a Caesare diuturni sudoris et victoriarum frequentium rependi posse contemplaretur.", "st": "20.8"}, {"sp": "N", "t": "“Cuius iracundiae nec dignitatum augmenta, nec annuum merentis stipendium, id quoque inopinum accessit, quod ad partis orbis eoi postremas venire iussi homines assueti glacialibus terris, separandique liberis et coniugibus, egentes trahebantur et nudi. Unde solito saevius efferati nocte in unum collecti, palatium obsidere, Augustum Iulianum vocibus magnis appellantes et crebris.", "st": "20.8"}, {"sp": "N", "t": "“Cohorrui (fateor) et secessi, amendatusque dum potui, salutem occultatione quaeritabam et latebris. Cumque nullae darentur indutiae, libero pectoris muro (ut ita dixerim) saeptus, progressus ante conspectum omnium steti, molliri posse tumultum auctoritate ratus vel sermonibus blandis.", "st": "20.8"}, {"sp": "N", "t": "“Sed exarsere mirum in modum, eo usque provecti, ut quoniam precibus vincere pertinaciam conabar, instanter mortem contiguis assultibus intentarent. Victus denique mecumque ipse contemplans, quod alter confosso me forsitan libens declarabitur princeps, assensus sum, vim lenire posse ratus armatam.", "st": "20.8"}, {"sp": "N", "t": "“Gestorum hic textus est, quem mente quaeso accipito placida. Nec actum quicquam secus existimes, vel susurrantes perniciosa malignos admittas, ad compendia sua excitare secessiones principum assuetos; sed adulatione vitiorum altrice depulsa, excellentissiman virtutum omnium adverte iustitiam, et condicionum aequitatem, quam propono, bona fide suscipito, cum animo disputans, haec statui Romano prodesse, nobiscum, qui caritate sanguinis et fortunae superioris culmine sociamur.", "st": "20.8"}, {"sp": "N", "t": "“Ignosce enim: quae cum ratione poscuntur, non tam fieri cupio, quam a te utilia probari et recta, avide tua praecepta deinde quoque suscepturus.", "st": "20.8"}, {"sp": "N", "t": "“Quae necesse sit fieri in compendium redigam breue. Equos praebebo currules Hispanos, et miscendos Gentilibus atque Scutariis adulescentes Laetos quosdam, cis Rhenum editam barbarorum progeniem, vel certe ex dediticiis, qui ad nostra desciscunt. Et haec ad usque exitum vitae me spondeo non modo grato animo, verum cupido quoque facturum.", "st": "20.8"}, {"sp": "N", "t": "“Praefectos praetorio, aequitate et meritis notos, tua nobis dabit clementia, residuos ordinarios iudices, militiaeque moderatores, promovendos arbitrio meo concedi est consentaneum, itidemque stipatores. Stultum est enim cum ante caveri possit ne fiat, eos ad latus imperatoris adscisci, quorum mores ignorantur et voluntates.", "st": "20.8"}, {"sp": "N", "t": "“Hoc sane sine ulla dubitatione firmaverim: tirones ad peregrina et longinqua Galli transmittere, diuturna perturbatione, casibusque vexati gravissimis, nec sponte sua poterunt nec coacti, ne consumpta penitus iuventute, ut affliguntur praeterita recordantes, ita desperatione pereant impendentium.", "st": "20.8"}, {"sp": "N", "t": "“Nec Parthicis gentibus opponenda auxilia hinc acciri conveniet, cum adhuc nec barbarici sint impetus interclusi, et (si dici quod verum est pateris), haec provinciae malis iactatae continuis, externis indigeant adiumentis et fortibus.", "st": "20.8"}, {"sp": "N", "t": "“Haec hortando (ut aestimo) salutariter scripsi, poscens et rogans. Scio enim scio nequid sublatius dicam, quam imperio congruens, quas rerum acerbitates, iam conclamatas et perditas, concordia vicissim sibi cedentium principum, meliorem revocavit in statum, cum appareat maiorum exemplo nostrorum, moderatores haec et similia cogitantes, fortunate beateque vivendi reperire quodam modo viam, et ultimo tempori posteritatique iucundam sui memoriam commendare.”", "st": "20.8"}, {"sp": "N", "t": "His litteris iunctas secretiores alias Constantio offerendas clanculo misit, obiurgatorias et mordaces, quarum seriem nec scrutari licebat, nec (si licuisset), proferre decebat in publicum.", "st": "20.8"}, {"sp": "N", "t": "Ad id munus implendum, electi viri sunt graves, Pentadius officiorum magister, et Eutherius cubiculi tunc praepositus, post oblatas litteras relaturi, nullo suppresso, quae viderunt, et super ordine futurorum fidenter acturi.", "st": "20.8"}, {"sp": "N", "t": "Auxerat inter haec coeptorum invidiam, Florenti fuga praefecti, qui velut praesagiens concitandos motus ob militem (ut sermone tenus iactabatur), accitum, consulto discesserat Viennam, alimentariae rei gratia divelli causatus a Caesare, quem saepe tractatum asperius formidabat.", "st": "20.8"}, {"sp": "N", "t": "Dein cum comperisset eum ad Augustum culmen evectum, exigua ac prope nulla vivendi spe versus in metum, ut longe disiunctus, malis se quae suspicabatur, exemit, et necessitudine omni relicta, digressus venit ad Constantium itineribus lentis, utque se nulli obnoxium culpae monstraret, Iulianum ut perduellem multis criminibus appetebat.", "st": "20.8"}, {"sp": "N", "t": "Cuius post abitum, bene Iulianus cogitans et prudenter, scirique volens quod praesenti quoque pepercisset, caritates eius cum re familiari intacta, publico cursu usu permisso, ad Orientem vehi tutius imperavit.", "st": "20.8"}, {"sp": "N", "t": "Nec minore studio secuti legati, haec secum ferentes, quae praediximus, intentique ad viandum, cum venirent ad iudices celsiores, oblique tenebantur, morasque per Italiam et Illyricum perpessi diuturnas et graves, tandem transfretati per Bosporum, itineribusque lentis progressi, apud Caesaream Cappadociae etiam tum degentem invenere Constantium, Mazacam antehac nominatam, opportunam urbem et celebrem, sub Argaei montis pedibus sitam.", "st": "20.9"}, {"sp": "N", "t": "Qui intromissi data potestate offerunt scripta, hisque recitatis, ultra modum solitae indignationis excanduit imperator, limibusque oculis eos ad usque metum contuens mortis, egredi iussit, nihil post haec percontatus, vel audire perpessus.", "st": "20.9"}, {"sp": "N", "t": "Perculsus tamen ardenter, cunctatione stringebatur ambigua, utrum in Persas an contra Iulianum moveri iuberet acies quibus fidebat, haesitansque diu perpensis consiliis, flexus est quorundam sententia utilium suasorum, et iter orientem versus edixit.", "st": "20.9"}, {"sp": "N", "t": "Statim tamen et legatos absolvit, et Leonam quaestorem suum in Gallias cum litteris datis ad Iulianum pergere celeri statuit gradu, nihil aovatorum se asserens suscepisse, sed eum si saluti suae proximorumque consulit, tumenti flatu deposito, intra Caesaris se potestatem continere praecipiens.", "st": "20.9"}, {"sp": "N", "t": "Utque id facile formido intentatorum efficeret, velut magnis viribus fretus, in locum Florentii praefectum praetorio, Nebridium tum quaestorem eiusdem Caesaris promoverat, et Felicem notarium, officiorum magistrum, et quosdam alios. gumoarium enim successorem Lupicini, antequam sciretur huius modi quicquam, magistrum provexit armorum.", "st": "20.9"}, {"sp": "N", "t": "Ingressus itaque Parisios, Leonas susceptus ut honoratus et prudens, postridie principi progresso in campum, cum multitudine armata pariter et plebeia, quam de industria convocarat, e tribunali (ut emineret altius) superstanti, scripta iubetur offerre. Replicatoque volumine edicti quod missum est, et legi ab exordio coepto, cum ventum fuisset ad locum id continentem, quod gesta omnia Constantius improbans Caesaris potestatem sufficere Iuliano censebat, exclamabatur undique vocum terribilium sonu:", "st": "20.9"}, {"sp": "N", "t": "“Auguste Iuliane,” ut provincialis et miles, et rei publicae decrevit auctoritas recreatae quidem, sed adhuc metuentis redivivos barbarorum excursus.", "st": "20.9"}, {"sp": "N", "t": "Quibus auditis, Leonas cum Iuliani litteris haec eadem indicantibus, revertit incolumis, solusque admissus est ad praefecturam Nebridius; id enim Caesar quoque scribens, ex sententia sua fore aperte praedixit. Magistrum enim officiorum iam pridem ipse Anatolium ordinavit, libellis antea respondentem, et quosdam alios ut sibi utile videbatur et tutum.", "st": "20.9"}, {"sp": "N", "t": "Et quoniam cum haec ita procederent, timebatur Lupicinus, licet absens agensque etiam tum apud Britannos, homo superbae mentis et turgidae, eratque suspicio quod (si haec trans mare didicisset) novarum rerum materias excitaret, notarius Bononiam mittitur, observaturus sollicite, ne quisquam fretum oceani transire permitteretur. Quo vetito, reversus Lupicinus, antequam horum quicquam sciret, nullas ciere potuit turbas.", "st": "20.9"}, {"sp": "N", "t": "Iulianus tamen iam celsiore fortuna, militisque fiducia laetior, ne intepesceret, neve ut remissus argueretur et deses, legatis ad Constantium missis, in limitem Germaniae secundae egressus est, omnique apparatu, quem flagitavit instans negotium, communitus, Tricensimae oppido propinquabat.", "st": "20.10"}, {"sp": "N", "t": "Rheno exinde transmisso, regionem subito pervasit Francorum, quos Atthuarios vocant, inquietorum hominum licentius etiam tum percursantium extima Galliarum. Quos adortus subito nihil metuentes hostile, nimiumque securos, quod scruposa viarum difficultate arcente, nullum adhuc suos pagos introisse meminerant principem, superavit negotio levi: captisque plurimis et occisis, orantibus aliis qui superfuere, pacem ex arbitrio dedit, hoc prodesse possessoribus finitimis arbitratus.", "st": "20.10"}, {"sp": "N", "t": "Unde reversus pari celeritate per flumen, praesidiaque limitis explorans diligenter et corrigens, ad usque Rauracos venit, locisque recuperatis, quae olim barbari intercepta retinebant ut propria, eisdemque pleniore cura firmatis, per Besantionem Viennam hiematurus abscessit.", "st": "20.10"}, {"sp": "N", "t": "Hic per Gallias erat ordo gestorum. Quae dum ita prospere succedunt et caute, Constantius accitum Arsacen Armeniae regem, summaque liberalitate susceptum, praemonebat et hortabatur, ut nobis amicus esse perseveraret et fidus.", "st": "20.11"}, {"sp": "N", "t": "Audiebat enim saepius eum temptatum a rege Persarum fallaciis et minis et dolis, ut Romanorum societate posthabita, suis rationibus stringeretur.", "st": "20.11"}, {"sp": "N", "t": "Qui crebro adiurans, animam prius posse amittere quam sententiam, muneratus cum comitibus quos duxerat redit ad regnum, nihil ausus temerare postea promissorum, obligatus gratiarum multiplici nexu Constantio, inter quas illud potius excellebat, quod Olympiada (Ablabi filiam), praefecti quondam praetorio, ei copulaverat coniugem sponsam fratris sui Constantis.", "st": "20.11"}, {"sp": "N", "t": "Quo dimisso a Cappadocia ipse per Melitenam (minoris Armeniae oppidum), et Lacotena et Samosata, transito Euphrate Edessam venit, ibique dum agmina undique convenientium militum, et rei cibariae abundantes copias operitur, diu moratus, post aequinoctium egreditur autumnale Amidam petens.", "st": "20.11"}, {"sp": "N", "t": "Cuius cum prope venisset moenia favillis oppleta, collustrans, flebat cum gemitu, reputans qualis miseranda civitas pertulerat clades. Ibi tunc forte Ursulus praesens, qui aerarium tuebatur, dolore percitus exclamavit: “En quibus animis urbes a milite defenduntur, cui ut abundare stipendium possit, imperii opes iam fatiscunt!” Quod dictum ita amarum militaris multitudo postea apud Chalcedona recordata, ad eius exitium consurrexit.", "st": "20.11"}, {"sp": "N", "t": "Exinde cuneis confertis incedens, cum Bezabden adventaret, fixis tentoriis, vallo fossarumque altitudine circumsaeptis, obequitans castrorum ambitum longius, docebatur relatione multorum, instaurata esse firmius loca, quae antehac incuria corruperat vetustatis.", "st": "20.11"}, {"sp": "N", "t": "Et nequid omitteret, quod ante fervorem certaminum erat necessario praestruendum, viris prudentibus missis, condicione posita dupla, urgebat moenium defensores redire ad suos, alienis sine cruore concessis, aut in dicionem venire Romanam, dignitatibus augendos et praemiis. Atque cum illi destinatione nativa reniterentur, ut dare nati periculisque et laboribus indurati obsidioni congrua parabantur.", "st": "20.11"}, {"sp": "N", "t": "Densis itaque ordinibus, cum tubarum incitamentis, latera oppidi cuncta adortus alacrius miles, legionibus in testudines varias conglobatis paulatim tuto progrediens, subruere moenia conabatur, et quia telorum omne genus in subeuntes effundebatur, nexu clypeorum soluto discessum est, in receptum canentibus signis.", "st": "20.11"}, {"sp": "N", "t": "Laxatis deinde ad diem unum indutiis, tertia luce milite curiosius tecto, elatis passim clamoribus, ascensus undique temptabatur. Et licet defensores sub obtentis ciliciis, ne conspicerentur ab hostibus, latebant intrinsecus, tamen quotiens flagitabat necessitas, lacertos fortiter exsertantes, lapidibus subiectos incessebant et telis.", "st": "20.11"}, {"sp": "N", "t": "Et vimineae crates cum procederent confidenter, essentque parietibus iam contiguae, dolia desuper cadebant et molae, et columnarum fragmenta, quorum ponderibus nimiis obruebantur oppugnatores, hiatuque violento disiectis operimentis, cum periculis ultimis evadebant.", "st": "20.11"}, {"sp": "N", "t": "Decimo itaque postquam pugnari coeptum est die, cum spes nostrorum inferior cuncta maerore compleret, transferri placuerat molem arietis magnam, quam Persae quondam, Antiochia pulsibus eius excisa, relatam reliquerant apud Carras. Quae subito visa, aptataque faberrime, clausorum hebetaverat mentes, ad usque deditionis remedia paene prolapsas, ni resumptis viribus opponenda minaci machinae praeparassent.", "st": "20.11"}, {"sp": "N", "t": "Nec temeritas post haec cessaverat nec consilium; namque dum instrueretur aries vetustus et dissolutus, ut facile veheretur, omni arte omnique virium nisu, et oppugnatorum vineae firmitudine summa defensabatur, tormenta nihilo minus et lapidum crebritas atque fundarum ex utraque parte plurimos consumebant, et aggerum moles incrementis celeribus consurgebant, acriorque in dies adulescebat obsidio, multis nostrorum idcirco cadentibus, quod decernentes sub imperatoris conspectu, spe praemiorum, ut possint facile qui essent agnosci, nudantes galeis capita, sagittariorum hostilium peritia fundebantur.", "st": "20.11"}, {"sp": "N", "t": "Proin dies et noctes intentae vigiliis cautiores stantes utrubique faciebant. Et Persae aggerum altitudine iam in sublime porrecta, machinaeque ingentis horrore perculsi, quam minores quoque sequebantur, omnes exurere vi maxima nitebantur, et assidue malleolos atque incendiaria tela torquentes, laborabant in cassum, ea re quod umectis coriis et centonibus erant opertae materiae plures, aliae unctae alumine diligenter, ut ignis in eas laberetur innoxius.", "st": "20.11"}, {"sp": "N", "t": "Verum has admoventes fortitudine magna, Romani licet difficile defensabant, tamen cupiditate potiundi oppidi ne prompta quidem pericula non contemnebant.", "st": "20.11"}, {"sp": "N", "t": "Et contra propugnatores cum iam discussurus turrim oppositam aries maximus adventaret, prominentem eius ferream frontem, quae re vera formam effingit arietis, arte subtili illaqueatam altrinsecus, laciniis retinuere longissimis, ne retrogradiens resumeret vires, neve ferire muros assultibus densis contemplabiliter posset, fundentes quoque ferventissimam picem. Et diu promotae machinae stabant, muralia saxa perferentes et tela.", "st": "20.11"}, {"sp": "N", "t": "Iamque aggeribus cumulatius excitatis, defensores, ni vigilassent, exitium affore iam sperantes, in audaciam ruere praecipitem, et repentino decursu, portis effusi, primosque adorti nostrorum, faces sitellasque ferreas onustas ignibus in arietes magnis viribus iaciebant.", "st": "20.11"}, {"sp": "N", "t": "Verum post ambiguam proelii varietatem, plurimi nullo impetrato intra moenia repelluntur: moxque ex aggeribus quos erexerunt Romani, idem Persae propugnaculis insistentes, sagittis incessebantur, et fundis telisque igniferis, quae per tegumenta turrium volitantia, paratis qui restinguerent, plerumque irrita labebantur.", "st": "20.11"}, {"sp": "N", "t": "Cumque pauciores utrubique fierent bellatores, et Persae truderentur ad ultima ni potior ratio succurrisset, impensiore opera procursus temptabatur ex castris, et eruptione subita multitudinis facta, inter armatos qui portabant ignes amplioribus ordinatis, iaciebantur corbes in materias ferreae, plenae flammarum, et sarmenta aliaque ad ignes concipiendos aptissima.", "st": "20.11"}, {"sp": "N", "t": "Et quia conspectum abstulerant fumi nigerrimae nubes, classico excitante in pugnam, legiones procinctae celeri gradu venerunt, et subcrescente paulatim ardore bellandi, cum ventum fuisset ad manus, repente machinae omnes effusis ignibus urebantur praeter maiorem, quam diruptis restibus quibus e muro iactis implicabatur, virorum fortium acrior nisus aegre semustam extraxit.", "st": "20.11"}, {"sp": "N", "t": "At ubi nocturnae tenebrae finem proeliis attulerunt, non in longum militi quies data. Cibo enim exiguo refectus et somno, rectorum monitu excitus, munitiones a muro longe demovit, dimicare succinctius parans per sublimes aggestus, qui iam consummati muris altius imminebant. Utque facile defensuri moenia pellerentur, in ipsis aggerum summitatibus binae sunt locatae ballistae, quarum metu ne prospicere quidem posse hostium quisquam crederetur.", "st": "20.11"}, {"sp": "N", "t": "His satis provisis, prope ipsum crepusculum triplex acies nostrorum instructa, conisque galearum minacius nutans, scalas vehentibus multis, impetum conabatur in muros. Iamque resultantibus armis et tubis, uno parique ardore hinc indeque pugnabatur audaci conflictu, latiusque sese pandente manu Romana, cum Persas occultari viderent, pavore impositorum aggeribus tormentorum, pulsabant turrim ariete, et cum ligonibus et dolabris et vectibus scalae quoque propinquabant utrimque convolante missilium crebritate.", "st": "20.11"}, {"sp": "N", "t": "Afflictabant tamen multo vehementius Persas ictus varii ballistarum, tamquam per transennam a clivis structilibus decurrentes. Unde fortunas suas sitas in extremo iam cogitantes, destinatam ruebant in mortem, et partiti munera dimicandi inter necessitatis articulos, relictis qui moenia tuerentur, reserata latenter postica, strictis gladiis valida manus erupit, pone sequentibus aliis, qui flammas occulte portabant.", "st": "20.11"}, {"sp": "N", "t": "Dumque Romani nunc instant cedentibus, nunc ultro incessentes excipiunt, qui vehebant foculos repentes incurvi, prunas unius aggesti inseruere iuncturis ramis arborum diversarum, et iunco et manipulis constructi cannarum: qui conceptis incendiorum aridis nutrimentis, iam cremabantur, militibus cum intactis tormentis exinde periculose digressis.", "st": "20.11"}, {"sp": "N", "t": "Ut vero certaminibus finem vespera dedit incedens, partesque discesserunt ad otium breve, imperator in varia sese consilia diducens et versans, cum excidio Phaenichae diutius imminere, necessariae rationes urgerent, quod munimentum velut insolubile claustrum, hostium excursibus erat obiectum, et serum repelleret tempus: certaturus leviter ibi statuit immorari, alimentis destituendos forsitan cedere existimans Persas. Quod secus atque rebatur evenit.", "st": "20.11"}, {"sp": "N", "t": "Cum enim remissius pugnaretur, umente caelo undantes nubes cum tenebris advenere minacibus, assiduisque imbribus ita immaduerat solum, ut luti glutinosa mollities, per eas regiones pinguissimi caespitis, omnia perturbaret. Et super his iugi fragore, tonitrua fulguraque mentes hominum pavidas perterrebant.", "st": "20.11"}, {"sp": "N", "t": "Accedebant arcus caelestis conspectus assidui. Quae species unde ita figurari est solita, expositio brevis ostendet. Halitus terrae calidiores et umoris spiramina conglobata in nubes, exindeque disiecta in aspergines parvas, ac radiorum fusione splendida facta, supinantur volubiliter contra ipsum igneum orbem, irimque conformant, ideo spatioso curvamine sinuosam, quod in nostro panditur mundo, quem sphaerae dimidiae parti rationes physicae superponunt.", "st": "20.11"}, {"sp": "N", "t": "Cuius species quantum mortalis oculus contuetur, prima lutea visitur, secunda flavescens vel fulva, punicea tertia, quarta purpurea, postrema caerulo concreta et viridi.", "st": "20.11"}, {"sp": "N", "t": "Hac autem mixta pulchritudine temperatur, ideo ut terrenae existimant mentes, quod prima eius pars dilutior cernitur, aeri concolor circumfuso, sequens fulva, id est paulo excitatior quam lutea, punicea tertia, quod solis obnoxia claritudini, pro reciprocatione spiritus fulgores eius purissime e regione deflorat, quarta ideo purpurat, quod intermicante asperginum densitate, per quas oritur, radiorum splendor concipiens ostendit aspectum flammeo propiorem, qui color quanto magis diffunditur, concedit in caerulum et virentem.", "st": "20.11"}, {"sp": "N", "t": "Arbitrantur alii tune iridis formam rebus apparere mundanis, cum altius delatae nubi crassae radii solis infusi, lucem iniecerint liquidam, quae non reperiens exitum, in se conglobata nimio splendescit attritu, et proximos quidem albo colores a sole sublimiore decerpit, subvirides vero a nubis similitudine superiectae, ut in mari solet usu venire, ubi candidae sunt undae quae litoribus illiduntur, interiores sine ulla concretione caerulae.", "st": "20.11"}, {"sp": "N", "t": "Et quoniam indicium est permutationis aurae (ut diximus), a sudo aere nubium concitans globos, aut contra ex concreto mutans in serenam laetitiam caelum, ideo apud poetas legimus saepe, Irim de caelo tunc mitti, cum praesentium rerum verti necesse sit status. Suppetunt aliae multae opiniones et variae, quas dinumerare nunc est supervacuum, narratione redire unde digressa est festinante.", "st": "20.11"}, {"sp": "N", "t": "His ac talibus imperator inter spem metumque iactabatur, ingravescente hiemis magnitudine, suspectisque per avios tractus insidiis, inter quae etiam tumultum exasperati militis verebatur. Super his urebat eius anxiam mentem, quod velut patefacta ianua divitis domus, irritus propositi reverteretur.", "st": "20.11"}, {"sp": "N", "t": "Quas ob res omisso vano incepto, hiematurus Antiochiae redit in Syriam, aerumnosa perpessus et gravia; nec enim levia erant damna quae Persae intulerant, sed atrociora diuque deflenda. Evenerat enim hoc, quasi fatali constellatione ita regente diversos eventus, ut ipsum Constantium dimicantem cum Persis, fortuna semper sequeretur afflictior, unde vincere saltim per duces optabat, quod aliquotiens meminimus contigisse.", "st": "20.11"}, {"sp": "HDR", "t": "Liber XXI", "st": "21"}, {"sp": "N", "t": "Intercluso hac bellorum difficili sorte Constantio trans flumen Euphratem, Iulianus agens apud Viennam, firmandis in futura consiliis, dies impendebat et noctes, quantum opes patiebantur angustae, altius semet attollens, semperque ambigens, utrum Constantium modis omnibus alliceret in concordiam, an terroris incutiendi gratia lacesseret prior.", "st": "21.1"}, {"sp": "N", "t": "Quae sollicite reputans, utrumque formidabat, et amicum cruentum et in aerumnis civilibus saepe victorem, maximeque Galli fratris exemplum, mentem eius anxiam suspendebat, quem inertia mixtaeque periuriis fraudes prodidere quorundam.", "st": "21.1"}, {"sp": "N", "t": "Erigebat tamen aliquotiens animum ad multa et urguentia, tutissimum ratus inimicum se ex confesso monstrare, ei cuius ex praeteritis motus coniectabat ut prudens, ne per amicitias fictas insidiis falleretur occultis.", "st": "21.1"}, {"sp": "N", "t": "Parvi igitur habitis, quae per Leonam Constantius scripserat, nulloque arbitrio eius promotorum suscepto, praeter Nebridium, quinquennalia Augustus iam edidit: et ambitioso diademate utebatur, lapidum fulgore distincto, cum inter exordia principatus, assumpta vili corona circumdatus erat xystarchae similis purpurato.", "st": "21.1"}, {"sp": "N", "t": "Inter quae Helenae coniugis defunctae suprema miserat Romam, in suburbano viae Nomentanae condenda, ubi uxor quoque Galli quondam (soror eius) sepulta est Constantina.", "st": "21.1"}, {"sp": "N", "t": "Acuebat autem incendebatque eius cupiditatem, pacatis iam Galliis, incessere ultro Constantium, animus coniciens eum per vaticinandi praesagia multa (quae callebat) et somnia, e vita protinus excessurum.", "st": "21.1"}, {"sp": "N", "t": "Et quoniam erudito et studioso cognitionum omnium principi, malivoli praenoscendi futura pravas artes assignant, advertendum est breviter, unde sapienti viro hoc quoque accedere poterit, doctrinae genus haud leve.", "st": "21.1"}, {"sp": "N", "t": "Elementorum omnium spiritus, utpote perennium corporum praesentiendi motu semper et ubique vigens, ex his, quae per disciplinas varias affectamus, participat nobiscum munera divinandi: et substantiales potestates ritu diverso placatae, velut ex perpetuis fontium venis, vaticina mortalitati suppeditant verba, quibus numen praeesse dicitur Themidis, quam ex eo quod fixa fatali lege decreta, praescire facit in posterum, quae τεθειμένα sermo Graecus appellat, ita cognominatam, in cubili solioque Iovis, vigoris vivifici, theologi veteres collocarunt.", "st": "21.1"}, {"sp": "N", "t": "Auguria et auspicia non volucrum arbitrio futura nescientium colliguntur (nec enim hoc vel insipiens quisquam dicet) sed volatus avium dirigit deus, ut rostrum sonans aut praetervolans pinna, turbido meatu vel leni, futura praemonstret. Amat enim benignitas numinis, seu quod merentur homines, seu quod tangitur eorum affectione, his quoque artibus prodere quae impendent.", "st": "21.1"}, {"sp": "N", "t": "Extis itidem pecudum attenti fatidicis, in species converti assuetis innumeras, accidentia sciunt. Cuius disciplinae Tages nomine quidam monstrator est, ut fabulantur, in Etruriae partibus emersisse subito visus e terra.", "st": "21.1"}, {"sp": "N", "t": "Aperiunt tunc quoque ventura, cum aestuant hominum corda, sed locuntur divina. Sol enim (ut aiunt physici) mens mundi nostras mentes ex sese velut scintillas diffunditans cum eas incenderit vehementius, futuri conscias reddit. Unde Sibyllae crebro se dicunt ardere, torrente vi magna flammarum. Multa significant super his crepitus vocum, et occurrentia signa, tonitrua quin etiam et fulgura, et fulmina itidemque siderum sulci.", "st": "21.1"}, {"sp": "N", "t": "Somniorum autem rata fides et indubitabilis foret, ni ratiocinantes coniectura fallerentur interdum. Quae (ut Aristoteles affirmat) tum fixa sunt et stabilia, cum animantis altius quiescentis, ocularis pupula neutrubi inclinata, rectissime cernit.", "st": "21.1"}, {"sp": "N", "t": "Et quia vanities aliquotiens plebeia strepit, haec imperite mussando, si esset praesentiendi notitia quaedam, cur ille se casurum in bello, vel alius hoc se passurum ignoravit aut illud, sufficiet dici, quod et grammaticus locutus interdum est barbare, et absurde cecinit musicus, et ignoravit remedium medicus: sed non ideo nec grammatica nec musica nec medicina subsistit.", "st": "21.1"}, {"sp": "N", "t": "Unde praeclare hoc quoque (ut alia) Tullius: “Signa ostenduntur” ait “a dis rerum futurarum. In his siqui erraverit, non deorum natura sed hominum coniectura peccavit.” Ne igitur extra calcem (quod dicitur) sermo decurrens, lecturo fastidium ferat, ad explicanda prospecta revertamur.", "st": "21.1"}, {"sp": "N", "t": "Cum apud Parisios adhuc Caesar Iulianus quatiens scutum variis motibus exerceretur in campo, axiculis, quibus orbis erat compaginatus, in vanum excussis, ampla remanserat sola, quam retinens valida manu stringebat.", "st": "21.2"}, {"sp": "N", "t": "Territisque ut omine diro praesentibus cunctis, “Nemo” inquit “vereatur: habeo firmiter quod tenebam.” Item cum apud Viennam postea quiesceret sobrius, horrore medio noctis, imago quaedam visa splendidior, hos ei versus heroes modo non vigilanti aperte edixit, eadem saepius replicando, quibus fretus nihil asperum sibi superesse existimabat<br>Ζεὺς ὅταν εἰς πλατὺ τέρμα μόλῃ κλυτοῦ ὑδροχόοιο,<br>Παρθενικῆς δὲ Κρόνος μοίρῃ βαίνῃ ἐπὶ πέμπτῃ<br>εἰκοστῇ, βασιλεὺς Κωνστάντιος Ἀσίδος αἴης<br>τέρμα φίλου βιοτοῦ στυγερὸν καὶ ἐπώδυνον ἕξει.", "st": "21.2"}, {"sp": "N", "t": "Agebat itaque nihil interim de statu rerum praesentium mutans, sed animo tranquillo et quieto incidentia cuncta disponens, paulatimque sese corroborans, ut dignitatis augmento, virium quoque congruerent incrementa.", "st": "21.2"}, {"sp": "N", "t": "Utque omnes nullo impediente, ad sui favorem illiceret, adhaerere cultui Christiano fingebat, a quo iam pridem occulte desciverat, arcanorum participibus paucis, haruspicinae auguriisque intentus, et ceteris quae deorum semper fecere cultores.", "st": "21.2"}, {"sp": "N", "t": "Et ut haec interim celarentur, feriarum die, quem celebrantes mense Ianuario Christiani Epiphania dictitant, progressus in eorum ecclesiam, sollemniter numine orato discessit.", "st": "21.2"}, {"sp": "N", "t": "Dum haec ita aguntur, propinquante iam vere, nuntio percitus inopino, ad tristitiam versus est et maerorem. Didicit enim Alamannos a pago Vadomarii exorsos, unde nihil post ictum foedus sperabatur incommodum, vastare confinis Raetiis tractus, nihilque sinere intemptatum, manus praedatorias fusius discurrentes.", "st": "21.3"}, {"sp": "N", "t": "Quod ne dissimulatum redivivas bellorum materias excitaret, Libinonem quendam comitem cum Celtis et Petulantibus misit, hiemantibus secum, negotium (ut poscebat ratio) correcturum.", "st": "21.3"}, {"sp": "N", "t": "Qui cum mature prope oppidum Sanctionem venisset, longe visus a barbaris, qui iam certamina meditantes, sese per valles abdiderant, hortatusque milites licet numero impares, cupidine tamen pugnandi vehementius irritatos, aggreditur inconsulte Germanos, interque dimicandi exordia, ipse concidit omnium primus, cuius interitu erecta barbarorum fiducia, Romanisque ad ducis vindictam accensis, certamen committitur obstinatum, et urgente magnitudinis mole, disiecti sunt nostri occisis paucis et vulneratis.", "st": "21.3"}, {"sp": "N", "t": "Cum hoc Vadomario et Gundomado eius fratre itidem rege, Constantius (ut iam relatum est) firmaverat pacem. Post quae mortuo Gundomado, hunc sibi fore existimans fidum, secretorumque taciturnum exsecutorem et efficacem mandabat, si famae solius admittenda est fides, scribebatque, ut tamquam rupto concordiae pacto, subinde collimitia sibi vicina vexaret, quo Iulianus id metuens nusquam a tutela discederet Galliarum.", "st": "21.3"}, {"sp": "N", "t": "Quibus (si dignum est credere) obtemperans Vadomarius haec et similia perpetrabat, ad perstringendum fallendumque miris modis ab aetatis primitiis callens, ut postea quoque ducatum per Phoenicen regens ostendit. Sed re ipsa convictus abstinuit. Capto enim a stationariis militibus notario, quem miserat ad Constantium, scrutatoque siquid portaret, epistula eius reperta est, in qua praeter alia multa, id quoque scripserat: “Caesar tuus disciplinam non habet.” Iulianum autem assidue per litteras dominum et Augustum appellabat et deum.", "st": "21.3"}, {"sp": "N", "t": "Haec ut erant periculosa et dubia, Iulianus in exitiale malum eruptura considerans, in unum omni cogitatione intenta, eum vi incautum rapere festinabat, ut securitatem suam provinciarumque locaret in tuto, et iniit consilium tale.", "st": "21.4"}, {"sp": "N", "t": "Philagrium notarium, Orientis postea comitem, ad eas miserat partes, cuius prudentiae fidebat, olim sibi compertae, eique inter multa, quae pro captu instantium rerum erat acturus, signatam quoque chartulam tradidit, mandavitque, ne aperiret vel recitaret nisi Vadomario viso cis Rhenum.", "st": "21.4"}, {"sp": "N", "t": "Perrexit Philagrius ut praeceptum est, eoque praesente et negotiis adstricto diversis, transgressus Vadomarius flumen, ut nihil in profunda metuens pace nihilque secus gestorum simulans scire, viso praeposito militum ibi degentium, pauca locutus ex more, ultro semet, ut suspicionis nihil relinqueret abiturus, ad convivium eius venire promisit, ad quod erat etiam Philagrius invitatus.", "st": "21.4"}, {"sp": "N", "t": "Qui statim ingressus, rege conspecto imperatoris recordatus est verba, causatusque rem seriam et urgentem, ad diversorium rediit, scriptisque lectis, doctus quid agi conveniet, confestim reversus discubuit inter ceteros.", "st": "21.4"}, {"sp": "N", "t": "Finitisque epulis Vadomarium fortiter apprehensum, rectori militum arte custodiendum apud signa commisit, textu lecto iussorum, comitibus eius ad sua redire compulsis, super quibus nihil fuerat imperatum.", "st": "21.4"}, {"sp": "N", "t": "Exhibitus tamen idem rex ad principis castra, iamque spe veniae omni praeclusa, cum interceptum notarium et quae scripserat ad Constantium, comperisset iam publicata, ne convicio quidem tenus compellatus, missus est ad Hispanias. Id enim studio curabatur ingenti, ne Iuliano discedente a Galliis, immanissimus homo provinciarum statum aegre compositum, licentius conturbaret.", "st": "21.4"}, {"sp": "N", "t": "Hoc casu elatior Iulianus, regis opinione citius intercepti, quem profecturus ad longinqua formidabat nihil remittentibus curis, barbaros adoriri disposuit, quos peremisse Libinonem comitem in congressu cum militibus docuimus paucis.", "st": "21.4"}, {"sp": "N", "t": "Et ne rumor adventus sui eos ad remotiora traduceret, superato Rheno noctis alto silentio, cum auxiliorum expeditissimis globis, nihil metuentes huius modi circumvenit, excitatosque hostilium fragore armorum, dum gladios circumspectant et tela, celeriter involavit et quosdam occidit, orantes alios praedamque offerentes, dediticios cepit, reliquis, qui remansere, pacem precantibus dedit, quietem pollicitis firmam.", "st": "21.4"}, {"sp": "N", "t": "Quae dum mentibus aguntur erectis, coniectans quantas intestinae cladis excitaverat moles, nihilque tam convenire conatibus subitis, quam celeritatem sagaci praevidens mente, professa palam defectione, se tutiorem fore existimavit, incertusque de militum fide, placata ritu secretiore Bellona, classico ad contionem exercitu convocato, saxeo suggestu insistens, iamque (ut apparebat) fidentior haec clarius solito disserebat:", "st": "21.5"}, {"sp": "N", "t": "“Iam dudum tacita deliberatione vos aestimo (magni commilitones) gestorum excitos amplitudine, hoc operiri consilium, ut eventus, qui sperantur, perpendi possint et praecaveri. Plus enim audire quam loqui militem decet actibus coalitum magnis et gloriosis, nec alia spectatae aequitatis sentire rectorem, quam ea, quae laudari digne potuerunt et probari. Ut igitur quae proposui ambagibus abiectis absolvam, advertite oro benivole, quae sermone brevi percurram.", "st": "21.5"}, {"sp": "N", "t": "“Arbitrio dei caelestis, vobis inter ipsa iuventae rudimenta permixtus, irruptiones Alamannorum assiduas et Francorum, populandique iugem licentiam fregi, et vigore communi, Romanis agminibus quotiens libet Rhenum pervium feci, contra rumorum fremitus gentiumque validarum violentos excursus, stando immobilis, virtutis vestrae nimirum firmamento confisus.", "st": "21.5"}, {"sp": "N", "t": "“Et haec laborum, quos exhausimus, Galliae spectatrices post funera multa, iacturasque recreatae diuturnas et graves, posteritati per aetatum examina commendabunt.", "st": "21.5"}, {"sp": "N", "t": "“At nunc cum auctoritate vestri iudicii, rerumque necessitate compulsus, ad Augustum elatus sum culmen, deo vobisque fautoribus, si fortuna coeptis adfuerit, altius affecto maiora, id prae me ferens quod exercitui cuius aequitas armorumque inclaruit magnitudo, domi moderatus visus sum et tranquillus, et in crebritate bellorum, contra conspiratas gentium copias, consideratus et cautus.", "st": "21.5"}, {"sp": "N", "t": "“Ut igitur adversa praeveniamus mentium societate iunctissima, sequimini viam consilii mei salutarem (ut puto), cum integritas rerum intentioni nostrae voluntatique respondeat, et dum maioribus vacant praesidiis regiones Illyricae, impraepedito cursu tendentes, Daciarum interim fines extimos occupemus, exinde quid agi oporteat bonis successibus instruendi.", "st": "21.5"}, {"sp": "N", "t": "“Ad quae vos ex more fidentium ducum, iuramento quaeso concordiam spondete mansuram et fidem, operam mi navaturo sedulam et sollicitam, nequid agatur inconsultum et segne, et producturo, siquis exegerit, incorruptam conscientiam meam, quod nihil voluntate praeter ea, quae in commune conducunt, aggrediar aut temptabo.", "st": "21.5"}, {"sp": "N", "t": "“Illud sane obtestor et rogo: observate, ne impetu gliscentis ardoris, in privatorum damna quisquam vestrum exsiliat, id cogitans quod ita nos illustrarunt hostium innumerae strages, ut indemnitas provinciarum et salus exemplis virtutum pervulgatae.”", "st": "21.5"}, {"sp": "N", "t": "Hoc sermone imperatoris vice alicuius oraculi comprobato, mota est incitatius contio, et rerum cupida novandarum, unanimanti consensu, voces horrendas immani scutorum fragore miscebat, magnum elatumque ducem, et (ut experta est) fortunatum domitorem gentium appellans et regum.", "st": "21.5"}, {"sp": "N", "t": "Iussique universi in eius nomen iurare, sollemniter, gladiis cervicibus suis admotis, sub exsecrationibus diris, verbis iuravere conceptis, omnes pro eo casus, quoad vitam profuderint (si necessitas adegerit) perlaturos; quae secuti rectores, omnesque principis proximi, fidem simili religione firmarunt.", "st": "21.5"}, {"sp": "N", "t": "Solus omnium licet proposito stabili, audacter tamen praefectus repugnavit Nebridius, iuris iurandi nexu contra Constantium nequaquam se stringi posse commemorans, cuius beneficiis obligatus erat crebris et multis.", "st": "21.5"}, {"sp": "N", "t": "Quibus auditis, cum stantes propius milites acriter inflammati, eum appeterent trucidandum, ad genua sua prolapsum, imperator paludamento protexit, indeque reversus in regiam cum antegressum eum vidisset supplicemque iacentem orare, ut levandi causa timoris, ei porrigeret dexteram, “Ecquid” ait “praecipuum amicis servabitur, si tu manum tetigeris meam? Sed tu quo libet abi securus.” Hocque audito, ille innoxius ad larem suum recessit in Tusciam.", "st": "21.5"}, {"sp": "N", "t": "His Iulianus, ut poscebat negotii magnitudo, praestructis, expertus quid in rebus tumultuosis anteversio valeat et praegressus, per tesseram edicto itinere in Pannonias, castris promotis et signis, temere se fortunae commisit ambiguae.", "st": "21.5"}, {"sp": "N", "t": "Replicare nunc convenit tempora, et narrare summatim, quae dum aguntur in Galliis ante dicta, Constantius hiemans Antiochiae, domi militiaeque perfecit.", "st": "21.6"}, {"sp": "N", "t": "Inter complures alios honore conspicuos, adoraturi imperatorem peregre venientem, ordinantur etiam ex tribunis insignibus. Cum igitur a Mesopotamia reversus, Constantius hoc exciperetur officio, Amphilochius quidam ex tribuno Paphlago, quem dudum sub Constante militantem discordiarum sevisse causas inter priores, fratres, suspiciones contiguae veritati pulsabant, ausus paulo petulantius stare, ut ipse quoque ad parile obsequium admittendus, agnitus est et prohibitus, strepentibusque multis, et intueri lucem ulterius non debere clamantibus, ut perduellem, et obstinatum, Constantius circa haec lenior solito, “Desinite” ait “urgere hominem ut existimo sontem, sed nondum aperte convictum, et mementote quod, siquid admisit huius modi, sub obtutibus meis conscientiae ipsius sententia punietur, quam latere non poterit,” et ita discessum est.", "st": "21.6"}, {"sp": "N", "t": "Postridie ludis Circensibus idem ex adverse imperatoris (ubi consueverat) spectans, repentino clamore sublato, cum certamen opinatum emitteretur, diffractis cancellis, quibus una cum pluribus incumbebat, cunctis cum eo in vanum excussis laesisque leviter paucis, interna compage disrupta, efflasse spiritum repertus est solus, unde Constantius ut futurorum quoque praescius exsultabat.", "st": "21.6"}, {"sp": "N", "t": "Eodem tempore Faustinam nomine sortitus est coniugem, amissa iam pridem Eusebia, cuius fratres erant Eusebius et Hypatius consulares, corporis morumque pulchritudine pluribus antistante, et in culmine tam celso humana, cuius favore iustissimo exemptum periculis, declaratumque Caesarem rettulimus Iulianum.", "st": "21.6"}, {"sp": "N", "t": "Habita est eisdem diebus etiam Florentii ratio, e Galliis novitatis metu digressi, et Anatolio recens mortuo praefecto praetorio per Illyricum, ad eius mittitur locum, cumque Tauro itidem praefecto praetorio per Italiam, amplissimi suscepit insignia magistratus.", "st": "21.6"}, {"sp": "N", "t": "Parabantur nihilo minus externorum atque civilium instrumenta bellorum, et augebatur turmarum equestrium numerus, parique studio supplementa legionibus scripta sunt, indictis per provincias tirociniis, omnisque ordo et professio vexabatur, vestem armaque exhibens et tormenta, aurum quin etiam et argentum, multiplicisque rei cibariae copias, et diversa genera iumentorum.", "st": "21.6"}, {"sp": "N", "t": "Et quia a Persarum rege ad sua ob difficultatem hiberni temporis aegre contruso, reserata caeli temperie validior impetus timebatur, ad Transtigritanos reges et satrapas legati cum muneribus missi sunt amplis, monituri cunctos et hortaturi, nostra sentire, et nihil fallax temptare vel fraudulentum.", "st": "21.6"}, {"sp": "N", "t": "Ante omnia tamen Arsaces et Meribanes, Armeniae et Hiberiae reges, cultu ambitioso indumentorum emercabantur, et multiformibus donis, damna Romanis negotiis illaturi, si rebus tum etiam dubiis descivissent ad Persas.", "st": "21.6"}, {"sp": "N", "t": "Inter tot urgentia, Hermogene defuncto, ad praefecturam promovetur Helpidius, ortus in Paphlagonia, aspectu vilis et lingua, sed simplicioris ingenii, incruentus et mitis, adeo ut cum ei coram innocentem quendam torquere Constantius praecepisset, aequo animo abrogari sibi potestatem oraret, haecque potioribus aliis ex sententia principis agenda permitti.", "st": "21.6"}, {"sp": "N", "t": "Rigore itaque instantium negotiorum anceps Constantius, quid capesseret ambigebat, diu multumque anxius, utrum Iulianum peteret et longinqua, an Parthos repelleret, iam transituros (ut minabantur) Euphratem, haerensque tandem cum ducibus communicato saepe consilio, in id flexus est, ut finito propiore bello vel certe mollito, nullo post terga relicto quem formidaret, Illyriis percursis et Italia (ut rebatur), Iulianum inter exordia ipsa coeptorum tamquam praedam venaticiam caperet. Hoc enim ad leniendum suorum metum subinde praedicabat.", "st": "21.7"}, {"sp": "N", "t": "Tamen ne intepesceret, aut omisisse belli videretur aliud latus, adventus sui terrorem ubique dispergens, veritusque ne Africa absente eo perrumperetur, ad omnes casus principibus opportuna, velut finibus Orientis egressurus, per mare notarium misit Gaudentium, quem exploratorem actuum Iuliani per Gallias aliquamdiu fuisse praestrinximus.", "st": "21.7"}, {"sp": "N", "t": "Hunc enim obsequio celeri cuncta consideratione gemina efficere posse sperabat, quod adversam partem metueret offensam et properaret, nanctus hanc opportunitatem commendari Constantio, quem credebat procul dubio fore victorem: nemo enim omnium tunc ab hac constanti sententia discrepabat.", "st": "21.7"}, {"sp": "N", "t": "Qui cum eo venisset, mandatorum principis memor, per litteras Cretione comite quid ageretur edocto, reliquisque rectoribus, lecto undique milite fortiore, translatisque ab utraque Mauritania discursatoribus expeditis, Aquitaniae et Italiae obiecta litora tuebatur artissime.", "st": "21.7"}, {"sp": "N", "t": "Neque id consilium fefellit Constantium. Eo enim superstite nullus adversorum illas tetigit terras, licet oram Siciliensem a Lilybaeo protentam ad Pachynum multitudo servabat armata, si patuisset facultas, ocius transitura.", "st": "21.7"}, {"sp": "N", "t": "His pro rerum ratione, ut sibi prodesse existimabat Constantius, aliisque minutis et levioribus ordinatis, ducum nuntiis docebatur et litteris, Persarum copias in unum coactas, rege turgido praeeunte, iam prope margines tendere Tigridis, incertum quonam erumpere cogitantes.", "st": "21.7"}, {"sp": "N", "t": "Quibus percitus, ut propius agens, futuros possit antevenire conatus, quam primum hibernis egressus, accito undique equitatu, peditumque robore, quo fidebat, per Capersanam Euphrate navali ponte transcurso Edessam petit, uberem commeatibus et munitam, ibi parumper operiens, dum exploratores aut perfugae motum castrorum hostilium indicarent.", "st": "21.7"}, {"sp": "N", "t": "Discedens inter haec Iulianus a Rauracis, peractis quae docuimus dudum, Sallustium praefectum promotum remisit in Gallias, Germaniano iusso vicem tueri Nebridii, itidemque Nevittae magisterium commisit armorum, Gumoarium proditorem antiquum timens, quem cum Scutarios ageret, latenter prodidisse Veteranionem suum principem audiebat; et Iovio quaesturam, cuius in actibus Magnenti meminimus, et Mamertino largitiones curandas, et Dagalaifum praefecit domesticis, aliosque plures ex arbitrio suo militibus regendis apposuit, quorum merita norat et fidem.", "st": "21.8"}, {"sp": "N", "t": "Profecturus itaque per Marcianas silvas viasque iunctas Histri fluminis ripis, inter subita vehementer incertus, id verebatur, ne contemptus ut comitantibus paucis, multitudinem offenderet repugnantem.", "st": "21.8"}, {"sp": "N", "t": "Quod ne fieret consilio sollerti praevidit, et agminibus distributis, per itinera Italiae nota quosdam properaturos cum Iovino misit et Iovio, alios per mediterranea Raetiarum magistro equitum Nevittae commissos, quo diffusi per varia, opinionem numeri praeberent immensi, formidineque cuncta complerent. Id enim et Alexander Magnus, et deinde alii plures, negotio ita poscente, periti fecere ductores.", "st": "21.8"}, {"sp": "N", "t": "Mandabat tamen egressis, ut tamquam hoste protinus occursuro, tutius graderentur, stationesque nocturnas agerent et vigilias, ne improviso hostium invaderentur excursu.", "st": "21.8"}, {"sp": "N", "t": "Quibus ita (ut videbatur) apte dispositis, more quo tractus perruperat saepe barbaricos, contextis successibus fidens, porrectius ire pergebat.", "st": "21.9"}, {"sp": "N", "t": "Cumque ad locum venisset, unde navigari posse didicit flumen, lembis escensis, quos opportune fors dederat plurimos, per alveum, quantum fieri potuit, ferebatur occulte, ideo latens, quod toleranter et fortiter, nullius cibi indigens mundioris, sed paucis contentus et vilibus, oppida forinsecus transibat et castra, imitatus egregium illud Cyri veteris dictum, qui cum delatus ad hospitem interrogaretur ab eo, quid ad convivium parari deberet, panem responderat solum: sperare enim aiebat, prope rivum se cenaturum.", "st": "21.9"}, {"sp": "N", "t": "Fama vero, quae mille, ut aiunt, linguis rerum mire exaggerat fidem, per Illyrios omnes celebrior fundebatur, Iulianum strata per Gallias multitudine regum et gentium numeroso exercitu, et successibus tumidum variis, adventare.", "st": "21.9"}, {"sp": "N", "t": "Quo rumore perculsus, praefectus praetorio Taurus, ut hostem vitans externum, mature discessit, vectusque mutatione celeri publici cursus, transitis Alpibus Iuliis, eodem ictu Florentium itidem praefectum secum abduxit.", "st": "21.9"}, {"sp": "N", "t": "Levibus tamen indiciis super Iuliani motu Lucillianus percitus comes, qui per illas regiones rem curabat ea tempestate castrensem, agensque apud Sirmium milites congregans, quos ex stationibus propinquis acciri celeritatis ratio permittebat, venture resistere cogitabat.", "st": "21.9"}, {"sp": "N", "t": "Sed ille ut fax vel incensus malleolus, volucriter ad destinata festinans, cum venisset Bononeam, a Sirmio miliario nono disparatam et decimo, senescente luna ideoque obscurante noctis maximam partem, e navi exsiluit improvisus, statimque Dagalaifum misit cum expeditis ad Lucillianum vocandum, trahendumque si resistere niteretur.", "st": "21.9"}, {"sp": "N", "t": "Qui tum etiam quiescens, cum strepitu excitatus turbulento vidisset ignotorum hominum se circulo circumsaeptum, concepto negotio, et imperatorii nominis metu praestrictus, praeceptis paruit invitissimus, secutusque alienum arbitrium, magister equitum paulo ante superbus et ferox, iumentoque impositus repentino, principi ut captivus offertur ignobilis, oppressam terrore vix colligens mentem.", "st": "21.9"}, {"sp": "N", "t": "Verum cum primitus visus, adorandae purpurae datam sibi copiam advertisset, recreatus tandem suique securus, “Incaute” inquit “imperator et temere cum paucis alienis partibus te commisisti.” Cui amarum Iulianus subridens, “Haec verba prudentia serva” inquit “Constantio. Maiestatis enim insigne non ut consiliario tibi, sed ut desinas pavere porrexi.”", "st": "21.9"}, {"sp": "N", "t": "Nihil deinde amoto Lucilliano, differendum nec agendum segnius ratus, ut erat in rebus trepidis audax et confidentior, civitatem (ut praesumebat) dediticiam petens, citis passibus incedebat, eumque suburbanis propinquantem amplis nimiumque protentis, militaris et omnis generis turba, cum lumine multo et floribus, votisque faustis, Augustum appellans et dominum, duxit in regiam.", "st": "21.10"}, {"sp": "N", "t": "Ubi eventu laetus et omine, firmata spe venturorum, quod ad exemplum urbium matris populosae et celebris, per alias quoque civitates ut sidus salutare susciperetur, edito postridie curuli certamine, cum gaudio plebis, ubi lux excanduit tertia, morarum impatiens, percursis aggeribus publicis, Succos nemine auso resistere, praesidiis occupavit, eisdemque tuendis Nevittam praefecit ut fidum. Cuius loci situm excessu brevi conveniet ostendi.", "st": "21.10"}, {"sp": "N", "t": "Consertae celsorum montium summitates Haemi et Rhodopae, quorum alter ab ipsis Histri marginibus, alter ab Axii fluminis citeriore parte consurgit, in angustias tumulosis collibus desinentes, Illyrios interscindunt et Thracas, hinc vicinae mediterraneis Dacis et Serdicae, inde Thracias despectantes et Philippopolim, civitates amplas et nobiles, et tamquam natura in dicionem Romanam redigendas nationes circumsitas praenoscente, ita figuratae consuite, inter artos colles quondam hiantes obscurius, ad magnitudinem splendoremque postea rebus elatis, patefactae sunt et carpentis, aditibusque aliquotiens clausis, magnorum ducum populorumque reppulere conatus.", "st": "21.10"}, {"sp": "N", "t": "Et pars, quae Illyricum spectat, mollius edita, velut incauta, subinde superatur. Latus vero e regione oppositum Thraciis, prona humilitate deruptum, hincque et inde fragosis tramitibus impeditum difficile scanditur, etiam nullo vetante. Sub hac altitudine aggerum, utrubique spatiosa camporum planities iacet, superior ad usque Iulias Alpes extenta, inferior ita resupina et panda ut nullis habitetur obstaculis ad usque fretum et Propontidem.", "st": "21.10"}, {"sp": "N", "t": "His ut in re tali tamque urgenti compositis, magistro equitum illic relicto, imperator revertitur Naessum (copiosum oppidum), de quo impraepedite cuncta disponeret, suis utilitatibus profutura.", "st": "21.10"}, {"sp": "N", "t": "Ubi Victorem apud Sirmium visum, scriptorem historicum, exindeque venire praeceptum, Pannoniae secundae consularem praefecit, et honoravit aenea statua, virum sobrietatis gratia aemulandum, multo post urbi praefectum.", "st": "21.10"}, {"sp": "N", "t": "Iamque altius semet extollens, et numquam credens ad concordiam provocari posse Constantium, orationem acrem et invectivam, probra quaedam in eum explanantem et vitia, scripserat ad senatum. Quae cum Tertullo administrante adhuc praefecturam, recitarentur in curia, eminuit nobilitatis cum speciosa fiducia, benignitas grata. Exclamatum est enim in unum, cunctorum sententia congruente, “auctori tuo reverentiam rogamus.”", "st": "21.10"}, {"sp": "N", "t": "tunc et memoriam Constantini, ut novatoris turbatorisque priscarum legum et moris antiquitus recepti, vexavit, eum aperte incusans, quod barbaros omnium primus ad usque fasces auxerat et trabeas consulares, insulse nimirum et leviter, qui cum vitare deberet id quod infestius obiurgavit, brevi postea Mamertino in consulatu iunxit Nevittam, nec splendore nec usu nec gloria horum similem, quibus magistratum amplissimum detulerat Constantinus: contra inconsummatum et subagrestem et (quod minus erat ferendum) celsa in potestate crudelem.", "st": "21.10"}, {"sp": "N", "t": "Haec et talia cogitanti, sollicitoque super maximis rebus et seriis, nuntius metuendus intimatur et insperatus, ausa indicans quorundam immania, impeditura cursus eius ardentes, ni vigilanter haec quoque antequam adolescerent hebetasset. Quae breviter exponentur.", "st": "21.11"}, {"sp": "N", "t": "Duas legiones Constantiacas addita una sagittariorum cohorte, quas invenerat apud Sirmium, ut suspectae adhuc fidei, per speciem necessitatum urgentium misit in Gallias. Quae pigrius motae, spatiaque itinerum longa, et Germanos hostes truces et assiduos formidantes, novare quaedam moliebantur, auctore et incitatore Nigrino, equitum turmae tribuno, in Mesopotamia genito: reque digesta per secreta colloquia, et alto roborata silentio, cum Aquileiam pervenissent, uberem situ et opibus, murisque circumdatam validis, eam hostiliter repente clausere, iuvante indigena plebe tumultum horrore, cui Constanti nomen erat tum etiam iunctum.", "st": "21.11"}, {"sp": "N", "t": "Et obseratis aditibus, turribusque armatis ac propugnaculis, futurae concertationi praeparabant utilia, interim soluti et liberi, hocque facinore ita audaci, ad favendum Constanti partibus ut superstitis Italicos incolas excitabant.", "st": "21.11"}, {"sp": "N", "t": "Quibus Iulianus acceptis, agens tunc apud Naessum, nihil a tergo timens adversum, legensque et audiens hanc civitatem circumsessam quidem aliquotiens, numquam tamen excisam aut deditam, impensiore studio sibi sociare vel fraude, vel diversis adulationum generibus, antequam maius oriretur aliquid, properabat.", "st": "21.12"}, {"sp": "N", "t": "Ideoque Iovinum magistrum equitum venientem per Alpes, Noricosque ingressum, ad id quod exarserat, quoquo modo corrigendum, redire citius imperavit. Et nequid deesset, milites omnes, qui comitatum sequebantur aut signa, retineri iussit per idem oppidum transeuntes, pro viribus laturos auxilium.", "st": "21.12"}, {"sp": "N", "t": "Hisque dispositis, ipse haut diu postea cognita morte Constanti, discursis Thraciis Constantinopolim introiit: ac saepe doctus lentius fore id obsidium quam verendum, Immone cum comitibus aliis ad hoc destinato, ire monuit exinde Iovinum, alia quae potiores flagitabant necessitates, acturum.", "st": "21.12"}, {"sp": "N", "t": "Ordine itaque scutorum gemino Aquileia circumsaepta, concinentibus sententiis ducum, conveniens visum est ad deditionem allicere defensores, minacium blandorumque varietate sermonum: et multis ultro citroque dictitatis, in immensum obstinatione gliscente, ex colloquio re infecta disceditur.", "st": "21.12"}, {"sp": "N", "t": "Et quia nihil praeter pugnam exspectabatur, curatis utrubique cibo somnoque corporibus, aurora iam surgente, concrepante sonitu bucinarum, partes accensae in clades mutuas, ferocientes magis quam consultius, elatis clamoribus ferebantur.", "st": "21.12"}, {"sp": "N", "t": "Pluteos igitur prae se ferentes oppugnatores, cratesque densius textas, sensim incedentes et caute, murorum ima suffodere ferramentorum multitudine conabantur, aptas plerique vehentes ad mensuram moenium scalas, iamque parietibus paene contigui pars lapidibus volutis in pronum collisi, pars confixi stridentibus iaculis, retroque gradientes, averterunt secum omnes alios metu similium a proposito pugnandi detortos.", "st": "21.12"}, {"sp": "N", "t": "Hoc primo congressu erecti in audaciam clausi, assumpta fiducia meliorum, parvi ducebant restantia, mentibusque fundatis et compositis per opportuna tormentis, indefesso labore, vigilias et cetera subsidia securitatis implebant.", "st": "21.12"}, {"sp": "N", "t": "Contra munitores licet pavore discriminum anxii, pudore tamen ne secordes viderentur et segnes, ubi parum vis procedebat, Marte aperto temptata, ad instrumenta obsidionalium artium transtulerunt. Et quia nec arietibus admovendis, nec ad intemptandas machinas vel ut possint forari cuniculi, inveniebatur locus usquam habilis, disparatione brevi civitatem Natisone amni praeterlabente, commentum excogitatum est cum veteribus admirandum.", "st": "21.12"}, {"sp": "N", "t": "Constructas veloci studio ligneas turres, propugnaculis hostium celsiores, imposuere trigeminis navibus, valide sibi conexis, quibus insistentes armati, uno parique ardore prohibitores dispellere, collatis ex propinquo viribus, nitebantur: subterque expediti velites a turrium cavernis egressi, iniectis ponticulis, quos ante compaginarant, transgredi festinarunt indiviso negotio ut, dum vicissim missilibus se petunt et saxis utrimquesecus alte locati, hi qui transiere per pontes, nullo interpellante, aedificii parte convulsa, aditus in penetralia oppidi reserarent.", "st": "21.12"}, {"sp": "N", "t": "Verum summa coepti prudentis aliorsum evasit. Cum enim adventarent iam turres, contortis malleolis madentibus pice, harundine quin etiam, sarmentis ac vario fomite flammarum incessebantur. Quae quoniam, incendio celeri, ponderibusque trepide superstantium inclinatae, prociderunt in flumen, armatorum aliqui per earum fastigia interibant, eminus confixi tormentis.", "st": "21.12"}, {"sp": "N", "t": "Inter quae destituti pedites post navalium sociorum occasum, obtriti sunt saxis immanibus, praeter paucos quos morte scilicet per impedita suffugia, velocitas exemerat pedum. Ad ultimum certamine protracto in vesperam, datoque signo in receptum ex more, ambo digressi, diei residuum animis egere disparibus.", "st": "21.12"}, {"sp": "N", "t": "Munitorum enim maerores, funera lugentium propria, prohibitores spe iam superandi firmabant, licet ipsi quoque paucos gemebant amissos. Properabatur tamen nihilo minus, et quantum recreandis viribus quiete et cibo satis fuit tribute, per noctis integrae spatium, reparatur lucis exordio proelium, incitamento tubarum.", "st": "21.12"}, {"sp": "N", "t": "Et quidam elatis super capita scutis (ut pugnaturi levius), alii vehentes umeris ut antea scalas, ferventique impetu procurrentes, pectora multiformium telorum ictibus exponebant. Alii ferratas portarum obices effringendas adorti, ultro ignibus petebantur, vel elisi saxis muralibus oppetebant. Quidam fossam fidentius transire conati, repentinis eorum assultibus, qui erumpebant clanculo per posticas, ruebant incaute, aut saucii discedebant. Recursus enim ad moenia tutior, vallumque antemuranum caespitibus fultum, insidiantes ab omni discrimine defendebant.", "st": "21.12"}, {"sp": "N", "t": "Et quamquam prohibitores duritia bellorumque artibus antistarent, quibus nihil praeter moenium supererat adiumentum, collectus tamen ex potioribus numeris miles, diuturnas ferre nequiens moras, suburbana omnia circumibat, diligenter inquirens, qua vi vel machinis posset patefactam irrumpere civitatem.", "st": "21.12"}, {"sp": "N", "t": "Quod ubi patrare non poterat, magnitudine vetante difficultatum, obsideri remissius coepta est, et excubiis stationibusque relictis, praesidiarii milites vastantes agros propinquos, omnibus congruentibus abundabant, raptorum pleraque concorporalibus suis impertientes. Unde largiore admodum potu, saginisque distenti marcebant.", "st": "21.12"}, {"sp": "N", "t": "His relatione Immonis consortiumque cognitis, Iulianus Constantinopoli etiam tum hibernans, sollerti remedio turbatis consuluit rebus, moxque Agilonem magistrum peditum ea tempestate probe cognitum miserat, ut viso honoratissimo viro, compertaque per eum morte Constanti, solveretur obsidium.", "st": "21.12"}, {"sp": "N", "t": "Inter quae ne cessaret Aquileiae oppugnatio cum in reliquis opera consumeretur in cassum, placuit resistentes acriter ad deditionem siti compelli, et ubi aquarum ductibus intersectis, nihilo minus celsiore fiducia repugnarent, flumen laboribus avertitur magnis. Quod itidem frustra est factum. Attenuatis enim avidioribus bibendi subsidiis, hic quos temeritas clauserat, contenti putealibus aquis, parce vixerunt.", "st": "21.12"}, {"sp": "N", "t": "Quae dum agitantur casibus ante dictis, supervenit (ut praeceptum est) Agilo, scutorumque densitate contectus, prope fidenter accessit, multaque locutus et vera, quibus Constanti obitum, firmatumque Iuliani docebat imperium, sine fine conviciis confutabatur ut fallax. Nec ei quisquam credidit gesta narranti, antequam pacta salute, susceptus ad pugnaculum solus, fide religiosius reddita, ea quae docuerat, replicaret.", "st": "21.12"}, {"sp": "N", "t": "His auditis ex diuturno angore portis reclusis omnes effusi, suscepere laeti pacificum ducem, seque purgantes, Nigrinum totius furoris auctorem, paucosque alios obtulerunt, eorum supplicio laesae crimina maiestatis et urbis aerumnas expiari poscentes.", "st": "21.12"}, {"sp": "N", "t": "Paucis denique post diebus, exploratius spectato negotio, Mamertino tum iudicante, praefecto praetorio, Nigrinus ut acerrimus belli instinctor, exustus est vivus. Romulus vero post eum et Sabostius curiales, convicti, sine respectu periculi studia sevisse discordiarum, poenali consumpti sunt ferro. Residui omnes abierunt innoxii, quos ad certaminum rabiem necessitas egerat, non voluntas. Id enim aequitate pensata, statuerat placabilis imperator et clemens.", "st": "21.12"}, {"sp": "N", "t": "Et haec quidem postea gesta sunt. Iulianus vero agens etiam tum apud Naessum, curis altioribus stringebatur, multa utrimque pertimescens. Formidabat enim ne clausorum militum apud Aquileiam repentino assultu, obseratis angustiis Alpium Iuliarum, provincias et adminicula perderet, quae exinde sperabat in dies.", "st": "21.12"}, {"sp": "N", "t": "Itidemque opes Orientis magnopere verebatur audiens dispersum per Thracias militem, contra vim subitam cito coactum, adventare Succorum confinia, comite Martiano ducente. Sed tamen congrua instantium sollicitudinum moli, ipse quoque agitans efficaciter, Illyricum contrahebat exercitum, pulvere coalitum Martio, promptumque in certaminibus bellicoso iungi rectori.", "st": "21.12"}, {"sp": "N", "t": "Nec privatorum utilitates in tempore ita flagranti despiciens, litesque audiens controversas maxime municipalium ordinum, ad quorum favorem propensior, iniuste plures muneribus publicis annectebat.", "st": "21.12"}, {"sp": "N", "t": "Ibi Symmachum repertum et Maximum, senatores conspicuos, a nobilitate legatos ad Constantium missos, exinde reversos honorifice vidit, et potiore posthabito, in locum Tertulli Maximum urbi praefecit aeternae, ad Rufini Vulcatii gratiam, cuius sororis eum filium norat. Hoc administrante alimentaria res abundavit et querellae plebis excitari crebro solitae cessaverunt.", "st": "21.12"}, {"sp": "N", "t": "tunc ut et securitatem trepidis rebus afferret, et obedientium nutriret fiduciam, Mamertinum promotum praefectum praetorio per Illyricum designavit consulem et Nevittam, qui nuper ut primum augendae barbaricae vilitatis auctorem, immoderate notaverat Constantinum.", "st": "21.12"}, {"sp": "N", "t": "His ac talibus eo inter spem metumque nova negotia commovente, Constantius apud Edessam exploratorum relationibus variis anxius, in rationes diducebatur ancipites, nunc ad concursatorias pugnas militem struens, nunc si copia patuisset, obsidione gemina Bezabden aggressurus, consultans prudenter, ne mox partes petiturus arctoas, improtectum Mesopotamiae relinqueret latus.", "st": "21.13"}, {"sp": "N", "t": "Verum consiliorum ambiguum retinebant multiplices morae, tardante trans Tigridem rege, dum moveri permitterent sacra. Nam si permeate flumine nullum qui resisteret invenisset, absque difficultate penetrarat Euphratem; alioqui ad civilia bella custodiens militem, timebat eum periculis obiectare circummuranis, firmitatem moenium munimenti, defensorumque alacritatem expertus.", "st": "21.13"}, {"sp": "N", "t": "Ne quiesceret tamen, neve condemnaretur inertiae, Arbitionem et Agilonem, equestris pedestrisque militiae magistros, cum agminibus maximis properare coegit, non ut lacesserent Persas in proelia, sed praetenturis iuncturos citeriores Tigridis ripas, et speculaturos quonam rex erumperet violentus. Addebatque monendo saepius et scribendo, ut si multitudo transire coepisset hostilis, referrent citius pedem.", "st": "21.13"}, {"sp": "N", "t": "Dumque collimitia iussa custodiunt duces, et occulta fallacissimae gentis observantur, agens ipse cum parte validiori exercitus, curabat urgentia (velut pugnaturus) oppidaque tuebatur excursu. Speculatores vero et transfugae subinde venientes, repugnantia prodebant, ideo futurorum incerti, quod apud Persas nemo consiliorum est conscius, praeter optimates taciturnos et fidos, apud quos Silentii quoque colitur numen.", "st": "21.13"}, {"sp": "N", "t": "Accersebatur autem a memoratis ducibus imperator assidue, orantibus ferri sibi suppetias. Testabantur enim se non nisi coactis in unum viribus cunctis, posse impetum regis ardentissimi sustinere.", "st": "21.13"}, {"sp": "N", "t": "Quae dum aguntur ita sollicite, nuntii percrebuere certissimi, quorum clara fide compertum est, Iulianum Italiam et Illyricum cursu celeri praetergressum, claustra interim occupasse Succorum, accita undique praestolantem auxilia, ut multitudine stipatus armorum pervaderet Thracias.", "st": "21.13"}, {"sp": "N", "t": "Quo cognito, maerore offusus Constantius, solacio uno sustentabatur, quod intestinos semper superaverit motus; re tamen magnam ei difficultatem ad capessendum consilium afferente, id elegit potissimum, ut vehiculis publicis impositum paulatim praemitteret militem, imminentis casus atrocitati velocius occursurum.", "st": "21.13"}, {"sp": "N", "t": "Omniumque consensu hac probata sententia, pergebant (ut praeceptum est), expediti. Eique haec disponenti, luce postera nuntiatur, regem cum omni manu quam duxerat, ad propria revertisse, auspiciis dirimentibus, lenitoque metu, revocatis omnibus praeter eos quos consuetudo praesidio Mesopotamiae destinarat, confestim reversus est Nicopolim urbem.", "st": "21.13"}, {"sp": "N", "t": "Summa itaque coeptorum quorsum evaderet ambigens, cum in unum exercitus convenisset, omnes centurias et manipulos et cohortes in contionem vocavit, concinentibus tubis, oppletoque multitudinis campo, ut eam ad firmanda promptius adigeret imperanda, tribunali celso insistens, stipatusque solito densius, haec prosecutus est, ad serenitatis speciem et fiduciae vultu formato:", "st": "21.13"}, {"sp": "N", "t": "“Sollicitus semper nequid re levi vel verbo committam, inculpatae parum congruens honestati, utque cautus navigandi magister, clavos pro fluctuum motibus erigens vel inclinans, compellor nunc apud vos, amantissimi viri, confiteri meos errores, quin potius (si dici liceat verum) humanitatem, quam credidi negotiis communibus profuturam. Proinde ut sciri facilius possit, quae sit huius concilii convocandi materia, accipite quaeso aequis auribus et secundis.", "st": "21.13"}, {"sp": "N", "t": "“Gallum patruelem meum tempore quo confundendis rebus pertinaciter Magnentius inhaerebat, quem obruere vestrae virtutes, potestate Caesaris sublimatum, ad Orientis praesidium misi. Qui cum a iustitia per multa visu relatuque nefaria defecisset, arbitrio punitus est legum.", "st": "21.13"}, {"sp": "N", "t": "“Atque utinam hoc contenta fuisset Invidia, turbarum acerrima concitatrix, ut angat nos una sed secura doloris praeteriti recordatio. At nunc aliud accidit, ausim dicere praeteritis maestius, quod per fortitudinem vobis ingenitam, adiumenta caelestia coercebunt.", "st": "21.13"}, {"sp": "N", "t": "“Iulianus, quem dum circumfrementes Illyricum nationes exteras oppugnatis, tuendis praefecimus Galliis, levium confidentia proeliorum, quae cum Germanis gessit semermibus, ut vecors elatus, adscitis in societatem superbam auxiliaribus paucis, feritate speque postrema, ad perniciosam audaciam promptis, in noxam publicam conspiravit, aequitate calcata, parente nutriceque orbis Romani, quam tumentes spiritus tamquam favillas reflaturam vindicaturamque, deinde ut sceleste factorum ultricem, et ipse expertus, et docente antiquitate facile credo.", "st": "21.13"}, {"sp": "N", "t": "“Quid igitur superest, nisi ut turbinibus excitis occurramus, subcrescentis rabiem belli, antequam pubescat validius, celeritatis remediis oppressuri? Nec enim dubium, favore numinis summi praesente, cuius perenni suffragio damnantur ingrati, ferrum impie praeparatum ad eorum interitum esse vertendum, qui non lacessiti, sed aucti beneficiis pluribus, ad insontium pericula surrexerunt.", "st": "21.13"}, {"sp": "N", "t": "“Ut enim mea mens augurat Iustitiaque rectis consiliis adfutura promittit, spondeo quod, si ventum fuerit comminus, ita pavore torpescent, ut nec oculorum vestrorum vibratae lucis ardorem, nec barritus sonum perferant primum.”", "st": "21.13"}, {"sp": "N", "t": "Omnes post haec dicta in sententiam ducti suam hastasque vibrantes irati, post multa quae benivole responderant, petebant duci se protinus in rebellem. Qua gratia in laetitiam imperator versus ex metu, contione mox absoluta, Arbitionem ante alios faustum ad intestina bella sedanda, ex ante actis iam sciens, iter suum praeire cum Lanceariis et Mattiariis, et catervis expeditorum praecepit, et cum Laetis itidem Gomoarium, venturis in Succorum angustiis opponendum, ea re aliis antelatum, quod ut contemptus in Galliis erat Iuliano infestus.", "st": "21.13"}, {"sp": "N", "t": "In hoc rerum adversarum tumultu, haerens eius fortuna iam et subsistens, adventare casum vitae difficilem, modo non loquentibus signis aperte monstrabat. Namque et nocturnis imaginibus terrebatur, et nondum penitus mersus in somnum, umbram viderat patris obtulisse pulchrum infantem, eumque susceptum et locatum in gremio suo, excussam sibi proiecisse longius sphaeram, quam ipse dextera manu gestabat. Id autem permutationem temporum indicabat, licet interpretantes placentia responderent.", "st": "21.14"}, {"sp": "N", "t": "Post haec confessus est iunctioribus proximis, quod tamquam desolatus, secretum aliquid videre desierit, quod interdum adfuisse sibi squalidius aestimabat, et putabatur genius esse quidam, tutelae salutis appositus, eum reliquisse mundo citius digressurum.", "st": "21.14"}, {"sp": "N", "t": "Ferunt enim theologi in lucem editis hominibus cunctis, salva firmitate fatali, huius modi quaedam velut actus rectura numina sociari, admodum tamen paucissimis visa, quos multiplices auxere virtutes.", "st": "21.14"}, {"sp": "N", "t": "Idque et oracula et auctores docuere praeclari. Inter quos est etiam Menander comicus, apud quem hi senarii duo leguntur:<br>ἅπαντι δαίμων ἀνδρὶ συμπαρίσταται<br>εὐθὺς γενομένῳ, μυσταγωγὸς τοῦ βίου.", "st": "21.14"}, {"sp": "N", "t": "Itidem ex sempiternis Homeri carminibus intellegi datur, non deos caelestes cum viris fortibus collocutos, nec adfuisse pugnantibus vel iuvisse, sed familiaris genios cum eisdem versatos, quorum adminiculis freti praecipuis, Pythagoras enituisse dicitur et Socrates, Numaque Pompilius, et superior Scipio et (ut quidam existimant) Marius et Octavianus, cui Augusti vocabulum delatum est primo, Hermesque Termaximus, et Tyaneus Apollonius atque Plotinus, ausus quaedam super hac re disserere mystica, alteque monstrare, quibus primordiis hi genii animis conexi mortalium eas tamquam gremiis suis susceptas tuentur (quoad licitum est) docentique maiora, si senserint puras et a colluvione peccandi, immaculata corporis societate discretas.", "st": "21.14"}, {"sp": "N", "t": "Ingressus itaque Antiochiam festinando Constantius, ad motum certaminum civilium (ut solebat), avide surrecturus, paratis omnibus exire properabat immodice, renitentibus plurimis murmure tenus. Nec enim dissuadere palam audebat quisquam vel vetare.", "st": "21.15"}, {"sp": "N", "t": "Autumno iam senescente profectus, cum ad suburbanum venisset, disiunctum exinde tertio lapide, Hippocephalum nomine, lucente iam die, cadaver hominis interfecti, dextra iacens capite avulso conspexit, contra occiduum latus extensum: territusque omine, finem parantibus fatis, destinatius ipse tendebat, venitque Tarsum, ubi leviore febri contactus, ratusque itinerario motu imminutae valetudinis excuti posse discrimen, petit per vias difficiles Mobsucrenas, Ciliciae ultimam hinc pergentibus stationem, sub Tauri montis radicibus positam, egredique secuto die conatus, illabente morbi gravitate detentus est: paulatimque urente calore nimio venas, ut ne tangi quidem corpus eius posset, in modum foculi fervens, cum usus deficeret medelarum, ultimum spirans, deflebat exitium, mentisque sensu tum etiam integro, successorem suae potestatis statuisse dicitur Iulianum.", "st": "21.15"}, {"sp": "N", "t": "Deinde anhelitu iam pulsante letali, conticuit, diuque cum anima colluctatus iam discessura, abiit e vita tertium nonarum Octobrium, imperii tricesimo octavo vitaeque anno quadragesimo quarto et mensibus paucis.", "st": "21.15"}, {"sp": "N", "t": "Post quae, supremis cum gemitu conclamatis, excitisque lamentis et luctu, deliberabant locum obtinentes in aula regia primum, quid agerent quidve moliri deberent: paucisque occulte super eligendo imperatore temptatis, incitante (ut ferebatur) Eusebio, quem noxarum conscientia stimulabat, cum novandis rebus imminens obsisteret Iulianus, mittuntur ad eum Theolaifus et Aligildus tunc comites, mortem indicantes propinqui, et oraturi, ut mora omni depulsa, ad obtinendum obtemperare sibi paratum, tenderet Orientem.", "st": "21.15"}, {"sp": "N", "t": "Fama tamen rumorque loquebatur incertus, Constantium voluntatem ordinasse postremam, in qua Iulianum (ut praediximus) scripsit heredem, et his quos diligebat, fidei commissa detulit et legata.", "st": "21.15"}, {"sp": "N", "t": "Uxorem autem praegnantem reliquit, unde edita postuma eiusque nomine appellata, cum adolevisset, matrimonii iure copulata est Gratiano.", "st": "21.15"}, {"sp": "N", "t": "Bonorum igitur vitiorumque eius differentia vere servata, praecipua prima conveniet expediri. Imperatoriae auctoritatis cothurnum ubique custodiens, popularitatem elato animo contemnebat et magno, erga tribuendas celsiores dignitates impendio parcus, nihil circa administrationum augmenta praeter pauca novari perpessus, numquam erigens cornua militarium.", "st": "21.16"}, {"sp": "N", "t": "Nec sub eo dux quisquam cum clarissimatu provectus est. Erant enim (ut nos quoque meminimus), perfectissimi: nec occurrebat magistro equitum provinciae rector nec contingi ab eo civile negotium permittebat. Sed cunctae castrenses et ordinariae potestates, ut honorum omnium apicem, priscae reverentiae more, praefectos semper suspexere praetorio.", "st": "21.16"}, {"sp": "N", "t": "In conservando milite nimium cautus, examinator meritorum non numquam subscruposus, palatinas dignitates velut ex quodam tribuens perpendiculo, et sub eo nemo celsum aliquid acturus, in regia repentinus adhibitus est vel incognitus, sed qui post decennium officiorum magisterium vel largitiones vel simile quicquam esset recturus, apertissime noscebatur. Valdeque raro contigerat, ut militarium aliquis ad civilia regenda transiret, contraque non nisi pulvere bellico indurati, praeficiebantur armatis.", "st": "21.16"}, {"sp": "N", "t": "Doctrinarum diligens affectator, sed cum a rhetorice per ingenium desereretur obtunsum, ad versificandum transgressus, nihil operae pretium fecit.", "st": "21.16"}, {"sp": "N", "t": "In vita parca et sobria, edendi potandique moderatione, valetudinem ita retinuit firmam, ut raros colligeret morbos, sed eos non procul a vitae periculis: id enim evenire corporibus a lascivia dimotis et luxu, diuturna experimenta et professiones medendi monstrarunt.", "st": "21.16"}, {"sp": "N", "t": "Somno contentus exiguo, cum id posceret tempus et ratio, perque spatia vitae longissima impendio castus, ut nec malivolo citerioris vitae ministro saltem suspicione tenus posset redargui, quod crimen etiam si non invenit, malignitas fingit, in summarum licentia potestatum.", "st": "21.16"}, {"sp": "N", "t": "Equitandi et iaculandi, maximeque perite dirigendi sagittas, artiumque armaturae pedestris perquam scientissimus. Quod autem nec os tersisse umquam vel nares in publico, nec spuisse, nec transtulisse in partem alterutram vultum aliquando est visus, nec pomorum quoad vixerat gustaverit (ut dicta saepius) praetermitto.", "st": "21.16"}, {"sp": "N", "t": "Dinumeratis carptim bonis, quae scire potuimus, nunc ad explananda eius vitia veniamus. Cum esset in negotiis aliis principibus mediis comparandus, si affectatae dominationis amplam quandam falsam repperisset aut levem, hanc sine fine scrutando, fasque eodem loco ducens et nefas, Caligulae et Domitiani et Commodi immanitatem facile superabat, quorum aemulatus saevitiam inter imperandi exordia, cunctos sanguine et genere se contingentes, stirpitus interemit.", "st": "21.16"}, {"sp": "N", "t": "Addebatur miserorum aerumnis, qui rei maiestatis imminutae vel laesae deferebantur, acerbitas eius et iracundia suspicionesque in huius modi cuncta distentae. Et siquid tale increpuisset, in quaestiones acrius exsurgens quam civiliter, spectatores apponebat his litibus truces, mortemque longius in puniendis quibusdam, si natura permitteret, conabatur extendi, in eius modi controversiarum partibus etiam Gallieno ferocior.", "st": "21.16"}, {"sp": "N", "t": "Ille enim perduellionum crebris verisque appetitus insidiis, Aureoli et Postumi et Ingenui et Valentis, cognomento Thessalonici, aliorumque plurium, mortem factura crimina aliquotiens lenius vindicabat: hic etiam ficta vel dubia, adigebat videri certissima, vi nimia tormentorum.", "st": "21.16"}, {"sp": "N", "t": "iustumque in eius modi titulis capitali odio oderat, cum maxime id ageret ut iustus aestimaretur et clemens. Et tamquam ex arida silva volantes scintillae, flatu leni ventorum, ad usque discrimina vicorum agrestium incohibili cursu perveniunt, ita ille quoque ex minimis causis, malorum congeries excitabat, Marci illius dissimilis principis verecundi, qui cum ad imperiale culmen in Syria Cassius surrexisset, epistularum fascem ab eo ad conscios missum, perlatore capto sibi oblatum, ilico signatum exuri praecepit, agens adhuc in Illyrico, ne insidiatoribus cognitis, invitus quosdam habere posset offensos.", "st": "21.16"}, {"sp": "N", "t": "Utque recte sentientes quidam arbitrabantur, virtutis erat potius indicium magnum, imperio eundem Constantium sine cruore cessisse, quam vindicasse tam inclementer.", "st": "21.16"}, {"sp": "N", "t": "Ut Tullius quoque docet, crudelitatis increpans Caesarem, in quadam ad Nepotem epistula: “Neque enim quicquam aliud est felicitas” inquit “nisi honestarum rerum prosperitas. Vel ut alio modo definiam: felicitas est fortuna adiutrix consiliorum bonorum, quibus qui non utitur, felix esse nullo pacto potest. Ergo in perditis impiisque consiliis, quibus Caesar usus est, nulla potuit esse felicitas. Feliciorque meo iudicio Camillus exsulans quam temporibus eisdem Manlius, etiam si (id quod cupierat) regnare potuisset.”", "st": "21.16"}, {"sp": "N", "t": "Id Ephesius quoque Heraclitus asserens monet, ab inertibus et ignavis, eventus variante fortuna, superatos aliquotiens viros fuisse praestantes; illud vero eminere inter praecipuas laudes, cum potestas, in gradu, velut sub iugum missa nocendi saeviendi cupiditate et irascendi, in arce victoris animi tropaeum erexerit gloriosum.", "st": "21.16"}, {"sp": "N", "t": "Ut autem in externis bellis hie princeps fuit saucius et afflictus, ita prospere succedentibus pugnis civilibus tumidus, et intestinis ulceribus rei publicae sanie perfusus horrenda: quo pravo proposito magis quam recto vel usitato, triumphalis arcus ex clade provinciarum sumptibus magnis erexit in Galliis et Pannoniis, titulis gestorum affixis, se (quoad stare poterunt monumenta) lecturis.", "st": "21.16"}, {"sp": "N", "t": "Uxoribus et spadonum gracilentis vocibus et palatinis quibusdam nimium quantum addictus, ad singula eius verba plaudentibus, et quid ille aiat aut neget (ut assentiri possint) observantibus.", "st": "21.16"}, {"sp": "N", "t": "Augebat etiam amaritudinem temporum, flagitatorum rapacitas inexpleta, plus odiorum ei quam pecuniae conferentium. Hocque multis intolerantius videbatur, quod nec causam aliquando audivit, nec provinciarum indemnitati prospexit, cum multiplicatis tributis et vectigalibus vexarentur. Eratque super his adimere facilis quae donabat.", "st": "21.16"}, {"sp": "N", "t": "Christianam religionem absolutam et simplicem anili superstitione confundens, in qua scrutanda perplexius quam componenda gravius excitavit discidia plurima, quae progressa fusius aluit concertatione verborum, ut catervis antistitum iumentis publicis ultro citroque discurrentibus per synodos (quas appellant), dum ritum omnem ad suum trahere conatur arbitrium, rei vehiculariae succideret nervos.", "st": "21.16"}, {"sp": "N", "t": "Figura tali situque membrorum: subniger, luce oculorum edita, cernensque acutum, molli capillo, rasis assidue genis lucentibus ad decorem, usque ad pubem ab ipsis colli confinis longior, brevissimis cruribus et incurvis, unde saltu valebat et cursu.", "st": "21.16"}, {"sp": "N", "t": "Pollinctum igitur corpus defuncti, conditumque in loculis, Iovianus etiam tum protector domesticus, cum regia prosequi pompa, Constantinopolim usque iussus est, prope necessitudines eius humandum.", "st": "21.16"}, {"sp": "N", "t": "Eique vehiculo insidenti, quod portabat reliquias, ut principibus solet, annonae militaris offerebantur indicia (ut ipsi nominant “probae”) et animalia publica monstrabantur, et ex usu crebrescebant occursus, quae et alia horum similia eidem Ioviano imperium quidem sed et cassum et umbratile (ut ministro rerum funebrium) portendebant.", "st": "21.16"}, {"sp": "HDR", "t": "Liber XXII", "st": "22"}, {"sp": "N", "t": "Dum haec in diversa parte terrarum, Fortunae struunt volubiles casus, Iulianus inter multa, quae per Illyricum agitabat, exta rimabatur assidue, avesque suspiciens, praescire festinabat accidentium finem, sed responsis ambiguis et obscuris haerebat, futurorum incertus.", "st": "22.1"}, {"sp": "N", "t": "Eique tandem aruspicinae peritus, Aprunculis Gallus orator, promotus rector postea Narbonensis, nuntiavit eventus, inspectu iecoris (ut aiebat ipse) praedoctus, quod operimento duplici viderat tectum. Cumque ille timeret, ne cupiditati suae congruentia fingerentur, eratque ideo maestus, omen multo praesentius ipse conspexit, quod excessum Constantii dare monstrabat. Eodem enim puncto quo idem obierat in Cilicia, lapso milite qui se insessurum equo dextra manu erexit, humique prostrate, exclamavit ilico audientibus multis, cecidisse qui eum ad culmen extulerat celsum.", "st": "22.1"}, {"sp": "N", "t": "Et quamquam haec laetifica sciret, velut fixa tamen firmitate consistens, intra terminos Daciae se continebat, sic quoque plurima pertimescens. Nec enim cautum ducebat, coniecturis credere forsitan in contrarium erupturis.", "st": "22.1"}, {"sp": "N", "t": "Inter quae tam suspensa advenere subito missi ad eum legati Theolaifus atque Aligildus, defunctum Constantium nuntiantes, addentesque quod eum voce suprema successorem suae fecerit potestatis.", "st": "22.2"}, {"sp": "N", "t": "Qua re cognita post exemptos periculorum aestus et bellicarum sollicitudinum turbas, in immensum elatus, iamque vaticiniis credens, et celeritatem negotiis suis aliquotiens profuisse expertus, edixit iter in Thracias, motisque propere signis, emensa declivitate Succorum Philippopolim petit, Eumolpiada veterem, alacri gradu sequentibus quos duxerat cunctis.", "st": "22.2"}, {"sp": "N", "t": "Advertebant enim imperium, quod ereptum ibant cum ultimorum metu discriminum, praeter spem ordinario iure concessum. Utque solet fama novitates augere, properabat exinde sublimior, uti quodam Triptolemi curru, quem ob rapidos circumgressus, aeriis serpentibus et pinnigeris fabulosa vetustas imponit: perque terras et maria formidatus, nullis obstantibus moris, Heracleam ingressus est Perinthum.", "st": "22.2"}, {"sp": "N", "t": "Quo apud Constantinopolim mox comperto, effundebatur aetas omnis et sexus, tamquam demissum aliquem visura de caelo. Exceptus igitur tertium Iduum Decembrium verecundis senatus officiis, et popularium consonis plausibus, stipatusque armatorum et togatorum agminibus, velut acie ducebatur instructa, omnium oculis in eum non modo contuitu destinato, sed cum admiratione magna defixis.", "st": "22.2"}, {"sp": "N", "t": "Somnio enim propius videbatur adultum adhuc iuvenem, exiguo corpore, factis praestantem ingentibus, post cruentos exitus regum et gentium, ab urbe in urbem inopina velocitate transgressum, quaqua incederet accessione opum et virium, famae instar cuncta facilius occupasse, principatum denique deferente nutu caelesti, absque ulla publicae rei suscepisse iactura.", "st": "22.2"}, {"sp": "N", "t": "Brevi deinde Secundo Salutio, promoto praefecto praetorio, summam quaestionum agitandarum ut fido commisit: Mamertino et Arbitione et Agilone atque Nevitta adiunctis, itidemque Iovino magistro equitum per Illyricum recens provecto.", "st": "22.3"}, {"sp": "N", "t": "Qui omnes transgressi Chalcedona, praesentibus Iovianorum Herculianorumque principiis et tribunis, causas vehementius aequo bonoque spectaverunt, praeter paucas ubi veritas reos nocentissimos offerebat.", "st": "22.3"}, {"sp": "N", "t": "Et Palladium primum ex magistro officiorum in Brittannos exterminarunt, suspicione tenus insimulatum, quaedam in Gallum composuisse apud Constantium, dum sub eodem Caesare officiorum esset magister.", "st": "22.3"}, {"sp": "N", "t": "Dein Taurum ex praefecto praetorio in exilium egere Vercellum, cuius factum apud iudices iustorum iniustorumque distinctores, videri potuit veniae dignum. Quid enim deliquit, si ortum turbinem veritus, ad tutelam principis sui confugit? Et acta super eo gesta non sine magno legebantur horrore, cum id voluminis publici contineret exordium: “Consulatu Tauri et Florenti, inducto sub praeconibus Tauro.”", "st": "22.3"}, {"sp": "N", "t": "Ad exitium itidem tale Pentadius trahebatur, cui id obiectum est, quod a Constantio missus, notis excepit, quae propinquante pernicie, super multis interrogatus, responderat Gallus. Sed cum se iuste defenderet, tandem abiit innoxius.", "st": "22.3"}, {"sp": "N", "t": "Iniquitate simili Florentius tunc magister officiorum (Nigriniani filius) contrusus est in insulam Delmatiam Boas. Alter enim Florentius, ex praefecto praetorio consul etiamtum, rerum mutatione subita territus, cum coniuge periculis exemptus, diu delituit, nec redire ante mortem potuit Iuliani, capitis crimine tamen damnatus est absens.", "st": "22.3"}, {"sp": "N", "t": "Pari sorte Euagrius comes rei privatae, et Saturninus ex cura palatii, et Cyrinus ex notario, portati sunt in exilium. Ursuli vero necem largitionum comitis ipsa mihi videtur flesse Iustitia, imperatorem arguens ut ingratum. Cum enim Caesar in partes mitteretur occiduas, omni tenacitate stringendus, nullaque potestate militi quicquam donandi delata, ut pateret ad motus asperiores exercitus, hic idem Ursulus datis litteris ad eum qui Gallicanos tuebatur thesauros, quicquid posceret Caesar, procul dubio iusserat dari.", "st": "22.3"}, {"sp": "N", "t": "Quo exstincto cum maledictis execrationibusque multorum se Iulianus sentiret expositum, impurgabile crimen excusari posse existimans, absque conscientia sua hominem affirmabat occisum, praetendens quod eum militaris ira delevit, memor quae dixerat (ut ante rettulimus), cum Amidam vidisset excisam.", "st": "22.3"}, {"sp": "N", "t": "Ideoque timidus videbatur, vel parum intellegens quid conveniret, cum Arbitionem semper ambiguum et praetumidum his quaestionibus praefecisset, aliis specie tenus cum principiis legionum praesentibus, quem primum omnium saluti suae norat obiectum, ut decuit victoriarum civilium participem fortem.", "st": "22.3"}, {"sp": "N", "t": "Et quamquam haec quae retulimus, eius displicuere fautoribus, sequentia tamen severitatis recto vigore sunt gesta.", "st": "22.3"}, {"sp": "N", "t": "Apodemium enim ex agente in rebus, quem in Silvani necem et Galli, effrenatius arsisse docuimus, Paulumque notarium cognomento Catenam, cum multorum gemitu nominandum, vivos exustos, qui sperari debuit oppressit eventus.", "st": "22.3"}, {"sp": "N", "t": "Eusebium super his, cui erat Constantiani thalami cura commissa, alte spirantem et dirum, addixere iudices poenae letali, quem ab ima sorte ad usque iubendum imperatoria paene elatum, ideoque intolerabilem, humanorum spectatrix Adrastia aurem (quod dicitur) vellens, monensque ut castigatius viveret, reluctantem, praecipitem tamquam e rupe quadam egit excelsa.", "st": "22.3"}, {"sp": "N", "t": "Conversus post haec princeps ad palatinos, omnes omnino qui sunt quique esse possunt removit non ut philosophus veritatis indagandae professor.", "st": "22.4"}, {"sp": "N", "t": "Laudari enim poterat, si saltem moderatos quosdam licet paucos retinuisset, morumque probitate compertos. Namque fatendum est, pleramque eorum partem vitiorum omnium seminarium effusius aluisse, ita ut rem publicam infecerint cupiditatibus pravis, plusque exemplis, quam peccandi licentia, laederent multos.", "st": "22.4"}, {"sp": "N", "t": "Pasti enim ex his quidam templorum spoliis et lucra ex omni odorantes occasione, ab egestate infima ad saltum sublati divitiarum ingentium nec largiendi nec rapiendi nec absumendi tenuere aliquem modum, aliena invadere semper assuefacti.", "st": "22.4"}, {"sp": "N", "t": "Unde fluxioris vitae initia pullularunt, et periuria, et nullus existimationis respectus, demensque superbia fidem suam probrosis quaestibus polluebat.", "st": "22.4"}, {"sp": "N", "t": "Inter quae ingluvies et gurgites crevere praerupti conviviorum, et pro victorialibus epulares triumphi, ususque abundantes serici et textiles auctae sunt artes, et culinarum sollicitior cura, et ambitiosa ornatarum domorum exquisita sunt spatia, quorum mensuram si in agris consul Quinctius possedisset, amiserat etiam post dictaturam gloriam paupertatis.", "st": "22.4"}, {"sp": "N", "t": "Quibus tam maculosis accessere flagitia disciplinae castrensis, cum miles cantilenas meditaretur, pro iubilo molliores: et non saxa (ut erant antehac) armato cubile, sed pluma et flexiles lectuli, et graviora gladiis pocula (testa enim bibere iam pudebat), quaerebantur et aedes marmoreae, cum scriptum sit antiquitatibus, Spartanum militem coercitum acriter, quod procinctus tempore ausus sit videri sub tecto.", "st": "22.4"}, {"sp": "N", "t": "Adeo autem ferox erat in suos illis temporibus miles et rapax, ignavus vero in hostes et fractus, ut per ambitiones otiumque opibus partis, auri et lapillorum varietates discerneret scientissime, contra quam recens memoria tradidit.", "st": "22.4"}, {"sp": "N", "t": "Notum est enim sub Maximiano Caesare vallo regis Persarum direpto, gregarium quendam post sacculum Parthicum (in quo erant margaritae) repertum, proiectis imperitia gemmis, abisse, pellis nitore solo contentum.", "st": "22.4"}, {"sp": "N", "t": "Evenerat eisdem diebus, ut ad demendum imperatoris capillum, tonsor venire praeceptus, introiret quidam ambitiose vestitus. Quo viso Iulianus obstipuit, et “Ego” inquit “non rationalem iussi, sed tonsorem acciri.” Interrogatus tamen ille quid haberet ex arte compendii, vicenas diurnas respondit annonas, totidemque pabula iumentorum, quae vulgo dictitant capita, et annuum stipendium grave, absque fructuosis petitionibus multis.", "st": "22.4"}, {"sp": "N", "t": "Unde motus omnes huius modi, cum cocis similibusque allis, eadem paene accipere consuetos (ut parum sibi necessarios) data quo velint eundi potestate, proiecit.", "st": "22.4"}, {"sp": "N", "t": "Et quamquam a rudimentis pueritiae primis, inclinatior erat erga numinum cultum, paulatimque adulescens, desiderio rei flagrabat, multa metuens tamen agitabat quaedam ad id pertinentia, quantum fieri poterat, occultissime.", "st": "22.5"}, {"sp": "N", "t": "Ubi vero abolitis quae verebatur, adesse sibi liberum tempus faciendi quae vellet advertit, pectoris patefecit arcana, et planis absolutisque decretis, aperire templa arisque hostias admovere, et restituere deorum statuit cultum.", "st": "22.5"}, {"sp": "N", "t": "Utque dispositorum roboraret effectum, dissidentes Christianorum antistites cum plebe discissa in palatium intromissos, monebat civilius, ut discordiis consopitis, quisque nullo vetante, religioni suae serviret intrepidus.", "st": "22.5"}, {"sp": "N", "t": "Quod agebat ideo obstinate, ut dissensiones augente licentia, non timeret unanimantem postea plebem, nullas infestas hominibus bestias, ut sunt sibi ferales plerique Christianorum expertus. Saepeque dictitabat: “Audite me quem Alamanni audierunt et Franci,” imitari putans Marci principis veteris dictum. Sed parum advertit, hoc ab eo nimium discrepare.", "st": "22.5"}, {"sp": "N", "t": "Ille enim cum Palaestinam transiret, Aegyptum petens, Iudaeorum faetentium et tumultuantium saepe taedio percitus, dolenter dicitur exclamasse: “O Marcomanni, o Quadi, o Sarmatae, tandem alios vobis inquietiores inveni.”", "st": "22.5"}, {"sp": "N", "t": "Per hoc idem tempus, rumoribus exciti variis, Aegyptii venere complures, genus hominum controversum et assuetudine perplexius litigandi semper laetissimum, maximeque avidum multiplicatum reposcere, si compulsori quicquam dederit, ut levari debito possit, vel certe commodius per dilationem inferre quae flagitantur, aut criminis vitandi formidine, divites pecuniarum repetundarum interrogare.", "st": "22.6"}, {"sp": "N", "t": "Hi omnes densati in unum, principem ipsum, et praefectos praetorio, graculorum more strepentes, interpellabant incondite, modo non ante septuagensimum annum extorquentes, quae dedisse se iure vel secus plurimis affirmabant.", "st": "22.6"}, {"sp": "N", "t": "Cumque nihil aliud agi permitterent, edicto proposito, universos iussit transire Chalcedona, pollicitus quod ipse quoque protinus veniet, cuncta eorum negotia finiturus.", "st": "22.6"}, {"sp": "N", "t": "Quibus transgressis, mandatum est navigiorum magistris, ultro citroque discurrentium, nequis transfretare auderet Aegyptium, hocque observato cura perpensiore, evanuit pertinax calumniandi propositum, et omnes spe praesumpta frustrati, redierunt ad lares.", "st": "22.6"}, {"sp": "N", "t": "Unde velut aequitate ipsa dictante lex est promulgata, qua cavetur nullum interpellari suffragatorem, super his quae eum recte constiterit accepisse.", "st": "22.6"}, {"sp": "N", "t": "Allapso itaque Calendarum Ianuariarum die cum Mamertini et Nevittae nomina suscepissent paginae consulares, humilior princeps visus est, in officio pedibus gradiendo cum honoratis, quod laudabant alii quidam ut affectatum et vile carpebant.", "st": "22.7"}, {"sp": "N", "t": "Dein Mamertino ludos edente circenses, manu mittendis ex more inductis per admissionum proximum, ipse lege agi ocius dixerat, ut solebat, statimque admonitus iuris dictionem eo die ad alterum pertinere, ut errato obnoxium, decem libris auri semet ipse multavit.", "st": "22.7"}, {"sp": "N", "t": "Frequentabat inter haec curiam agendo diversa, quae divisiones multiplices ingerebant. Et cum die quodam ei causas ibi spectanti, venisse nuntiatus esset ex Asia philosophus Maximus, exsiluit indecore: et qui esset oblitus, effuso cursu a vestibulo longe progressus, exosculatum susceptumque reverenter, secum induxit per ostentationem intempestivam, nimius captator inanis gloriae visus, praeclarique illius dicti immemor Tulliani, quo tales notando ita relatum:", "st": "22.7"}, {"sp": "N", "t": "“Ipsi illi philosophi etiam in his libris, quos de contemnenda gloria scribunt, nomen suum inscribunt, ut in eo ipso, quo praedicationem nobilitatemque despiciunt, praedicari de se ac se nominari velint.”", "st": "22.7"}, {"sp": "N", "t": "Haud multo deinceps, duo agentes in rebus, ex his qui proiecti sunt, eum adiere fidentius, promittentes latebras monstrare Florentii, si eis gradus militiae redderetur, quos incessens delatoresque appellans addebat non esse imperatorium, obliquis flecti indiciis ad retrahendum hominem mortis metu absconditum, qui forte non diu latitare citra spem veniae permitteretur.", "st": "22.7"}, {"sp": "N", "t": "Aderat his omnibus Praetextatus, praeclarae indolis gravitatisque priscae senator, ex negotio proprio forte repertus apud Constantinopolim, quem arbitrio suo Achaiae proconsulari praefecerat potestate.", "st": "22.7"}, {"sp": "N", "t": "Nec tamen, cum corrigendis civilibus ita diligenter instaret, omisit castrensia, rectores militibus diu exploratos apponens, urbes quin etiam per Thracias omnes, cum munimentis reparans extimis, curansque sollicite, ne arma vel indumenta, aut stipendium vel alimenta deessent his quos per supercilia Histri dispersos, excursibusque barbarorum oppositos agere vigilanter audiebat et fortiter.", "st": "22.7"}, {"sp": "N", "t": "Quae cum ita divideret, nihil segnius agi permittens, suadentibus proximis, ut aggrederetur propinquos Gothos, saepe fallaces et perfidos, hostes quaerere se meliores aiebat: illis enim sufficere mercatores Galatas, per quos ubique sine condicionis discrimine venundantur.", "st": "22.7"}, {"sp": "N", "t": "Haec eum curantem et talia, commendabat externis nationibus fama, ut fortitudine, sobrietate, militaris rei scientia, virtutumque omnium incrementis excelsum, paulatimque progrediens, ambitum oppleverat mundi.", "st": "22.7"}, {"sp": "N", "t": "Proinde timore eius adventus per finitimos longeque distantes latius explicato, legationes undique solito ocius concurrebant: hinc Transtigritanis pacem obsecrantibus et Armeniis, inde nationibus Indicis certatim cum donis optimates mittentibus ante tempus ab usque Divis et Serendivis, ab australi plaga ad famulandum rei Romanae semet offerentibus Mauris, ab aquilone et regionibus solis, per quas in mare Phasis accipitur, Bosporanis aliisque antehac ignotis legationes vehentibus supplices, ut annua complentes sollemnia, intra terrarum genitalium terminos otiose vivere sinerentur.", "st": "22.7"}, {"sp": "N", "t": "Appositum est (ut existimo) tempus, ad has partes nos occasione magni principis devolutos, super Thraciarum extimis situque Pontici sinus, visa vel lecta quaedam perspicua fide monstrare.", "st": "22.8"}, {"sp": "N", "t": "Athos in Macedonia mons ille praecelsus navibus quondam Medicis pervius, et Caphereus Euboicus scopulus, ubi Nauplius Palamedis pater classem collisit Argivam, licet longo spatio controversi a Thessalo mari distinguunt Aegaeum, quod paulatim fusius adulescens, dextra (qua late protenditur) per Sporadas est insulosum atque Cycladas, ideo sic appellatas quod omnes ambiunt Delon partu deorum insignem, laeva Imbrum et Tenedum circumluens et Lemnum et Thasum, quando perflatur, Lesbo illiditur violentius.", "st": "22.8"}, {"sp": "N", "t": "Unde gurgitibus refluis Apollinis Sminthii templum et Troada perstringit et Ilium heroicis casibus claram, efficitque Melana sinum oppositum Zephyro, cuius apud principium Abdera visitur Protagorae domicilium et Democriti, cruentaeque Diomedis Thracii sedes et convalles, per quas Hebrus sibi miscetur, et Maronea et Aenus, qua diris auspiciis coepta moxque relicta ad Ausoniam veterem ductu numinum properavit Aeneas.", "st": "22.8"}, {"sp": "N", "t": "Hinc gracilescens paulatim et velut naturali quodam commercio ruens in Pontum eiusque partem ad se iungens, in speciem Φ litterae Graecae formatur, exin Hellespontum a Rhodopa scindens, Cynossema (ubi sepulta creditur Hecuba) et Coelan praeterlabitur et Seston et Callipolin. Contra per Achillis Aiacisque sepulchra, Dardanum contingit et Abydon, unde iunctis pontibus Xerxes maria pedibus peragravit, dein Lampsacum Themistocli dono datam a rege Persarum, et Parion quam condidit Iasionis filius Paris.", "st": "22.8"}, {"sp": "N", "t": "Unde semiorbe curvescens altrinsecus, lataque aperiens terrarum divortia, circumfluis spatiis Propontidos respergit ex eoo latere Cyzicum, et Dindyma (religiosa Matris Magnae delubra), et Apamiam Ciumque, ubi Hylam et Astacum secuto tempore Nicomediam a rege cognominatam, qua in occasum procedit Cherronesum pulsat et Aegospotamus, in quo loco lapides casuros ex caelo praedixit Anaxagoras, et Lysimachiam et civitatem, quam Hercules conditam Perinthi comitis sui memoriae dedicavit.", "st": "22.8"}, {"sp": "N", "t": "Et ut effecte pleneque Φ litterae figura servetur, in meditullio ipso rotunditatis Proconesus insula est oblonga et Besbicus.", "st": "22.8"}, {"sp": "N", "t": "Post cuius summitatem in angustias rursus extenuatum Europam et Bithyniam intercurrens, per Chalcedona et Chrysopolim et stationes transit obscuras.", "st": "22.8"}, {"sp": "N", "t": "Nam supercilia eius sinistra Athyras portus despectat et Selymbria et Constantinopolis, vetus Byzantium, Atticorum colonia, et promuntorium Ceras praelucentem navibus vehens constructam celsius turrim, quapropter Ceratas appellatur ventus inde suetus oriri praegelidus.", "st": "22.8"}, {"sp": "N", "t": "Hoc modo fractum et participatione maris utriusque finitum, iamque mitescens in aequoream panditur faciem, quantum potest cadere sub aspectum, late diffusum et longe.", "st": "22.8"}, {"sp": "N", "t": "Omnis autem eius velut insularis circuitus litorea navigatio viginti tribus dimensa milibus stadiorum, ut Eratosthenes affirmat et Hecataeus et Ptolomaeus aliique huius modi cognitionum minutissimi scitatores, in speciem Scythici arcus nervo coagmentati geographiae totius assensione formatur.", "st": "22.8"}, {"sp": "N", "t": "Et qua sol oceano exsurgit eoo, paludibus clauditur Maeotidos: qua declinat in vesperum, Romanis provinciis terminatur: unde suspicit sidus arctoum, homines alit linguis et moribus dispares: latus eius austrinum molli devexitate subductum.", "st": "22.8"}, {"sp": "N", "t": "Per haec amplissima spatia oppida sunt dispersa Graecorum, quae cuncta aetatibus variis praeter pauca Atheniensium coloni condidere Milesii, inter Ionas alios in Asia per Nileum multo ante locati, Codri illius filium, qui se pro patria bello fertur Dorico devovisse.", "st": "22.8"}, {"sp": "N", "t": "Extremitatis autem arcus utrumque tenus duo exprimunt Bospori, e regione sibi oppositi, Thracius et Cimmericus: hac causa Bospori vocitati, quod per eos quondam Inachi filia, mutata (ut poetae loquuntur) in bovem, ad mare Ionium permeavit.", "st": "22.8"}, {"sp": "N", "t": "Dextram igitur inflexionem Bospori Thracii excipit Bithyniae litus, quam veteres dixere Mygdoniam, in qua Thynia et Mariandena sunt regiones et Amyci saevitia Bebryces exempti virtute Pollucis, remotaque statio, in qua volitantes minaciter harpyias Phineus vates horrebat; per quae litora in sinus oblongos curvatus Sangarius et Phyllis et Lycus et Rhebas fluvii funduntur in maria, quibus controversae cyaneae sunt Symplegades, gemini scopuli in vertices undique porrecti deruptos, assueti priscis saeculis obviam sibi cum horrendo fragore collisis molibus ferri, cedentesque retrorsus acri assultu, ad ea reverti quae pulsarant. Per has saxorum dehiscentium concursantiumque crebritates si etiam ales intervolasset, nulla celeritate pinnarum eripi poterat quin interiret oppressa.", "st": "22.8"}, {"sp": "N", "t": "Hi scopuli cum eos Argo prima omnium navis Colchos as direptionem aurei properans velleris praeterisset innoxia, immobiles turbine circumfracto stetere concorporati, ut eos aliquando fuisse diremptos nulli nunc conspicantium credant, nisi super hoc congruerent omnes priscorum carminum cantus.", "st": "22.8"}, {"sp": "N", "t": "Post Bithyniae partem provinciae Pontus et Paphlagonia protenduntur, in quibus Heraclea et Sinope et Polemonion, et Amisos amplae sunt civitates, et Tios et Amastris, omnes ab auspicio diligentia fundatae Graecorum, et Cerasus, unde advexit huius nominis poma Lucullus, insulaeque duae, et Trapezunta et Pityunta continentis oppida non obscura.", "st": "22.8"}, {"sp": "N", "t": "Ultra haec loca Acherusium specus est, quod accolae Μυχοπόντιον appellant, et portus Acone, fluviique Acheron, idemque Arcadius, et Iris et Tibris et iuxta Parthenius, omnes in mare ictu rapido decurrentes. Thermodon his amnis est proximus ab Armonio defluens monte, et Themiscyraeos interlabens lucos ad quos Amazonas quondam migrare necessitas subegerat talis.", "st": "22.8"}, {"sp": "N", "t": "Attritis damnorum assiduitate finitimis, Amazones veteres, quae eos cruentis populabantur incursibus, altiora spirabant, viresque suas circumspectantes his, quae propinqua saepius appetebant, validiores, raptae praecipiti cupiditatis ardore, perruptis nationibus plurimis, manus Atheniensibus intulerunt, acrique concertatione effuse disiectae, omnes nudatis equitatus sui lateribus, corruere.", "st": "22.8"}, {"sp": "N", "t": "Harum interitu cognito, residuae ut imbelles domi relictae, extrema perpessae, et vicinitatis repensantis similia, funestos impetus declinantes, ad pacatiorem sedem transiere Thermodontis, quarum progenies longe deinde propagata, per numerosam subolem manu firmissima ad loca reverterat genitalia, secuto tempore populis diversarum originum formidabilis.", "st": "22.8"}, {"sp": "N", "t": "Haut procul inde attollitur Carambis, placide collis contra septentrionem Helicen exsurgens, cuius e regione est Criumetopon, Tauricae promuntorium, duobus milibus et quingentis stadiis disparatum. Hocque ex loco omnis ora maritima, cuius initium Halys est amnis, velut longitudine lineali directa nervi efficit speciem, duabus arcus summitatibus complicati.", "st": "22.8"}, {"sp": "N", "t": "His regionibus Dahae confines sunt, acerrimi omnium bellatores, et Chalybes, per quos erutum et domitum est primitus ferrum. Post quos terras patentes Byzares obtinent et Sapires et Tibareni et Mossynoeci et Macrones et Philyres, populi nulla nobis assuetudine cogniti.", "st": "22.8"}, {"sp": "N", "t": "A quibus brevi spatio distant virorum monumenta nobilium, in quibus Sthenelus est humatus et Idmon et Tiphys, primus Herculis socius, Amazonico bello letaliter vulneratus, alter augur Argonautarum, tertius eiusdem navis cautissimus rector.", "st": "22.8"}, {"sp": "N", "t": "Praetercursis partibus memoratis, Aulion antron est, et fluenta Callichori, ex facto cognominati, quod superatis post triennium Indicis nationibus, ad eos tractus Liber reversus, circa huius ripas viridis et opacas orgia pristina reparavit et choros: trieterica huius modi sacra quidam existimant appellari.", "st": "22.8"}, {"sp": "N", "t": "Post haec confinia, Camaritarum pagi sunt celebres, et Phasis fremebundis cursibus Colchos attingit, Aegyptiorum antiquam subolem, ubi inter civitates alias Phasis est nomine fluvii dictitata, et Dioscurias nunc usque nota, cuius auctores Amphitus et Cercius Spartani traduntur, aurigae Castoris et Pollucis, quibus Heniochorum natio est instituta.", "st": "22.8"}, {"sp": "N", "t": "Paulum ab his secernuntur Achaei, qui bello anteriore quodam apud Troiam consummate, non cum super Helena certaretur (ut auctores prodidere non nulli), usque in Pontum reflantibus ventis errore delati, cunctisque hostilibus, stabilem domicilii sedem nusquam reperientes, verticibus montium insedere semper nivalium, et horrore caeli districti, victum sibi cum periculis raptu parare assuefacti sunt, atque eo ultra omnem deinde ferociam saevierunt. Super Cercetis, qui eisdem annexi sunt, nihil memoratu traditur dignum.", "st": "22.8"}, {"sp": "N", "t": "Quorum post terga Cimmerici agitant incolae Bospori, ubi Milesiae sunt civitates, harumque velut mater omnium Panticapaeum, quam perstringit Hypanis fluvius, genuinis intumescens aquis et externis.", "st": "22.8"}, {"sp": "N", "t": "Itineribus hinc extensis, Amazones ad usque Caspium mare porrectae, circumcolunt Tanain, qui inter Caucasias oriens rupes per sinuosos labitur circumflexus, Asiamque disterminans ab Europa, in stagnis Maeoticis delitescit.", "st": "22.8"}, {"sp": "N", "t": "Huic Ra vicinus est amnis, in cuius superciliis quaedam vegetabilis eiusdem nominis gignitur radix, proficiens ad usus multiplicis medelarum.", "st": "22.8"}, {"sp": "N", "t": "Ultra Tanain panduntur in latitudinem Sauromatae, per quos amnes fluunt perpetui Marabius et Rombitus et Theophanes et Totordanes. Licet alia quoque distans immanibus intervallis, Sauromatarum praetenditur natio, litori iuncta, quod Coracem suscipiens fluvium in aequor eiectat Euxinum.", "st": "22.8"}, {"sp": "N", "t": "Prope palus est Maeotis amplissimi circumgressus, ex cuius uberrimis venis per Panticapes angustias undarum magnitudo prorumpit in Pontum, cuius in dextro latere insulae sunt Phanagorus et Hermonassa studio constructae Graecorum.", "st": "22.8"}, {"sp": "N", "t": "Circa haec stagna ultima extimaque plures habitant gentes, sermonum institutorumque varietate dispariles, Iaxamatae et Maeotae et Iazyges, Roxolanique et Halani et Melanchlaenae et cum Gelonis Agathyrsi, apud quos adamantis est copia lapidis: aliique ultra latentes, quod sunt omnium penitissimi.", "st": "22.8"}, {"sp": "N", "t": "Sed Maeotidos lateri laevo Cherronesus est propinqua, coloniarum plena Graecarum. Unde quieti sunt homines et sedati, adhibentes vomeri curam, et proventibus fructuariis victitantes.", "st": "22.8"}, {"sp": "N", "t": "A quibus per varia regna diducti itineribus modicis Tauri dissociantur, inter quos immani diritate terribiles Arichi et Sinchi et Napaei, intendente saevitiam licentia diuturna, indidere mari nomen inhospitali, et a contrario per cavillationem Pontus Εὔξεινος appellatur, ut εὐήθη Graeci dicimus stultum et noctem εὐφρόνην, et furias εὐμενίδας.", "st": "22.8"}, {"sp": "N", "t": "Deos enim hostiis litantes humanis et immolantes advenas Dianae, quae apud eos dicitur Orsiloche, caesorum capita fani parietibus praefigebant, velut fortium perpetua monumenta facinorum.", "st": "22.8"}, {"sp": "N", "t": "In hac Taurica insula Leuce sine habitatoribus ullis Achilli est dedicata. In quam si fuerint quidam forte delati, visis antiquitatis vestigiis temploque et donariis eidem heroi consecratis, vesperi repetunt naves: aiunt enim non sine discrimine vitae illic quemquam pernoctare. Ibi et aquae sunt, et candidae aves nascuntur, halcyonibus similes, super quarum origine et Hellespontiacis proeliis tempore disseremus.", "st": "22.8"}, {"sp": "N", "t": "Sunt autem quaedam per Tauricam civitates, inter quas eminet Eupatoria et Dandace, et Theodosia et minores aliae nullis humanis hostiis impiatae.", "st": "22.8"}, {"sp": "N", "t": "Hactenus arcus apex protendi existimatur. Eius nune residua leniter sinuata, subiectaque ursae caelesti, ad usque laevum Bospori Thracii latus (ut ordo postulat) exsequemur, id admonentes, quod, cum arcus omnium gentium flexis curventur hastilibus, Scythici soli vel Parthici, circumductis utrimque introrsus pandis et patulis cornibus, effigiem lunae decrescentis ostendunt, medietatem recta et rotunda regula dividente.", "st": "22.8"}, {"sp": "N", "t": "Ergo in ipso huius compagis exordio, ubi Riphaei deficiunt montes, habitant Arimphaei, iusti homines placiditateque cogniti, quos amnes Chronius et Visula praeterfluunt; iuxtaque Massagetae, Halani et Sargetae, aliique plures obscuri, quorum nec vocabula nobis sunt nota nec mores.", "st": "22.8"}, {"sp": "N", "t": "Interiectu deinde non mediocri Carcinites panditur sinus eiusdemque nominis fluvius, et religiosus per eas terras Triviae lucus.", "st": "22.8"}, {"sp": "N", "t": "Dein Borysthenes a montibus oriens Nerviorum, primigeniis fontibus copiosus concursuque multorum amnium adulescens, mari praeruptis undarum verticibus intimatur, cuius in marginibus nemorosis Borysthenes est civitas et Cephalonesus, et arae Alexandro Magno Caesarique Augusto sacratae.", "st": "22.8"}, {"sp": "N", "t": "Longo exinde intervallo paene est insula, quam incolunt Sindi ignobiles, post eriles in Asia casus, coniugiis potiti dominorum et rebus, quibus subiectum gracile litus Ἀχιλλέως vocant indigenae δρόμον, exercitiis ducis quondam Thessali memorabilem. Eique proxima est civitas Tyros, colonia Phoenicum, quam praestringit fluvius Tyras.", "st": "22.8"}, {"sp": "N", "t": "In medio autem spatio arcus, quod prolixae rotunditatis esse praediximus, quodque expedite viatori diebus conficitur quindecim, Europaei sunt Halani et Costobocae, gentesque Scytharum innumerae, quae porriguntur ad usque terras sine cognito fine distentas. Quarum pars exigua frugibus alitur, residuae omnes palantes per solitudines vastas, nec stivam aliquando nec sementem expertas, sed squalentes et pruinosas, ferarum taetro ritu vescuntur, eisque caritates et habitacula, vilesque suppellectiles plaustris impositae sunt corticibus tectis, et cum placuerit, sine obstaculo migrant, eodem carpenta quo libuerit convolventes.", "st": "22.8"}, {"sp": "N", "t": "Cum autem ad alium portuosum ambitum fuerit ventum, qui arcus figuram determinat ultimam, Peuce prominet insula, quam circumcolunt Trogodytae et Peucini, minoresque aliae gentes, et Histros quondam potentissima civitas, et Tomi et Apollonia et Anchialos et Odessos, aliae praeterea multae, quas litora continent Thraciarum.", "st": "22.8"}, {"sp": "N", "t": "Amnis vero Danubius, oriens prope Rauracos montesque confines limitibus Raeticis, per latiorem orbem praetentus, ac sexaginta navigabilis paene omnes recipiens fluvios, septem ostiis per hoc Scythicum litus erumpit in mare.", "st": "22.8"}, {"sp": "N", "t": "Quorum primum est Peuce insula supra dicta, ut interpretata sunt vocabula Graeco sermone, secundum Naracustoma, tertium Calonstoma, quartum Pseudostoma; nam Borionstoma ac deinde Stenostoma longe minora sunt ceteris; septimum caenosum et palustri specie nigrum.", "st": "22.8"}, {"sp": "N", "t": "Omnis autem circumfluo ambitu Pontus et nebulosus est, et dulcior aequorum ceteris et vadosus, quod et concrescit aer ex umorum spiramine saepe densatus, et irruentium undarum magnitudine temperatur, et consurgit in brevia dorsuosa, limum glebasque aggerente multitudine circumvenientium fluentorum.", "st": "22.8"}, {"sp": "N", "t": "Et constat ab ultimis nostri finibus maris, agminatim ad hunc secessum pariendi gratia petere pisces, ut aquarum suavitate salubrius fetus educant in receptaculis cavis (qualia sunt ibi densissima), securi voracium beluarum: nihil enim in Ponto huius modi aliquando est visum, praeter innoxios delphinas et parvos.", "st": "22.8"}, {"sp": "N", "t": "Quicquid autem eiusdem Pontici sinus aquilone caeditur et pruinis, ita perstringitur gelu, ut nec amnium cursus subtervolvi credantur, nec per infidum et labile solum, gressus hominis possit vel iumenti firmari, quod vitium numquam mare sincerum, sed permixtum aquis amnicis temptat. Prolati aliquanto sumus longius quam sperabamus, pergamus ad reliqua.", "st": "22.8"}, {"sp": "N", "t": "Accesserat aliud ad gaudiorum praesentium cumulum, diu quidem speratum, sed dilationum ambage multiplici tractum. Nuntiatum est enim per Agilonem et Iovium, postea quaestorem, Aquileiae defensores longioris obsidii taedio, cognitoque Constanti excessu, patefactis portis egressos, auctores prodidisse turbarum, eisdemque vivis exustis (ut supra relatum est), omnes concessionem impetrasse delictorum et veniam.", "st": "22.8"}, {"sp": "N", "t": "At prosperis Iulianus elatior, ultra homines iam spirabat, periclis expertus assiduis, quod ei orbem Romanum placide iam regenti, velut mundanam cornucopiam Fortuna gestans propitia, cuncta gloriosa deferebat et prospera, antegressis victoriarum titulis haec quoque adiciens, quod, dum teneret imperium solus, nec motibus internis est concitus, nec barbarorum quisquam ultra suos exsiluit fines: et populi omnes, aviditate semper insectari praeterita, ut damnosa et noxia, in laudes eius studiis miris accendebantur.", "st": "22.9"}, {"sp": "N", "t": "Omnibus igitur, quae res diversae poscebant et tempora, perpensa deliberatione dispositis, et militibus orationibus crebris, stipendioque competenti, ad expedienda incidentia promptius animatis, cunctorum favore sublimis, Antiochiam ire contendens, reliquit Constantinopolim incrementis maximis fultam: natus enim illic, diligebat eam ut genitalem patriam et colebat.", "st": "22.9"}, {"sp": "N", "t": "Transgressus itaque fretum, praetercursa Chalcedone et Libyssa, ubi sepultus est Hannibal Poenus, Nicomediam venit, urbem antehac inclytam, ita magnis retro principum amplificatam impensis, ut aedium multitudine privatarum et publicarum, recte noscentibus regio quaedam urbis aestimaretur aeternae.", "st": "22.9"}, {"sp": "N", "t": "Cuius moenia cum vidisset in favillas miserabiles consedisse, angorem animi tacitis fletibus indicans, pigriore gradu pergebat ad regiam, hoc maxime aerumnis eius illacrimans, quod ordo squalens occurrit et populus nimium quantum antehac florentissimus; et agnoscebat quosdam, ibidem ab Eusebio educatus episcopo, quem genere longius contingebat.", "st": "22.9"}, {"sp": "N", "t": "Hic quoque pari modo ad reparanda, quae terrae subverterat tremor, abunde praestitis plurimis, per Nicaeam venit ad Gallograeciae fines, unde dextrorsus itinere declinato, Pessinunta convertit, visurus vetusta Matris magnae delubra, a quo oppido bello Punico secundo, carmine Cumano monente, per Scipionem Nasicam simulacrum translatum est Romam.", "st": "22.9"}, {"sp": "N", "t": "Cuius super adventu in Italiam pauca cum aliis huic materiae congruentibus, in actibus Commodi principis digessimus per excessum. Quam autem ob rem hoc nomine oppidum sit appellatum, variant rerum scriptores:", "st": "22.9"}, {"sp": "N", "t": "quidam enim figmento deae caelitus lapso ἀπὸ τοῦ πεσεῖν (quod cadere nos dicimus) urbem asseruere cognominatam. Alii memorant Ilum, Trois filium Dardaniae regem, locum sic appellasse. At Theopompus non Ilum id egisse, sed Midam affirmat, Phrygiae quondam potentissimum regem.", "st": "22.9"}, {"sp": "N", "t": "Venerato igitur numine, hostiisque litato et votis, Ancyram rediit: eumque exinde progredientem ulterius, multitudo inquietabat, pars violenter erepta reddi sibi poscentium, alii querentes consortiis se curialium addictos iniuste, non nulli sine respectu periculi agentes ad usque rabiem, ut adversarios suos laesae maiestatis criminibus illigarent.", "st": "22.9"}, {"sp": "N", "t": "Verum ille iudicibus Cassiis tristior et Lycurgis, causarum momenta aequo iure perpendens, suum cuique tribuebat, nusquam a vero abductus, acrius in calumniatores exsurgens, quos oderat, multorum huius modi petulantem saepe dementiam, ad usque discrimen expertus, dum esset adhuc humilis et privatus.", "st": "22.9"}, {"sp": "N", "t": "Exemplumque patientiae eius in tali negotio, licet sint alia plurima, id unum sufficiet poni. Inimicum quidam suum, cum quo discordabat asperrime, commisisse in maiestatem turbulentius deferebat, imperatoreque dissimulante, eadem diebus continuis replicans, interrogatus ad ultimum, qui esset quem argueret, respondit municipem locupletem Quo audito princeps renidens “Quibus indiciis” ait “ad hoc pervenisti?”", "st": "22.9"}, {"sp": "N", "t": "Et ille “Purpureum sibi” inquit “indumentum ex serico pallio parat,” iussusque post haec ut vilis arduae rei vilem incusans, abire tacitus et innoxius, nihilo minus instabat. Quo taedio Iulianus defetigatus ad largitionum comitem visum propius “Iube” inquit “periculoso garrulo pedum tegmina dari purpurea, ad adversarium perferenda, quem (ut datur intellegi), chlamydem huius coloris memorat sibi consarcinasse, ut sciri possit sine viribus maximis quid pannuli proficiant leves.”", "st": "22.9"}, {"sp": "N", "t": "Sed ut haec laudanda et bonis moderatoribus aemulanda, ita illud amarum et notabile fuit, quod aegre sub eo a curialibus quisquam appetitus, licet privilegiis et stipendiorum numero et originis penitus alienae firmitudine communitus, ius obtinebat aequissimum, adeo ut plerique territi emercarentur molestias pretiis clandestinis et magnis.", "st": "22.9"}, {"sp": "N", "t": "Itineribus itaque emensis cum ad Pylas venisset, qui locus Cappadocas discernit et Cilicas, osculo susceptum rectorem provinciae, nomine Celsum, iam inde a studiis cognitum Atticis, asscitumque in consessum vehiculi, Tarsum secum induxit.", "st": "22.9"}, {"sp": "N", "t": "At hinc videre properans Antiochiam, orientis apicem pulcrum, usus itineribus solitis venit, urbique propinquans, in speciem alicuius numinis votis excipitur publicis, miratus voces multitudinis magnae, salutare sidus illuxisse eois partibus acclamantis.", "st": "22.9"}, {"sp": "N", "t": "Evenerat autem eisdem diebus, annuo cursu completo, Adonea ritu veteri celebrari, amato Veneris (ut fabulae fingunt), apri dente ferali deleto, quod in adulto flore sectarum est indicium frugum. Et visum est triste, quod amplam urbem principumque domicilium introeunte imperatore tunc primum, ululabiles undique planctus et lugubres sonus audiebantur.", "st": "22.9"}, {"sp": "N", "t": "Hic patientiae eius et lenitudinis documentum leve quidem apparuit, sed mirandum. Thalassium quendam ex proximo libellorum, insidiatorem fratris oderat Galli, quo adorare adesseque officio inter honoratos prohibito, adversarii, cum quibus litigabat in foro, postridie turba congregata superflua, adito imperatore “Thalassius” clamitabant, “inimicus pietatis tuae nostra violenter eripuit.”", "st": "22.9"}, {"sp": "N", "t": "Et ille hac occasione hominem opprimi posse coniciens, “Agnosco” respondit, “quem dicitis offendisse me iusta de causa, sed silere vos interim consentaneum est, dum mihi inimico potiori faciat satis.” Mandavitque assidenti praefecto, ne audiretur eorum negotium, antequam ipse cum Thalassio rediret in gratiam, quod brevi evenit.", "st": "22.9"}, {"sp": "N", "t": "Ibi hiemans ex sententia, nullis interim voluptatium rapiebatur illecebris, quibus abundant Syriae omnes, verum per speciem quietis, iudicialibus causis intentus, non minus quam arduis bellicisque, distrahebatur multiformibus curis, exquisita docilitate deliberans, quibus modis suum cuique tribueret, iustisque sententiis, et improbi modicis coercerentur suppliciis, et innocentes fortunis defenderentur intactis.", "st": "22.10"}, {"sp": "N", "t": "Et quamquam in disceptando aliquotiens erat intempestivus, quid quisque iurgantium coleret, tempore alieno interrogans, tamen nulla eius definitio litis a vero dissonans reperitur, nec argui umquam potuit, ob religionem vel quodcumque aliud ab aequitatis recto tramite deviasse.", "st": "22.10"}, {"sp": "N", "t": "Iudicium enim hoc est optandum et rectum, ubi per varia negotiorum examina, iustum distinguitur et iniustum; a quo ille ne aberraret, tamquam scopulos cavebat abruptos. Hoc autem ideo assequi potuit, quod levitatem agnoscens commotioris ingenii sui, praefectis proximisque permittebat, ut fidenter impetus sues aliorsum tendentes atque decebat, monitu opportune frenarent; monstrabatque subinde se dolere delictis et gaudere correctione.", "st": "22.10"}, {"sp": "N", "t": "Cumque eum defensores causarum, ut conscium rationis perfectae, plausibus maximis celebrarent, fertur id dixisse permotus: “Gaudebam plane praeque me ferebam, si ab his laudarer, quos et vituperare posse adverterem, siquid factum sit secus aut dictum.”", "st": "22.10"}, {"sp": "N", "t": "Sufficiet autem pro multis, quae clementer egit in litibus cognoscendis, hoc unum ponere nec abhorrens a proposito, nec absurdum. Inducta in iudicium femina quaedam, cum palatinum adversarium suum e numero proiectorum cinctum praeter spem conspexisset, hoc factum insolens tumultuando querebatur, et imperator “Prosequere” ait “mulier, siquid te laesam existimas; hic enim sic cinctus est, ut expeditius per lutum incedat: parum nocere tuis partibus potest.”", "st": "22.10"}, {"sp": "N", "t": "Et aestimabatur per haec et similia, ut ipse dicebat assidue, vetus illa Iustitia, quam offensam vitiis hominum, Aratus extollit in caelum, imperante eo reversa ad terras, ni quaedam suo ageret, non legum arbitrio, erransque aliquotiens, obnubilaret gloriarum multiplices cursus.", "st": "22.10"}, {"sp": "N", "t": "Post multa enim etiam iura quaedam correxit in melius, ambagibus circumcisis, indicantia liquide, quid iuberent fieri vel vetarent. Illud autem erat inclemens, obruendum perenni silentio, quod arcebat docere magistros rhetoricos et grammaticos, ritus Christiani cultores.", "st": "22.10"}, {"sp": "N", "t": "Eisdem diebus notarius ille Gaudentius, quem opponendum per Africam missum supra diximus a Constantio, Iulianus quin etiam ex vicario, earundem partium nimius fautor, retracti sub vinculis, morte periere poenali.", "st": "22.11"}, {"sp": "N", "t": "tunc et Artemius, ex duce Aegypti, Alexandrinis urgentibus atrocium criminum mole, supplicio capitali multatus est. Post quem Marcelli ex magistro equitum et peditum filius, ut iniectans imperio manus publica deletus est morte. Romanus quin etiam et Vincentius, scutariorum scholae primae secundaeque tribuni, agitasse convicti quaedam suis viribus altiora, acti sunt in exilium.", "st": "22.11"}, {"sp": "N", "t": "Cumque tempus interstetisset exiguum, Alexandrini, Artemii comperto interitu, quem verebantur, ne cum potestate reversus (id enim minatus est), multos laederet ut offensus, iram in Georgium verterunt episcopum, vipereis (ut ita dixerim), morsibus ab eo saepius appetiti.", "st": "22.11"}, {"sp": "N", "t": "Is in fullonio natus (ut ferebatur), apud Epiphaniam Ciliciae oppidum, auctusque in damna complurium, contra utilitatem suam reique communis, episcopus Alexandriae est ordinatus, in civitate quae suopte motu et ubi causae non suppetunt, seditionibus crebris agitatur et turbulentis, ut oraculorum quoque loquitur fides.", "st": "22.11"}, {"sp": "N", "t": "His efferatis hominum mentibus, Georgius quoque ipse grave accesserat incentivum, apud patulas aures Constantii multos exinde incusans ut eius recalcitrantes imperiis, professionisque suae oblitus, quae nihil nisi iustum suadet et lene, ad delatorum ausa feralia desciscebat.", "st": "22.11"}, {"sp": "N", "t": "Et inter cetera dicebatur id quoque maligne docuisse Constantium, quod in urbe praedicta aedificia cuncta solo cohaerentia, a conditore Alexandro magnitudine impensarum publicarum exstructa, emolumentis aerarii proficere debent ex iure.", "st": "22.11"}, {"sp": "N", "t": "Ad haec mala id quoque addiderat, unde paulo post actus est in exitium praeceps. Reversus ex comitatu principis cum transiret per speciosum Genii templum, multitudine stipatus ex more, flexis ad aedem ipsam luminibus “Quam diu” inquit “sepulcrum hoc stabit?” Quo audito, velut fulmine multi perculsi, metuentesque ne illud quoque temptaret evertere, quicquid poterant in eius perniciem clandestinis insidiis concitabant.", "st": "22.11"}, {"sp": "N", "t": "Ecce autem repente perlato laetabili nuntio, indicante exstinctum Artemium, plebs omnis elata gaudio insperato, vocibus horrendis infrendens, Georgium petit, raptumque diversis mulcandi generibus proterens et conculcans, divaricatis pedibus, interfecit.", "st": "22.11"}, {"sp": "N", "t": "Cumque eo Dracontius monetae praepositus et Diodorus quidam, veluti comes, iniectis per crura funibus simul exanimati sunt; ille quod aram in moneta quam regebat, recens locatam evertit; alter quod dum aedificandae praeesset ecclesiae, cirros puerorum licentius detondebat, id quoque ad deorum cultum existimans pertinere.", "st": "22.11"}, {"sp": "N", "t": "Quo non contenta multitudo immanis, dilaniata cadavera peremptorum camelis imposita, vexit ad litus, eisdemque subdito igne crematis, cineres proiecit in mare, id metuens (ut clamabat), ne collectis supremis, aedes illis exstruerentur, ut reliquis, qui deviare a religione compulsi, pertulere cruciabiles poenas, ad usque gloriosam mortem intemerata fide progressi, et nunc martyres appellantur.", "st": "22.11"}, {"sp": "N", "t": "Poterantque miserandi homines ad crudele supplicium ducti, Christianorum adiumento defendi, ni Georgii odio omnes indiscrete flagrabant.", "st": "22.11"}, {"sp": "N", "t": "Hoc comperto imperator ad vindicandum facinus nefandum erectus, iamque expetiturus poenas a noxiis ultimas, mitigatus est lenientibus proximis, missoque edicto, acri oratione scelus detestabatur admissum, minatus extrema, si deinde temptatum fuerit aliquid quod iustitia vetet et leges.", "st": "22.11"}, {"sp": "N", "t": "Inter haec expeditionem parans in Persas, quam dudum animi robore conceperat celso, ad ultionem praeteritorum vehementer elatus est, sciens et audiens, gentem asperrimam per sexaginta ferme annos inussisse Orienti caedum et direptionum monumenta saevissima, ad internecionem exercitibus nostris saepe deletis.", "st": "22.12"}, {"sp": "N", "t": "Urebatur autem bellandi gemino desiderio, primo quod impatiens otii, lituos somniabat et proelia, dein quod in aetatis flore primaevo, obiectus efferatarum gentium armis, recalentibus etiam tum regum precibus et regalium, qui vinci magis posse quam supplices manus tendere credebantur, ornamentis illustrium gloriarum inserere Parthici cognomentum ardebat.", "st": "22.12"}, {"sp": "N", "t": "Quae maximis molibus festinari cernentes, obtrectatores desides et maligni, unius corporis permutationem tot ciere turbas intempestivas, indignum et perniciosum esse strepebant, studium omne in differendo procinctu ponentes. Et dictitabant, his praesentibus quos audita referre ad imperatorem posse rebantur, eum ni sedatius ageret in immodica rerum secundarum prosperitate, velut luxuriantes ubertate nimia fruges, bonis suis protinus occasurum.", "st": "22.12"}, {"sp": "N", "t": "Et haec diu multumque agitantes, frustra virum circumlatrabant immobilem occultis iniuriis, ut Pygmaei vel Thiodamas agrestis homo Lindius Herculem.", "st": "22.12"}, {"sp": "N", "t": "Ille tamen ut maioris praeter ceteros spiritus, nihilo lentius magnitudinem expeditionis secum commentans, in praeparandis congruis operam navabat enixam.", "st": "22.12"}, {"sp": "N", "t": "Hostiarum tamen sanguine plurimo aras crebritate nimia perfundebat, tauros aliquotiens immolando centenos, et innumeros varii pecoris greges, avesque candidas terra quaesitas et mari, adeo ut in dies paene singulos milites carnis distentiore sagina, victitantes incultius, potusque aviditate corrupti, umeris impositi transeuntium, per plateas ex publicis aedibus, ubi vindicandis potius quam cedendis conviviis indulgebant, ad sua diversoria portarentur, Petulantes ante omnes et Celtae, quorum ea tempestate confidentia creverat ultra modum.", "st": "22.12"}, {"sp": "N", "t": "Augebantur autem cerimoniarum ritus immodice, cum impensarum amplitudine antehac inusitata et gravi: et quisque cum impraepedite liceret, scientiam vaticinandi professus, iuxta imperitus et docilis, sine fine vel praestitutis ordinibus, oraculorum permittebantur scitari responsa, et extispicia non numquam futura pandentia, oscinumque et auguriorum et ominum fides, si reperiri usquam posset, affectata varietate quaerebatur.", "st": "22.12"}, {"sp": "N", "t": "Haecque dum more pacis ita procedunt, multorum curiosior Iulianus, novam consilii viam ingressus est, venas fatidicas Castalii recludere cogitans fontis, quem obstruxisse Caesar dicitur Hadrianus mole saxorum ingenti, veritus ne (ut ipse praecinentibus aquis capessendam rem publicam comperit), etiam alii similia docerentur: deumque adfatus circumhumata corpora statuit exinde transferri, eo ritu quo Athenienses insulam purgaverant Delon.", "st": "22.12"}, {"sp": "N", "t": "Eodem tempore diem undecimum kalendarum Novembrium amplissimum Daphnaei Apollinis fanum, quod Epiphanes Antiochus rex ille condidit iracundus et saevus, et simulacrum in eo Olympiaci Iovis imitamentum, eiusque aequiperans magnitudinem, subita vi flammarum exustum est.", "st": "22.13"}, {"sp": "N", "t": "Quo tam atroci casu repente consumpto, ad id usque imperatorem ira provexit, ut quaestiones agitari iuberet, solito acriores, et maiorem ecclesiam Antiochiae claudi. Suspicabatur enim id Christianos egisse, stimulatos invidia, quod idem templum inviti videbant ambitioso circumdari peristylio.", "st": "22.13"}, {"sp": "N", "t": "Ferebatur autem licet rumore levissimo, hac ex causa conflagrasse delubrum, quod Asclepiades philosophus, cuius in actibus Magnenti meminimus, cum visendi gratia Iuliani peregre ad id suburbanum venisset, deae caelestis argenteum breve figmentum, quocumque ibat secum solitus ferre, ante pedes statuit simulacri sublimes, accensisque cereis ex usu cessit, unde medietate noctis emensa, cum nec adesse quisquam potuit nec iuvare, volitantes scintillae adhaesere materiis vetustissimis, ignisque aridis nutrimentis, omne quicquid contingi potuit (licet erecta discretum celsitudine) concremarunt.", "st": "22.13"}, {"sp": "N", "t": "Eo anno sidere etiam tum instante brumali, aquarum incessit inopia metuenda, ut et rivi cassescerent quidam, et fontes antehac aquarum copiosis pulsibus abundantes, sed in integrum postea restituti sunt.", "st": "22.13"}, {"sp": "N", "t": "Et quartum nonas Decembres, vergente in vesperam die, reliqua Nicomedia collapsa est terrae motu, itidemque Nicaeae portio non mediocris.", "st": "22.13"}, {"sp": "N", "t": "Quae tametsi maestitiam sollicito incuterent principi, residua tamen non contemnebat urgentia, dum pugnandi tempus ei veniret optatum. Inter praecipua tamen et seria illud agere superfluum videbatur, quod, nulla probabili ratione suscepta, popularitatis amore, vilitati studebat venalium rerum, quae non numquam secus quam convenit ordinata, inopiam gignere solet et famem.", "st": "22.14"}, {"sp": "N", "t": "Et Antiochensi ordine id tunc fieri, cum ille iuberet, non posse, aperte monstrante, nusquam a proposito declinabat, Galli similis fratris licet incruentus. Quocirca in eos deinceps saeviens ut obtrectatores et contumaces volumen composuit invectivum, quod Antiochense vel Misopogonem appellavit, probra civitatis infensa mente dinumerans, addensque veritati complura: post quae multa in se facete dicta comperiens, coactus dissimulare pro tempore, ira sufflabatur interna.", "st": "22.14"}, {"sp": "N", "t": "Ridebatur enim ut Cercops, homo brevis humeros extentans angustos et barbam prae se ferens hircinam, grandiaque incedens tamquam Oti frater et Ephialtis, quorum proceritatem Homerus in immensum extollit, itidemque victimarius pro sacricola dicebatur ad crebritatem hostiarum alludentibus multis, et culpabatur hinc opportune, cum ostentationis gratia, vehens licenter pro sacerdotibus sacra, stipatusque mulierculis laetabatur. Et quamquam his paribusque de causis indignaretur, tacens tamen motumque in animi retinens potestate, sollemnia celebrabat.", "st": "22.14"}, {"sp": "N", "t": "Denique praestituto feriarum die Casium montem ascendit, nemorosum et tereti ambitu in sublime porrectum, unde secundis galliciniis videtur primo solis exortus. Cumque Iovi faceret rem divinam, repente conspexit quendam humi prostratum, supplici voce vitam precantem et veniam. Interrogantique ei, qui esset, responsum est praesidalem esse Theodotum Hierapolitanum, qui profectum a civitate sua Constantium inter honoratos deducens, adulando deformiter, tamquam futurum sine dubietate victorem, orabat, lacrimas fingens et gemitum, ut Iuliani ad eos mitteret caput, perduellis ingrati, specie illa, qua Magnenti circumlatum meminerat membrum.", "st": "22.14"}, {"sp": "N", "t": "Quibus auditis, “Accepi” inquit, “olim hoc dictum” imperator “relatione multorum, sed abi securus ad lares exutus omni metu clementia principis, qui (ut prudens definivit) inimicorum minuere numerum augereque amicorum sponte sua contendit ac libens.”", "st": "22.14"}, {"sp": "N", "t": "Exinde sacrorum perfecto ritu digresso, offeruntur rectoris Aegypti scripta, Apim bovem operosa quaesitum industria, tandem post tempus inveniri potuisse firmantis, quod (ut earum regionum existimant incolae) faustum, et ubertatem frugum diversaque indicans bona.", "st": "22.14"}, {"sp": "N", "t": "Super qua re pauca conveniet expediri. Inter animalia antiquis observationibus consecrata, Mnevis et Apis sunt notiora: Mnevis Soli sacratur, super quo nihil dicitur memorabile; sequens Lunae. Est enim Apis bos diversis genitalium notarum figuris expressus, maximeque omnium corniculantis lunae specie latere dextro insignis, qui cum post vivendi spatium praestitutum, sacro fonte immersus e vita abierit (nec enim ultra eum trahere licet aetatem, quam secreta librorum praescribit auctoritas mysticorum), necatur choragio pari, bos femina, quae ei inventa cum notis certis offertur, quo perempto alter cum publico quaeritur luctu, et si omnibus signis consummatus reperiri potuerit, ducitur Memphim, urbem praesentia frequenti numinis Aesculapii claram.", "st": "22.14"}, {"sp": "N", "t": "Cumque initiante antistitum numero centum, inductus in thalamum esse coeperit sacer, coniecturis apertis, signa rerum futurarum dicitur demonstrare, et adeuntes quosdam indiciis averti videtur obliquis, ut offerentem cibum aliquando Germanicum Caesarem (sicut lectum est) aversatus portenderat paulo post eventura.", "st": "22.14"}, {"sp": "N", "t": "Strictim itaque, quoniam tempus videtur hoc flagitare, res Aegyptiacae tangantur, quarum notitiam in actibus Hadriani et Severi principum digessimus late, visa pleraque narrantes.", "st": "22.15"}, {"sp": "N", "t": "Aegyptum gentem omnium vetustissimam, nisi quod super antiquitate certat cum Scythis, a meridiali latere Syrtes maiores et Phycus promuntorium et Borion et Garamantes nationesque varia claudunt; qua orientem e regione prospectat, Elephantinen et Meroen urbes Aethiopum, et Catadupos rubrumque pelagus, et Scenitas praetenditur Arabas, quos Sarracenos nunc appellamus; septentrioni supposita, terrarum situ cohaeret immenso, unde exordium Asia Syriarumque provinciae sumunt; a vespera Issiaco disiungitur mari, quod quidam nominavere Parthenium.", "st": "22.15"}, {"sp": "N", "t": "Pauca itaque super benivolo omnium flumine Nilo (quem Aegyptum Homerus appellat), praestringi conveniet, mox ostendendis aliis, quae sunt in his regionibus admiranda.", "st": "22.15"}, {"sp": "N", "t": "Origines fontium Nili, ut mihi quidem videri solet, sicut adhuc factum est, posterae quoque ignorabunt aetates. Verum quoniam fabulantes poetae variantesque geographi, in diversa latentem notitiam scindunt, opiniones eorum veritati confines, ut arbitror, expediam paucis.", "st": "22.15"}, {"sp": "N", "t": "Affirmant aliqui physicorum, in subiectis septentrioni spatiis cum hiemes frigidae cuncta constringunt, magnitudines nivium congelare, easque postea vi flagrantis sideris resolutas, fluxis umoribus nubes efficere gravidas, quae in meridianam plagam Etesiis flantibus pulsae, expressaeque tepore nimio incrementa ubertim suggerere Nilo creduntur.", "st": "22.15"}, {"sp": "N", "t": "Ex Aethiopicis imbribus, qui abundanter in tractibus illis per aestus torridos cadere memorantur, exundationes eius erigi anni temporibus asserunt alii praestitutis: quod utrumque dissonare videtur a veritate. Imbres enim apud Aethiopas aut numquam aut per intervalla temporum longa cadere memorantur.", "st": "22.15"}, {"sp": "N", "t": "Opinio est celebrior alia, quod spirantibus Prodromis, perque dies quadraginta et quinque, Etesiarum continuis flatibus repellentibus eius meatum, velocitate cohibita, superfusis fluctibus intumescit; et reluctante spiritu controverso adulescens in maius, hinc vi reverberante ventorum, inde urgente cursu venarum perennium, progrediens in sublime, contegit omnia, et humo suppressa, per supina camporum speciem exhibet maris.", "st": "22.15"}, {"sp": "N", "t": "Rex autem Iuba, Punicorum confisus textu librorum, a monte quodam oriri eum exponit, qui situs in Mauritania despectat oceanum, hisque indiciis hoc proditum ait, quod pisces et herbae et beluae similes per eas paludes gignuntur.", "st": "22.15"}, {"sp": "N", "t": "Aethiopiae autem partes praetermeans Nilus nominum diversitate decussa, quae ei orbem peragranti nationes indidere complures, aestuans inundatione ditissima, ad cataractas (id est praeruptos scopulos) venit, e quibus praecipitans, ruit potius quam fluit: unde Atos olim accolas usu aurium fragore assiduo deminuto, necessitas vertere solum ad quietiora coegit.", "st": "22.15"}, {"sp": "N", "t": "Exinde lenius means, per ostia septem, quorum singula perpetuorum amnium usum et faciem praebent, nullis per Aegyptum aquis externis adiutus eiectatur. Et praeter amnis plurimos ex alveo derivatos auctore, cadentesque in suppares eis, septem navigabiles sunt et undosi, quibus subiecta vocabula veteres indiderunt: Heracleoticus, Sebennyticus, Bolbiticus, Pathmiticus, Mendesius, Taniticus et Pelusiacus.", "st": "22.15"}, {"sp": "N", "t": "Oriens autem inde (ut dictum est) propellitur e paludibus ad usque cataractas, insulasque efficit plures, quarum aliquae ita porrectis spatiis dicuntur extentae, ut singulas aegre tertio die relinquat.", "st": "22.15"}, {"sp": "N", "t": "Inter quas duae sunt clarae, Meroe et Delta, a triquetrae litterae forma hoc vocabulo signatius appellata. Cum autem sol per Cancri sidus coeperit vehi, augescens ad usque transitum eius in Libram, diebusque centum sublatius fluens, minuitur postea, et mitigatis ponderibus aquarum, navibus antea pervios equitabiles campos ostendit.", "st": "22.15"}, {"sp": "N", "t": "Abunde itaque luxurians ita est noxius, ut infructuosus, si venerit parcior: gurgitum enim nimietate umectans diutius terras culturas moratur agrorum, parvitate autem minatur steriles segetes. Eumque nemo aliquando extolli cubitis altius sedecim possessor optavit. Et si inciderit moderatius, aliquotiens iactae sementes in loco praepinguis cespitis cum augmento fere septuagesimo renascuntur: solusque fluminum auras nullas exspirat.", "st": "22.15"}, {"sp": "N", "t": "Exuberat Aegyptus etiam pecudibus multis, inter quas terrestres sunt et aquatiles, aliaeque humi et in humoribus vivunt, unde ἀμφίβιοι nominantur. Et in aridis quidem capreoli vescuntur et bubali et spinturnicia omni deformitate ridicula, aliaque monstra quae enumerare non refert.", "st": "22.15"}, {"sp": "N", "t": "Inter aquatiles autem bestias, crocodilus ubique per eos tractus abundat, exitiale quadrupes malum, assuetum elementis ambobus, lingua carens, maxillam superiorem commovens solum, ordine dentium pectinato, perniciosis morsibus quicquid contigerit pertinaciter petens, per ova edens fetus anserinis similia.", "st": "22.15"}, {"sp": "N", "t": "Utque armatus est unguibus, si haberet etiam pollices, ad evertendas quoque naves sufficeret viribus magnis: ad cubitorum enim longitudinem octodecim interdum extentus, noctibus quiescens per undas, diebus humi vaporatur confidentia cutis, quam ita validam gerit, ut eius terga cataphracta vix tormentorum ictibus perforentur.", "st": "22.15"}, {"sp": "N", "t": "Et saevientes semper eaedem ferae (quasi pacto foedere quodam castrensi), per septem caerimoniosos dies mitescunt, ab omni saevitia desciscentes, quibus sacerdotes Memphi natales celebrant Nili.", "st": "22.15"}, {"sp": "N", "t": "Praeter eos autem, qui fortuita pereunt morte, alii dirumpuntur suffossis alvis mollibus serratis ferarum dorsualibus cristis, quas delphinis similes nutrit fluvius ante dictus, alii exitio intereunt tali.", "st": "22.15"}, {"sp": "N", "t": "Trochilus avicula brevis, dum escarum minutias captat, circa cubantem feram volitans blande, genasque eius irritatius titillando pervenit ad usque ipsam viciniam gutturis. Quod factum contuens enhydrus, ichneumonis genus, oris aditum penetrat alite praevia patefactum, et populato ventre, vitalibus dilancinatis erumpit.", "st": "22.15"}, {"sp": "N", "t": "Audax tamen crocodilus monstrum fugacibus; ubi audacem senserit, timidissimum; et in terra acutius cernens, per quattuor menses hibernos, nullo vesci dicitur cibo.", "st": "22.15"}, {"sp": "N", "t": "Hippopotami quoque generantur in illis partibus, ultra animalia cuncta ratione carentia sagacissimi, ad speciem equorum bifidos unquis habentes, caudasque breves, quorum sollertiae duo interim ostendere documenta sufficiet.", "st": "22.15"}, {"sp": "N", "t": "Inter arundines celsas, ut squalentes nimia densitate, haec belua cubilibus positis, otium pervigili studio circumspectat, laxataque copia, ad segetes depascendas egreditur. Cumque iam coeperit redire distenta, aversis vestigiis distinguit tramites multos, ne unius plani itineris lineas insidiatores secuti, repertum sine difficultate confodiant.", "st": "22.15"}, {"sp": "N", "t": "Item cum aviditate nimia extuberato ventre pigrescit, super calamos recens exsectos femora convolvit et crura, ut pedibus vulneratis cruor egestus sagina distentum faciat levem: et partes saucias caeno oblinit quam diu in cicatrices conveniant plagae.", "st": "22.15"}, {"sp": "N", "t": "Has monstruosas antehac raritates in beluis, in aedilitate Scauri vidit Romanus populus primitus, patris illius Scauri, quem defendens Tullius imperat Sardis, ut de familia nobili ipsi quoque cum orbis terrarum auctoritate sentirent, et per aetates exinde plures saepe huc ducti, nunc inveniri nusquam possunt, ut coniectantes regionum incolae dicunt, insectantis multitudinis taedio ad Blemmyas migrasse compulsi.", "st": "22.15"}, {"sp": "N", "t": "Inter Aegyptias alites, quarum varietas nullo comprehendi numero potest, ibis sacra est et amabilis, et innocua ideo, quod nidulis suis ad cibum suggerens ova serpentum, efficit ut rarescant mortiferae pestes absumptae.", "st": "22.15"}, {"sp": "N", "t": "Occurrunt eaedem volucres pinnatis agminibus anguium, qui ex Arabicis emergunt paludibus, venena maligna gignentes, mosque antequam finibus suis excedunt, proeliis superatos aeriis vorant, quas aves per rostra edere fetus accepimus.", "st": "22.15"}, {"sp": "N", "t": "Serpentes quoque Aegyptus alit innumeras, ultra omnem perniciem saevientes: basiliscos et amphisbaenas et scytalas, et acontias et dipsadas et viperas, aliasque complures, quas omnes magnitudine et decore aspis facile supereminens, numquam sponte sua fluenta egreditur Nili.", "st": "22.15"}, {"sp": "N", "t": "Multa in illis tractibus pretium est operae ac maxima cernere; e quibus pauca conveniet explicari. Templa ubique molibus magnis exstructa. Pyramides ad miracula septem provectae, quarum diuturnas surgendi difficultates scriptor Herodotus docet, ultra omnem altitudinem, quae humana manu confici potest, erectae sunt turres, ab imo latissimae in summitates acutissimas desinentes.", "st": "22.15"}, {"sp": "N", "t": "Quae figura apud geometras ideo sic appellatur, quod ad ignis speciem (τοῦ πυρὸς, ut nos dicimus) extenuatur in conum. Quarum magnitudo quoniam in celsitudinem nimiam scandens, gracilescit paulatim, umbras quoque mechanica ratione consumit.", "st": "22.15"}, {"sp": "N", "t": "Sunt et syringes subterranei quidam, et flexuosi secessus, quos (ut fertur) periti rituum vetustorum adventare diluvium praescii, metuentesque ne cerimoniarum oblitteraretur memoria, penitus operosis digestos fodinis per loca diversa struxerunt, et excisis parietibus volucrum ferarumque genera multa sculpserunt, et animalium species innumeras illas, quas hierographicas litteras appellarunt.", "st": "22.15"}, {"sp": "N", "t": "Dein Syene, in qua solstitii tempore, quo sol aestivum cursum extendit, recta omnia ambientes radii excedere ipsis corporibus umbras non sinunt. Inde si stipitem quisquam fixerit rectum, vel hominem aut arborem viderit stantem, circa lineamentorum ipsas extremitates contemplabitur umbras absumi, sicut apud Meroen, Aethiopiae partem aequinoctiali circulo proximam, dicitur evenire, ubi per nonaginta dies umbrae nostris in contrarium cadunt, unde Antiscios eius incolas vocant.", "st": "22.15"}, {"sp": "N", "t": "Quae quoniam miracula multa sunt, opusculi nostri propositum excedentia, ad ingenia celsa reiciamus, pauca super provinciis narraturi.", "st": "22.15"}, {"sp": "N", "t": "Tres provincias Aegyptus fertur habuisse temporibus priscis, Aegyptum ipsam et Thebaida et Libyam, quibus duas adiecit posteritas, ab Aegypto Augustamnicam et Pentapolim a Libya sicciore disparatam.", "st": "22.16"}, {"sp": "N", "t": "Igitur Thebais multas inter urbes clariores aliis Hermopolim habet, et Copton et Antinou, quam Hadrianus in honorem Antinoi ephebi condidit sui: hecatompylos enim Thebas nemo ignorat.", "st": "22.16"}, {"sp": "N", "t": "In Augustamnica Pelusium est oppidum nobile, quod Peleus Achillis pater dicitur condidisse, lustrari deorum monitu iussus in lacu, qui eiusdem civitatis alluit moenia, cum post interfectum fratrem nomine Phocum, horrendis furiarum imaginibus raptaretur, et Cassium, ubi Pompei sepulcrum est Magni, et Ostracine et Rhinocorura.", "st": "22.16"}, {"sp": "N", "t": "In Pentapoli Libya Cyrene est posita, urbs antiqua sed deserta, quam Spartanus condidit Battus, et Ptolemais et Arsinoe (eadem quae Teuchira) et Darnis et Berenice, quas Hesperidas appellant.", "st": "22.16"}, {"sp": "N", "t": "In sicciore vero Libye Paraetonion et Chaerecla et Neapolis inter municipia pauca et brevia.", "st": "22.16"}, {"sp": "N", "t": "Aegyptus ipsa, quae iam inde uti Romano imperio iuncta est, regio iure regitur a praefectis, exceptis minoribus multis, Athribi et Oxyryncho et Thmui et Memphi maximis urbibus nitet.", "st": "22.16"}, {"sp": "N", "t": "Alexandria enim vertex omnium est civitatum, quam multa nobilitant et magnifica, conditoris altissimi, et architecti sollertia Dinocratis, qui cum ampla moenia fundaret et pulchra, paenuria calcis ad momentum parum repertae, omnes ambitus lineales farina respersit, quod civitatem post haec alimentorum uberi copia circumfluere fortuito monstravit.", "st": "22.16"}, {"sp": "N", "t": "Inibi aurae salubriter spirant, et aer est tranquillus et clemens atque, ut periculum docuit, per varias collectum aetates, nullo paene die incolentes hanc civitatem solem serenum non vident.", "st": "22.16"}, {"sp": "N", "t": "Hoc litus cum fallacibus et insidiosis accessibus affligeret antehac navigantes discriminibus plurimis, excogitavit in portu Cleopatra turrim excelsam, quae Pharos a loco ipso cognominatur, praelucendi navibus nocturna suggerens ministeria, cum quondam ex Parthenio pelago venientes vel Libyco, per pandas oras et patulas, montium nullas speculas vel collium signa cernentes, harenarum illisae glutinosae mollitiae frangerentur.", "st": "22.16"}, {"sp": "N", "t": "Haec eadem regina heptastadium sicut vix credenda celeritate, ita magnitudine mira construxit, ob causam notam et necessariam. Insula Pharos, ubi Protea cum phocarum gregibus diversatum Homerus fabulatur inflatius, a civitatis litore mille passibus disparata, Rhodiorum erat obnoxia vectigali.", "st": "22.16"}, {"sp": "N", "t": "Quod cum hi die quodam nimium quantum petituri venissent, femina callida semper in fraudes, sollemnium specie feriarum eisdem publicanis secum ad suburbana perductis, opus iusserat inrequietis laboribus consummari, et septem diebus totidem stadia molibus iactis in mari solo propinquante, terrae sunt vindicata; equorumque cum vehiculo ingressa riserat Rhodios, insularum non continentis portorium flagitantes.", "st": "22.16"}, {"sp": "N", "t": "His accedunt altis sufflata fastigiis templa, inter quae eminet Serapeum, quod licet minuatur exilitate verborum, atriis tamen columnatis amplissimus, et spirantibus signorum figmentis, et reliqua operum multitudine ita est exornatum, ut post Capitolium, quo se venerabilis Roma in aeternum attollit, nihil orbis terrarum ambitiosius cernat.", "st": "22.16"}, {"sp": "N", "t": "In quo bybliothecae fuerunt inaestimabiles: et loquitur monumentorum veterum concinens fides, septingenta voluminum milia, Ptolomaeis regibus vigiliis intentis composita, bello Alexandrino, dum diripitur civitas, sub dictatore Caesare conflagrasse.", "st": "22.16"}, {"sp": "N", "t": "Canopus inde duodecimo disiungitur lapide, quem (ut priscae memoriae tradunt), Menelai gubernator sepultus ibi cognominavit. Amoenus impendio locus, et diversoriis laetis exstructus, auris et salutari temperamento perflabilis, ita ut extra mundum nostrum morari se quisquam arbitretur, in illis tractibus agens, cum saepe aprico spiritu immurmurantes audierit ventos.", "st": "22.16"}, {"sp": "N", "t": "Sed Alexandria ipsa non sensim (ut aliae urbes), sed inter initia prima aucta per spatiosos ambitus internisque seditionibus diu aspere fatigata, ad ultimum multis post annis, Aureliano imperium agente, civilibus iurgiis ad certamina interneciva prolapsis, dirutisque moenibus, amisit regionum maximam partem, quae Bruchion appellabatur, diuturnum praestantium hominum domicilium.", "st": "22.16"}, {"sp": "N", "t": "Unde Aristarchus grammaticae rei dumis excellens, et Herodianus artium minutissimus sciscitator, et Saccas Ammonius Plotini magister, aliique plurimi scriptores multorum in litteris nobilium studiorum, inter quos Chalcenterus eminuit Didymus, multiplicis scientiae copia memorabilis, qui in illis sex libris, ubi non numquam imperfecte Tullium reprehendit, sillographos imitatus, scriptores maledicos, iudicio doctarum aurium incusatur, ut immania frementem leonem trepidulis vocibus canis catulus longius circumlatrans.", "st": "22.16"}, {"sp": "N", "t": "Et quamquam veteres cum his quorum memini floruere complures, tamen ne nunc quidem in eadem urbe doctrinae variae silent; nam et disciplinarum magistri quodam modo spirant, et nudatur ibi geometrico radio quicquid reconditum latet, nondumque apud eos penitus exaruit musica, nec harmonia conticuit, et recalet apud quosdam adhuc (licet raros), consideratio mundani motus et siderum, doctique sunt alii numeros; pauci super his scientiam callent, quae fatorum vias ostendit.", "st": "22.16"}, {"sp": "N", "t": "Medicinae autem— cuius in hac vita nostra nec parca nec sobria, desiderantur adminicula crebra—ita studia augentur in dies ut (licet opus ipsum redoleat) pro omni tamen experimento sufficiat medico ad commendandam artis auctoritatem, Alexandriae si se dixerit eruditum.", "st": "22.16"}, {"sp": "N", "t": "Et haec quidem hactenus. Sed si intellegendi divini editionem multiplicem, et praesensionum originem mente vegeta quisquam volverit replicare, per mundum omnem inveniet mathemata huius modi ab Aegypto circumlata.", "st": "22.16"}, {"sp": "N", "t": "Ibi primum homines longe ante alios ad varia religionum incunabula (ut dicitur) pervenerunt et initia prima sacrorum caute tuentur condita scriptis arcanis.", "st": "22.16"}, {"sp": "N", "t": "Hac institutus prudentia Pythagoras colens secretius deos, quicquid dixit aut voluit auctoritatem esse instituit ratam, et femur suum aureum apud Olympiam saepe monstrabat, et cum aquila colloquens subinde visebatur.", "st": "22.16"}, {"sp": "N", "t": "Hinc Anaxagoras lapides e caelo lapsuros et putealem limum contrectans, tremores futuros praedixerat terrae. Et Solon sententiis adiutus Aegypti sacerdotum, latis iusto moderamine legibus, Romano quoque iuri maximum addidit firmamentum. Ex his fontibus per sublimia gradiens, sermonum amplitudine Iouis aemulus Platon, visa Aegypto militavit sapientia gloriosa.", "st": "22.16"}, {"sp": "N", "t": "Homines autem Aegyptii plerique subfusculi sunt et atrati, magisque maestiores, gracilenti et aridi, ad singulos motus excandescentes, controversi et reposcones acerrimi. Erubescit apud eos siqui non infitiando tributa, plurimas in corpore vibices ostendat. Et nulla tormentorum vis inveniri adhuc potuit, quae obdurato illius tractus latroni invito elicere potuit, ut nomen proprium dicat.", "st": "22.16"}, {"sp": "N", "t": "Id autem notum est (ut annales veteres monstrant), quod Aegyptus omnis sub avitis erat antea regibus, sed superatis apud Actium bello navali Antonio et Cleopatra, provinciae nomen accepit, ab Octaviano Augusto possessa. Aridiorem Libyam supremo Apionos regis consecuti sumus arbitrio, Cyrenas cum residuis civitatibus Libyae Pentapoleos, Ptolomaei liberalitate suscepimus. Evectus longius ad ordinem remeabo coeptorum.", "st": "22.16"}, {"sp": "HDR", "t": "Liber XXIII", "st": "23"}, {"sp": "N", "t": "Haec eo anno (ut praetereamus negotiorum minutias) agebantur. Iulianus vero iam tertio consul, adscito in collegium trabeae Sallustio praefecto per Gallias, quater ipse amplissimum inierat magistratum et videbatur novum adiunctum esse Augusto privatum, quod post Diocletianum et Aristobulum, nullus meminerat gestum.", "st": "23.1"}, {"sp": "N", "t": "Et licet accidentium varietatem sollicita mente praecipiens, multiplicatos expeditionis apparatus flagranti studio perurgeret, diligentiam tamen ubique dividens, imperiique sui memoriam, magnitudine operum gestiens propagare, ambitiosum quondam apud Hierosolymam templum, quod post multa et interneciva certamina, obsidente Vespasiano, posteaque Tito, aegre est expugnatum, instaurare sumptibus cogitabat immodicis, negotiumque maturandum Alypio dederat Antiochensi qui olim Britannias curaverat pro praefectis.", "st": "23.1"}, {"sp": "N", "t": "Cum itaque rei idem fortiter instaret Alypius, iuvaretque provinciae rector, metuendi globi flammarum prope fundamenta crebris assultibus erumpentes, fecere locum exustis aliquotiens operantibus inaccessum, hocque modo elemento destinatius repellente, cessavit inceptum.", "st": "23.1"}, {"sp": "N", "t": "Eisdem diebus, legatos ad se missos ab urbe aeterna, dare natos meritisque probabilis vitae compertos, imperator honoribus diversis affecit. Et Apronianum Romae decrevit esse praefectum, Octavianum proconsulem Africae, Venusto vicariam commisit Hispaniae, Rufinum Aradium comitem Orientis, in locum avunculi sui Iuliani, recens defuncti, provexit.", "st": "23.1"}, {"sp": "N", "t": "Quibus ut convenerat ordinatis, terrebatur omine quodam, ut docuit exitus, praesentissimo. Felice enim largitionum comite profluvio sanguinis repente exstincto, eumque comite Iuliano secuto, vulgus publicos contuens titulos, Felicem Iulianum Augustumque pronuntiabat.", "st": "23.1"}, {"sp": "N", "t": "Praecesserat aliud scaevum; namque kalendis ipsis Ianuariis ascendente eo gradile Genii templum, e sacerdotum consortio quidam ceteris diuturnior, nullo pulsante, repente concidit animamque insperato casu efflavit, quod adstantes (incertum per imperitiam an adulandi cupiditate), memorabant consulum seniori portendi, nimirum Sallustio, sed (ut apparuit) non aetati sed potestati maiori, interitum propinquare monstrabat.", "st": "23.1"}, {"sp": "N", "t": "Super his alia quoque minora signa subinde quod acciderat ostendebant. Inter ipsa enim exordia procinctus Parthici disponendi, nuntiatum est Constantinopolim terrae pulsu vibratam: quod horum periti minus laetum esse pronuntiabant aliena pervadere molienti rectori. Ideoque intempestivo conatu desistere suadebant, ita demum haec et similia contemni oportere firmantes, cum irruentibus armis externis, lex una sit et perpetua, salutem omni ratione defendere, nihil remittentem vigoris. Eisdem diebus nuntiatum est ei per litteras, Romae super hoc bello libros Sibyllae consultos, ut iusserat, imperatorem eo anno discedere a limitibus suis, aperto prohibuisse responso.", "st": "23.1"}, {"sp": "N", "t": "Inter haec tamen legationes gentium plurimarum auxilia pollicentium, liberaliter susceptae remittebantur, speciosa fiducia principe respondente, nequaquam decere adventiciis adiumentis rem vindicari Romanam, cuius opibus foveri conveniret amicos et socios, si auxilium eos adegerit necessitas implorare.", "st": "23.2"}, {"sp": "N", "t": "Solum Arsacem monuerat Armeniae regem, ut collectis copiis validis, iubenda operiretur, quo tenderet, quid deberet urgere, propere cogniturus. Proinde cum primam consultae rationes copiam praebuissent, rumore praecurso, hostiles occupare properans terras, nondum adulto vere, missa per militares numeros expeditionali tessera cunctos transire iussit Euphraten.", "st": "23.2"}, {"sp": "N", "t": "Quo comperto omnes evolant ex hibernis, transmissique (ut textus docebat scriptorum), dispersi per stationes varias adventum principis exspectabant. Ipse autem Antiochiam egressurus, Heliopoliten quendam Alexandrum, Syriacae iuris dictioni praefecit, turbulentum et saevum; dicebatque non illum meruisse, sed Antiochensibus avaris et contumeliosis huius modi iudicem convenire.", "st": "23.2"}, {"sp": "N", "t": "Cumque eum profecturum deduceret multitudo promiscua, itum felicem reditumque gloriosum exoptans, oransque ut deinde placabilis esset et lenior, nondum ira, quam ex compellationibus et probris conceperat, emollita, loquebatur asperius, se esse eos asserens postea non visurum.", "st": "23.2"}, {"sp": "N", "t": "Disposuisse enim aiebat, hiemandi gratia per compendiariam viam, consummate procinctu, Tarsum Ciliciae reversurum, scripsisseque ad Memorium praesidem, ut in eadem urbe cuncta usui congrua pararentur. Et hoc haud diu postea contigit. Corpus namque eius illuc relatum exsequiarum humili pompa, in suburbano sepultum est, ut ipse mandarat.", "st": "23.2"}, {"sp": "N", "t": "Iamque apricante caelo tertium nonas Martias profectus, Hierapolim solitis itineribus venit. Ubi cum introierit civitatis capacissimae portas, sinistra porticus subito lapsa, subter tendentes quinquaginta milites exceptis plurimis vulneratis, tignorum tegularumque pondere magno collisit.", "st": "23.2"}, {"sp": "N", "t": "Unde contractis copiis omnibus, Mesopotamiam propere signa commovit, ut fama de se nulla praeversa—id enim curatius observarat,—improvisus Assyrios occuparet. Denique cum exercitu et Scytharum auxiliis, Euphrate navali ponte transmisso, venit ad Batnas, municipium Osdroenae, ibique illaetabile portentum offendit.", "st": "23.2"}, {"sp": "N", "t": "Cum enim calonum frequens multitude ad suscipiendum consuete pabulum prope acervum palearum stetisset, impendio celsum—hoc enim modo per regiones illas tales species construuntur,—rapientibus multis, quassata congeries inclinata est, parique exitio quinquaginta obruit homines, mole maxima ruinarum.", "st": "23.2"}, {"sp": "N", "t": "Maestus exinde digressus, venit cursu propero Carras, antiquum oppidum, Crassorum et Romani exercitus aerumnis insigne. Unde duae ducentes Persidem viae regiae distinguuntur, laeva per Adiabenam et Tigridem, dextra per Assyrios et Euphraten.", "st": "23.3"}, {"sp": "N", "t": "Ibi moratus aliquot dies, dum necessaria parat, et Lunae (quae religiose per eos colitur tractus), ritu locorum fert sacra, dicitur ante aras, nullo arbitrorum admisso occulte paludamentum purpureum propinquo suo tradidisse Procopio, mandasseque arripere fidentius principatum, si se interisse didicerit apud Parthos.", "st": "23.3"}, {"sp": "N", "t": "Hic Iuliani quiescentis animus agitatus insomniis, eventurum triste aliquid praesagibat. Quocirca et ipse et visorum interpretes, praesentia contemplantes, diem secutum, qui erat quartum decimum kalendas Aprilis, observari debere pronuntiabant. Verum ut compertum est postea, hac eadem nocte Palatini Apollinis templum, praefecturam regente Aproniano, in urbe conflagravit aeterna, ubi ni multiplex iuvisset auxilium, etiam Cumana carmina consumpserat magnitudo flammarum.", "st": "23.3"}, {"sp": "N", "t": "Post quae ita digesta, agmina et commeatus omnis generis disponenti imperatori, procursatorum adventu anhelantium etiam tum indicatur, equestres hostium turmas vicino limite quodam perrupto, avertisse subito praedas.", "st": "23.3"}, {"sp": "N", "t": "Cuius atrocitate mali perculsus, ilico (ut ante cogitaverat) triginta milia lectorum militum eidem commisit Procopio, iuncto ad parilem potestatem Sebastiano comite ex duce Aegypti, eisdemque praecepit, ut intra Tigridem interim agerent, vigilanter omnia servaturi, nequid inopinum ex incauto latere oreretur, qualia multa saepe didicerat evenisse, mandabatque eis ut (si fieri potius posset), regi sociarentur Arsaci, cumque eo per Corduenam et Moxoenam, Chiliocomo uberi Mediae tractu, partibusque aliis praestricto cursu vastatis, apud Assyrios adhuc agenti sibi concurrerent, necessitatum articulis adfuturi.", "st": "23.3"}, {"sp": "N", "t": "His ita ordinatis, ipse exitu simulato per Tigrim, quod iter etiam re cibaria de industria iusserat instrui, flexit dextrorsus, et quieta nocte emensa, mane iumentum quo veheretur ex usu poposcit, oblatusque ei equus Babylonius nomine, ictu torminum consternatus, dum dolorum impatiens volvitur, auro lapillisque ornamenta distincta conspersit. Quo ostento laetior exclamavit, plaudentibus proximis, Babylona humi procidisse ornamentis omnibus spoliatam.", "st": "23.3"}, {"sp": "N", "t": "Et paulisper detentus, ut omen per hostias litando firmaret, Davanam venit castra praesidiaria, unde ortus Belias fluvius funditur in Euphraten. Hic corporibus cibo curatis et quiete, postridie ventum est ad Callinicum, munimentum robustum et commercandi opimitate gratissimum, ubi diem sextum kalendas Apriles, quo Romae Matri deorum pompae celebrantur annuales, et carpentum, quo vehitur simulacrum, Almonis undis ablui perhibetur, sacrorum sollemnitate prisco more completa, somno per otium capto, exsultans pernoctavit et laetus.", "st": "23.3"}, {"sp": "N", "t": "Luce vero secuta, profectus exinde per supercilia riparum fluvialium, aquis adulescentibus undique convenis, cum armigera gradiens manu, in statione quadam sub pellibus mansit, ubi Saracenarum reguli gentium, genibus supplices nixi, oblata ex auro corona, tamquam mundi nationumque suarum dominum adorarunt, suscepti gratanter, ut ad furta bellorum appositi.", "st": "23.3"}, {"sp": "N", "t": "Dumque hos alloquitur, Xerxis illius potentissimi regis instar, classis advenit, tribuno Constantiano cum comite Lucilliano ductante, quae latissimum flumen Euphraten artabat, in qua mille erant onerariae naves, ex diversa trabe confectae, commeatus abunde ferentes, et tela, et obsidionales etiam machinas, quinquaginta aliae bellatrices, totidemque ad compaginandos necessariae pontes.", "st": "23.3"}, {"sp": "N", "t": "Re ipsa admoneor, breviter quantum mediocre potest ingenium, haec instrumentorum genera ignorantibus circumscripte monstrare; et ballistae figura docebitur prima.", "st": "23.4"}, {"sp": "N", "t": "Ferrum inter axiculos duos firmum compaginatur et vastum in modum regulae maioris extentum, cuius ex volumine tereti, quod in medio pars polita componit, quadratus eminet stilus extentius, recto canalis angusti meatu cavatus, et hac multiplici chorda nervorum tortilium illigatus: eique cochleae duae ligneae coniunguntur artissime, quarum prope unam assistit artifex contemplabilis, et subtiliter apponit in temonis cavamine, sagittam ligneam spiculo maiore conglutinatam, hocque facto, hinc inde validi iuvenes versant agiliter rotabilem flexum.", "st": "23.4"}, {"sp": "N", "t": "Cum ad extremitatem nervorum acumen venerit summum, percita interno pulsu a ballista ex oculis avolat, interdum nimio ardore scintillans, et evenit saepius ut antequam telum cernatur, dolor letale vulnus agnoscat.", "st": "23.4"}, {"sp": "N", "t": "Scorpionis autem (quem appellant nunc Onagrum) huius modi forma est. Dolantur axes duo quernei vel ilicei, curvanturque mediocriter, ut prominere videantur in gibbas, hique in modum serratoriae machinae conectuntur ex utroque latere patentius perforati, quos inter per cavernas funes colligantur robusti, compagem (ne dissiliat) continentes.", "st": "23.4"}, {"sp": "N", "t": "Ab hac medietate restium ligneus stilus exsurgens obliquius, et in modum iugalis temonis erectus, ita nervorum nodulis implicatur, ut altius tolli possit et inclinari, summitatique eius unci ferrei copulantur, e quibus pendet stuppea vel ferrea funda, cui ligno fulmentum prosternitur ingens, cilicium paleis confertum minutis, validis nexibus illigatum, et locatum super congestos caespites vel latericios aggeres. Nam muro saxeo huius modi moles imposita disiectat quidquid invenerit subter concussione violenta, non pondere.", "st": "23.4"}, {"sp": "N", "t": "Cum igitur ad concertationem fuerit ventum, lapide rotundo fundae imposito, quaterni altrinsecus iuvenes repagula quibus incorporati sunt funes, explicantes retrorsus, stilum paene supinum inclinant: itaque demum sublimis adstans magister, claustrum quod totius operis continet vincula, reserat malleo forti perculsum, unde absolutus ictu volucri stilus, et mollitudine offensus cilicii, saxum contorquet, quicquid incurrerit collisurum.", "st": "23.4"}, {"sp": "N", "t": "Et tormentum quidem appellatur ex eo quod omnis explicatio torquetur, scorpio autem quoniam aculeum desuper habet erectum, cui etiam onagri vocabulum indidit aetas novella ea re, quod asini feri cum venatibus agitantur, ita eminus lapides post terga calcitrando emittunt, ut perforent pectora sequentium aut perfractis ossibus capita ipsa displodant.", "st": "23.4"}, {"sp": "N", "t": "Hinc ad arietem veniemus. Eligitur abies vel ornus excelsa, cuius summitas duro ferro concluditur et prolixo, arietis efficiens prominulam speciem, quae forma huic machinamento vocabulum indidit, et sic suspensa utrimque, transversis asseribus et ferratis, quasi ex lance vinculis trabis alterius continetur, eamque quantum mensurae ratio patitur, multitudo retro repellens, rursus ad obvia quaeque rumpenda protrudit, ictibus validissimis, instar adsurgentis et cedentis arietis Qua crebritate velut reciproci fulminis impetu aedificiis scissis in rimas, concidunt structurae laxatae murorum.", "st": "23.4"}, {"sp": "N", "t": "Hoc genere operis si fuerit exserto vigore discussum, nudatis defensoribus muris, ideoque solutis obsidiis, civitates munitissimae recluduntur.", "st": "23.4"}, {"sp": "N", "t": "Pro his arietum meditamentis iam crebritate despectis, conditur machina scriptoribus historicis nota, quam ἑλέπολιν Graeci cognominamus. Cuius opera diuturna Demetrius, Antigoni filius regis, Rhodo aliisque urbibus oppugnatis, Poliorcetes est appellatus.", "st": "23.4"}, {"sp": "N", "t": "Aedificatur autem hoc modo: testudo compaginatur immanis, axibus roborata longissimis, ferreisque clavis aptata, et contegitur coriis bubulis, virgarumque recenti textura, atque limo asperguntur eius suprema, ut flammeos detrectet et missiles casus.", "st": "23.4"}, {"sp": "N", "t": "Conseruntur autem eius frontalibus trisulcae cuspides praeacutae, ponderibus ferreis graves, qualia nobis pictores ostendunt fulmina vel fictores, ut quicquid petierit, aculeis exsertis abrumpat.", "st": "23.4"}, {"sp": "N", "t": "Hanc ita validam molem rotis et funibus regens, numerosus intrinsecus miles, languidiori murorum parti viribus admovet concitis, et nisi desuper propugnantium valuerint vires, collisis parietibus aditus patefacit ingentes.", "st": "23.4"}, {"sp": "N", "t": "Malleoli autem, teli genus, figurantur hac specie: sagitta est cannea, inter spiculum et harundinem multifido ferro coagmentata, quae in muliebris coli formam (quo nentur lintea stamina), concavatur ventre subtiliter, et plurifariam patens, atque in alveo ipso ignem cum aliquo suscipit alimento.", "st": "23.4"}, {"sp": "N", "t": "Et si emissa lentius arcu invalido,—ictu enim rapidiore exstinguitur,—haeserit usquam, tenaciter cremat, aquisque conspersa acriores excitat aestus incendiorum, nec remedio ullo quam superiacto pulvere consopitur. Hactenus de instrumentis muralibus, e quibus pauca sunt dicta. Nunc ad rerum ordinem revertamur.", "st": "23.4"}, {"sp": "N", "t": "Adscitis Saracenorum auxiliis, quae animis obtulere promptissimis, tendens imperator agili gradu Cercusium, principio mensis Aprilis ingressus est, munimentum tutissimum et fabre politum, cuius moenia Abora et Euphrates ambiunt flumina, velut spatium insulare fingentes.", "st": "23.5"}, {"sp": "N", "t": "Quod Diocletianus exiguum antehac et suspectum, muris turribusque circumdedit celsis, cum in ipsis barbarorum confiniis interiores limites ordinaret, documento recenti perterritus, ne vagarentur per Syriam Persae, ita ut paucis ante annis cum magnis provinciarum contigerat damnis.", "st": "23.5"}, {"sp": "N", "t": "Namque, cum Antiochiae in alto silentio, scaenicis ludis mimus cum uxore immissus, e medio sumpta quaedam imitaretur, populo venustate attonito, coniunx “Nisi somnus est” inquit “en Persae,” et retortis plebs universa cervicibus, ex arce volantia in se tela declinans, spargitur passim. Ita civitate incensa, et obtruncatis pluribus, qui pacis more palabantur effusius, incensisque locis finitimis et vastatis, onusti praeda hostes ad sua remearunt innoxii, Mareade vivo exusto, qui eos ad suorum interitum civium duxerat inconsulte. Et haec quidem Gallieni temporibus evenerunt.", "st": "23.5"}, {"sp": "N", "t": "Iulianus vero dum moratur apud Cercusium, ut per navalem Aborae pontem exercitus et omnes sequelae transirent, litteras tristes Sallusti, Galliarum praefecti, suscepit, orantis suspendi expeditionem in Parthos, obtestantisque, ne ita intempestive, nondum pace numinum exorata, irrevocabile subiret exitium.", "st": "23.5"}, {"sp": "N", "t": "Posthabito tamen suasore cautissimo, fidentius ultra tendebat, quoniam nulla vis humana vel virtus meruisse umquam potuit, ut quod praescripsit fatalis ordo non fiat. Statimque transgressus, pontem avelli praecepit, necui militum ab agminibus propriis revertendi fiducia remaneret.", "st": "23.5"}, {"sp": "N", "t": "Pari sorte hic quoque omen inlaetabile visum est, apparitoris cuiusdam cadaver extentum, carnificis manu deleti, quem praefectus Sallustius praesens, ea re supplicio capitali damnarat, quod intra praestitutum diem alimentorum augmentum exhibere pollicitus, casu impediente frustratus est. Sed miserando homine trucidato, postridie advenit, ut ille promiserat, alia classis, abunde vehens annonam.", "st": "23.5"}, {"sp": "N", "t": "Profecti exinde Zaitham venimus locum, qui olea arbor interpretatur. Hic Gordiani imperatoris longe conspicuum vidimus tumulum, cuius actus a pueritia prima, exercituumque felicissimos ductus, et insidiosum interitum, digessimus tempore competenti.", "st": "23.5"}, {"sp": "N", "t": "Ubi cum pro ingenita pietate consecrato principi parentasset, pergeretque ad Duram (desertum oppidum) procul militarem cuneum conspicatus, stetit immobilis, eique dubitanti quid ferrent, offertur ab eis immanissimi corporis leo, cum aciem peteret, multiplici telorum iactu confossus. Quo omine velut certiore iam spe status prosperioris elatus, exsultantius incedebat, sed incerto flatu fortunae, aliorsum prorupit eventus. Obitus enim regis portendebatur, sed cuius, erat incertum.", "st": "23.5"}, {"sp": "N", "t": "Nam et oracula dubia legimus, quae non nisi casus discrevere postremi, ut fidem vaticinii Delphici, quae post Halyn flumen transmissum, maximum regnum deiecturum praedixerat Croesum, et aliam quae Atheniensibus ad certandum contra Medos oblique destinaverat mare, sortemque his posteriorem, veram quidem, sed non minus ambiguam: aio te, Aeacida, Romanos vincere posse.", "st": "23.5"}, {"sp": "N", "t": "Etrusci tamen haruspices qui comitabantur gnaros prodigialium rerum, cum illis procinctum hunc saepe arcentibus, non crederetur, prolatis libris exercitualibus, ostendebant signum hoc esse prohibitorium, principique aliena licet iuste invadenti, contrarium.", "st": "23.5"}, {"sp": "N", "t": "Sed calcabantur philosophis refragantibus, quorum reverenda tunc erat auctoritas, errantium subinde, et in parum cognitis perseverantium diu. Et enim ut probabile argumentum ad fidem implendam scientiae suae, id praetendebant, quod et Maximiano antehac Caesari, cum Narseo Persarum rege iam congressuro, itidem leo et aper ingens trucidati simul oblati sunt, et superata gente discessit incolumis, illo minime contemplato, quod aliena petenti portendebatur exitium, et Narseus primus Armeniam Romano iuri obnoxiam occuparat.", "st": "23.5"}, {"sp": "N", "t": "Secuto itidem die, qui erat septimum idus Aprilis, sole vergente iam in occasum, ex parva nubecula subito aere crassato, usus adimitur lucis, et post minacem tonitruum crebritatem et fulgurum, Iovianus nomine miles ex caelo tactus cum duobus equis concidit, quos potu satiatos a flumine reducebat.", "st": "23.5"}, {"sp": "N", "t": "Eoque viso, harum rerum interpretes arcessiti, interrogatique etiam id vetare procinctum fidentius affirmabant, fulmen consiliarium esse monstrantes: ita enim appellantur quae dissuadent aliquid fieri vel suadent. Ideoque hoc nimis cavendum, quod militem celsi nominis cum bellatoriis iumentis exstinxit, et hoc modo contacta loca nec intueri nec calcari debere fulgurales pronuntiant libri.", "st": "23.5"}, {"sp": "N", "t": "Contra philosophi, candorem ignis sacri repente conspecti, nihil significare aiebant, sed esse acrioris spiritus cursum, ex aethere aliqua vi ad inferiora detrusum, aut si exinde praenoscitur aliquid, incrementa claritudinis imperatori portendi, gloriosa coeptanti, cum constet flammas suapte natura nullo obstante ad sublimia convolare.", "st": "23.5"}, {"sp": "N", "t": "Fracto igitur (ut ante dictum est) ponte, cunctisque transgressis, imperator antiquissimum omnium ratus est militem alloqui, sui rectorisque fiducia properantem intrepide. Signo itaque per lituos dato, cum centuriae omnes et cohortes et manipuli convenissent, ipse aggeri glebali assistens, coronaque celsarum circumdatus potestatum, talia ore sereno disseruit favorabilis studio concordi cunctorum:", "st": "23.5"}, {"sp": "N", "t": "“Contemplans maximis viribus et alacritate vos vigere, fortissimi milites, contionari disposui, docturus ratione multiplici, non nunc primitus (ut maledici mussitant) Romanos penetrasse regna Persidis. Namque ut Lucullum transeam vel Pompeium, qui per Albanos et Massagetas, quos Alanos nunc appellamus, hac quoque natione perrupta, adivit Caspios lacus, Ventidium novimus Antoni legatum, strages per hos tractus innumeras edidisse.", "st": "23.5"}, {"sp": "N", "t": "“Sed ut a vetustate discedam, haec quae tradidit recens memoria replicabo. Traianus et Verus et Severus hinc sunt digressi, victores et tropaeati, redissetque pari splendore iunior Gordianus, cuius monumentum nunc vidimus honorate, apud Resainan superato fugatoque rege Persarum, ni factione Philippi, praefecti praetorio, sceleste iuvantibus paucis, in hoc ubi sepultus est loco, vulnere impio cecidisset. Nec erravere diu manes eius inulti, quod velut facta librante Iustitia, omnes qui in eius conspiravere perniciem, cruciabilibus interiere suppliciis.", "st": "23.5"}, {"sp": "N", "t": "“Et illos quidem voluntas, ad altiora propensiores, subire impulit facinora memoranda, sors vero miseranda recens captarum urbium et inultae caesorum exercituum umbrae, et damnorum magnitudines castrorumque amissiones, ad haec quae proposuimus agenda hortantur, votis omnium sociis ut medeamur praeteritis, et roborata huius lateris securitate re publica, quae de nobis magnifice loquatur posteritas relinquamus.", "st": "23.5"}, {"sp": "N", "t": "“Adero ubique vobis, adiumento numinis sempiterni, imperator et antesignanus et conturmalis ominibus secundis (ut reor). At si fortuna versabilis in pugna me usquam fuderit, mihi vero pro Romano orbe memet vovisse sufficiet, ut Curtii Muciique veteres, et clara prosapia Deciorum. Abolenda nobis natio molestissima, cuius in gladiis nondum nostrae propinquitatis exaruit cruor.", "st": "23.5"}, {"sp": "N", "t": "“Plures absumptae sunt maioribus nostris aetates, ut interirent radicitus quae vexabant. Devicta est perplexo et diuturno Marte Carthago, sed eam dux inclytus timuit superesse victoriae. Evertit funditus Numantiam Scipio, post multiplices casus obsidionis emensos. Fidenas ne imperio subcrescerent aemulae Roma subvertit, et Faliscos ita oppressit et Veios, et suadere nobis laborat monumentorum veterum fides, ut has civitates aliquando valuisse credamus.", "st": "23.5"}, {"sp": "N", "t": "“Haec ut antiquitatum peritus exposui; superest ut aviditate rapiendi posthabita, quae insidiatrix saepe Romani militis fuit, quisque agmini cohaerens incedat, cum ad necessitatem congrediendi fuerit ventum, signa propria secuturus, sciens quod si remanserit usquam, exsectis cruribus relinquetur. Nihil enim praeter dolos et insidias hostium vereor, nimium callidorum.", "st": "23.5"}, {"sp": "N", "t": "“Ad summam polliceor universis, rebus post haec prospere mitigatis, absque omni praerogativa principum, qui quod dixerint vel censuerint, pro potestate auctoritatis iustum esse existimant, rationem me recte consultorum vel secus, siquis exegerit, redditurum.", "st": "23.5"}, {"sp": "N", "t": "“Quocirca erigite iam nunc, quaeso, erigite animos vestros, multa praesumentes et bona, aequata sorte nobiscum quicquid occurrerit difficile subituri, et coniectantes aequitati semper solere iungi victoriam.”", "st": "23.5"}, {"sp": "N", "t": "Conclusa oratione ad hunc gratissimum finem, ductoris gloria proeliator miles exsultans, speque prosperorum elatior, sublatis altius scutis, nihil periculosum fore vel arduum clamitabat, sub imperatore plus sibi laboris quam gregariis indicente.", "st": "23.5"}, {"sp": "N", "t": "Maxime omnium id numeri Gallicani fremitu laetiore monstrabant, memores aliquotiens eo ductante, perque ordines discurrente, cadentes vidisse gentes aliquas alias supplicantes.", "st": "23.5"}, {"sp": "N", "t": "Res adigit huc prolapsa ut in excessu celeri situm monstrare Persidis, descriptionibus gentium curiose digestis, in quibus aegre vera dixere paucissimi. Quod autem erit paulo prolixior textus, ad scientiam proficiet plenam. Quisquis enim affectat nimiam brevitatem ubi narrantur incognita non quid signatius explicet, sed quid debeat praeteriri, scrutatur.", "st": "23.6"}, {"sp": "N", "t": "Hoc regnum quondam exiguum, multisque antea nominibus appellatum, ob causas quas saepe rettulimus, cum apud Babylona Magnum fata rapuissent Alexandrum, in vocabulum Parthi concessit Arsacis, obscuro geniti loco, latronum inter adulescentiae rudimenta ductoris, verum paulatim in melius mutato proposito, clarorum contextu factorum aucti sublimius.", "st": "23.6"}, {"sp": "N", "t": "Qui post multa gloriose et fortiter gesta, superato Nicatore Seleuco, eiusdem Alexandri successore, cui victoriarum crebritas hoc indiderat cognomentum, praesidiisque Macedonum pulsis, ipse tranquillius agens temperator oboedientium fuit et arbiter lenis.", "st": "23.6"}, {"sp": "N", "t": "Denique post finitima cuncta vi vel aequitatis consideratione vel metu subacta, civitatum et castrorum castellorumque munimentis oppleta Perside, assuefactaque timori esse accolis omnibus, quos antea formidabat, medium ipse agens cursum aetatis placida morte decessit. Certatimque summatum et vulgi sententiis concinentibus, astris, ut ipsi existimant, ritus sui consecratione permixtus est omnium primus.", "st": "23.6"}, {"sp": "N", "t": "Unde ad id tempus reges eiusdem gentis praetumidi, appellari se patiuntur Solis fratres et Lunae, utque imperatoribus nostris Augusta nuncupatio amabilis est et optata, ita regibus Parthicis abiectis et ignobilibus antea, incrementa dignitatum felicibus Arsacis auspiciis accessere vel maxima.", "st": "23.6"}, {"sp": "N", "t": "Quam ob rem numinis eum vice venerantur et colunt, eo usque propagatis honoribus, ut ad nostri memoriam temporis, non nisi Arsacides (si sit usquam) in suscipiendo regno cunctis anteponatur, et in qualibet civili concertatione, quae assidue apud eos eveniunt, velut sacrilegium quisque caveat, ne dextra sua Arsaciden arma gestantem feriat vel privatum.", "st": "23.6"}, {"sp": "N", "t": "Satisque constat, hanc gentem regna populis vi superatis compluribus dilatasse ad usque Propontidem et Thracias, sed alte spirantium ducum superbia, licenter grassantium per longinqua, aerumnis maximis imminutam, primo per Cyrum, quem Bospori fretum cum multitudine fabulosa transgressum, ad internecionem delevit Tomyris, regina Scytharum, ultrix acerrima filiorum.", "st": "23.6"}, {"sp": "N", "t": "Deinde cum Dareus posteaque Xerxes, Graeciam elementorum usu mutato aggressi, cunctis paene copiis terra marique consumptis, vix ipsi tutum invenere discessum, ut bella praetereamus Alexandri, ac testamento nationem omnem in successoris unius iura translatam.", "st": "23.6"}, {"sp": "N", "t": "Quibus peractis, transcursisque temporibus longis sub consulibus et deinceps in potestatem Caesarum redacta re publica, nobiscum hae nationes subinde dimicarunt paribusque momentis interdum, aliquotiens superatae, non numquam abiere victrices.", "st": "23.6"}, {"sp": "N", "t": "Nunc locorum situm (quantum ratio sinit), carptim breviterque absolvam. Hae regiones in amplitudines diffusae longas et latas, ex omni latere insulosum et celebre, Persicum ambiunt mare, cuius ostia adeo esse perhibentur angusta, ut ex Harmozonte, Carmaniae promuntorio, contra oppositum aliud promuntorium, quod appellant incolae Maces, sine impedimento cernatur.", "st": "23.6"}, {"sp": "N", "t": "Quibus angustiis permeatis, cum latitudo patuerit nimis extensa, aequa navigatio ad usque urbem Teredona porrigitur, ubi post iacturas multiplices pelago miscetur Euphrates, omnisque sinus dimensione litorea in numerum viginti milium stadiorum velut spatio detornato, finitur, cuius per oras omnes oppidorum est densitas et vicorum, naviumque crebri discursus.", "st": "23.6"}, {"sp": "N", "t": "Ergo permeatis angustiis ante dictis venitur ad Carmaniae sinum orienti obiectum. Inde longo intervallo cantichus nomine panditur sinus australis, haut procul inde alius, quem vocant Chaliten occiduo obnoxius sideri. Hinc praestrictis pluribus insulis, e quibus paucae sunt notae, Indorum mari iunguntur oceano, qui ferventem solis exortum suscipit omnium primus, ipse quoque nimium calens.", "st": "23.6"}, {"sp": "N", "t": "Utque geographici stili formarunt, hac specie distinguitur omnis circuitus ante dictus. Ab arctoo cardine usque ad Caspias portas, Cadusiis conterminat et Scytharum gentibus multis et Arimaspis hominibus luscis et feris. Ab occidua plaga contingit Armenios et Niphaten et in Asia sitos Albanos, Mare Rubrum et Scenitas Arabas quos Saracenos posteritas appellavit: Mesopotamiam sub axe meridiali despectat: orienti a fronte contrarius ad Gangen extenditur flumen, quod Indorum intersecans terras, in pelagus eiectatur australe.", "st": "23.6"}, {"sp": "N", "t": "Sunt autem in omini Perside, hae regiones maximae, quas vitaxae (id est magistri equitum) curant, et reges et satrapae—nam minores plurimas recensere difficile est et superfluum—Assyria, Susiana, Media, Persis, Parthia, Carmania maior, Hyrcania, Margiana, Bactriani, Sogdiani, Sacae, Scythia infra Imaum et ultra eundem montem, Serica, Aria, Paropanisadae, Drangiana, Arachosia et Gedrosia.", "st": "23.6"}, {"sp": "N", "t": "Citra omnes propinqua est nobis Assyria, celebritate et magnitudine et multiformi feracitate ditissima. Quae per populos pagosque amplos diffusa quondam et copiosos, ad unum concessit vocabulum et nunc omnis appellatur Assyria, ubi inter bacarum vulgariumque abundantiam frugum, bitumen nascitur prope lacum nomine Sosingiten, cuius alveo Tigris voratus, fluensque subterraneus, percursis spatiis longis emergit.", "st": "23.6"}, {"sp": "N", "t": "hic et naphtha gignitur picea specie glutinosa, similis ipsa quoque bitumini, cui etiam si avicula insederit brevis, praepedito volatu submersa penitus evanescit. Et cum hoc liquoris ardere coeperit genus, nullum inveniet humana mens praeter pulverem exstinguendi commentum.", "st": "23.6"}, {"sp": "N", "t": "In his pagis hiatus quoque conspicitur terrae, unde halitus letalis exsurgens, quodcumque animal proxime steterit, odore gravi consumit. Quae lues oriens a profundo quodam puteo, cum os eius excesserit, si in latum ante quam sublimius vagaretur, terras circumsitas inhabitabiles acerbitate fecisset.", "st": "23.6"}, {"sp": "N", "t": "Cuius simile foramen apud Hierapolim Phrygiae antehac (ut asserunt aliqui), videbatur. Unde emergens itidem noxius spiritus, perseveranti odore quidquid prope venerat corrumpebat, absque spadonibus solis, quod qua causa eveniat, rationibus physicis permittatur.", "st": "23.6"}, {"sp": "N", "t": "Apud Asbamaei quoque Iovis templum in Cappadocia, ubi amplissimus ille philosophus Apollonius traditur natus prope oppidum Tyana, stagno effluens fons cernitur, qui magnitudine aquarum inflatus, seseque resorbens, numquam extra margines intumescit.", "st": "23.6"}, {"sp": "N", "t": "Intra hunc circuitum Adiabena est, Assyria priscis temporibus vocitata, longaque assuetudine ad hoc translata vocabulum, ea re quod inter Onam et Tigridem sita, navigeros fluvios, adiri vado numquam potuit: transire enim διαβαίνειν dicimus Graeci. Et veteres quidem hoc arbitrantur.", "st": "23.6"}, {"sp": "N", "t": "Nos autem dicimus quod in his terris amnes sunt duo perpetui, quos ipsi transivimus, Diabas et Adiabas, iunctis navalibus pontibus, ideoque intellegi Adiabenam cognominatam ut a fluminibus maximis Aegyptos, Homero auctore, et India et Euphratensis ante hoc Commagena, itidemque Hiberia ex Hibero (nunc Hispania) et a Baeti amne insigni provincia Baetica.", "st": "23.6"}, {"sp": "N", "t": "In hac Adiabena, Ninus est civitas, quae olim Persidis regna possederat, nomen Nini potentissimi quondam regis, Samiramidis mariti, declarans, et Ecbatana et Arbela et Gaugamela, ubi Dareum Alexander post discrimina varia proeliorum, incitato Marte prostravit.", "st": "23.6"}, {"sp": "N", "t": "In omni autem Assyria, multae sunt urbes. Inter quas Apamia eminet, Mesene cognominata, et Teredon et Apollonia et Vologessia, hisque similes multae. Splendidissimae vero et pervulgatae hae solae sunt tres: Babylon cuius moenia bitumine Samiramis struxit—arcem enim antiquissimus rex condidit Belus—et Ctesiphon, quam Vardanes temporibus priscis instituit, posteaque rex Pacorus, incolarum viribus amplificatam et moenibus, Graeco indito nomine, Persidis effecit specimen summum. Post hanc Seleucia ambitiosum opus Nicatoris Seleuci.", "st": "23.6"}, {"sp": "N", "t": "Qua per duces Veri Caesaris (ut ante rettulimus), expugnata, avulsum sedibus simulacrum Comei Apollinis, perlatumque Romam, in aede Apollinis Palatini deorum antistites collocarunt. Fertur autem quod post direptum hoc idem figmentum, incensa civitate, milites fanum scrutantes invenere foramen angustum, quo reserato, ut pretiosum aliquid invenirent, ex adyto quodam concluso a Chaldaeorum arcanis, labes primordialis exsiluit, quae insanabilium vi concepta morborum, eiusdem Veri Marcique Antonini temporibus, ab ipsis Persarum finibus ad usque Rhenum et Gallias, cuncta contagiis polluebat et mortibus.", "st": "23.6"}, {"sp": "N", "t": "His prope Chaldaeorum est regio, altrix philosophiae veteris, ut memorant ipsi, apud quos veridica vaticinandi fides eluxit. Perfluunt autem has easdem terras potiores ante alios amnes, hi quos praediximus, et Marses et Flumen Regium et Euphrates, cunctis excellens. Qui tripertitus navigabilis per omnes est rivos, insulasque circumfluens, et arva cultorum industria diligentius rigans, vomeri et gignendis arbustis habilia facit.", "st": "23.6"}, {"sp": "N", "t": "His tractibus Susiani iunguntur, apud quos non multa sunt oppida. Inter alia tamen eminet Susa, saepe domicilium regum, et Arsiana et Sele et Aracha. Cetera brevia sunt et obscura. Fluvii vero multi per haec loca discurrunt, quibus praestant Oroates et Harax et Mosaeus, per harenosas angustias, quae a Rubro prohibent Caspium mare, aequoream multitudinem inundantes.", "st": "23.6"}, {"sp": "N", "t": "At in laeva Media confinis Hyrcano panditur mari: quam ante regnum Cyri superioris, et incrementa Persidis, legimus Asiae reginam totius, Assyriis domitis, quorum plurimos pagos in Atropatenae vocabulum permutatos, belli iure possedit.", "st": "23.6"}, {"sp": "N", "t": "Pugnatrix natio et formidanda post Parthos, quibus vincitur solis, regiones inhabitans ad speciem quadratae figurae formatas. Harum terrarum incolae omnes ad latitudinem nimiam extenduntur, eisque maximae celsitudines imminent montium, quos Zagrum et Orontem et Iasonium vocant.", "st": "23.6"}, {"sp": "N", "t": "Coroni quoque montis altissimi partem habitantes occiduam, frumentariis agris affluunt et vinariis, pingui fecunditate laetissimi, et fluminibus fontiumque venis liquidis locupletes.", "st": "23.6"}, {"sp": "N", "t": "Edunt apud eos prata virentia fetus equorum nobilium, quibus (ut scriptores antiqui docent, nosque vidimus), ineuntes proelia viri summates vehi exsultantes solent, quos Nesaeos appellant.", "st": "23.6"}, {"sp": "N", "t": "Abundat itaque civitatibus ditibus Media, et vicis in modum oppidorum exstructis, et multitudine incolarum. Utque absolute dicatur, uberrimum est habitaculum regum.", "st": "23.6"}, {"sp": "N", "t": "In his tractibus Magorum agri sunt fertiles, super quorum secta studiisque, quoniam huc incidimus, pauca conveniet expediri. Magiam opinionum insignium auctor amplissimus Plato, hagistiam esse verbo mystico docet, divinorum incorruptissimum cultum, cuius scientiae saeculis priscis multa ex Chaldaeorum arcanis Bactrianus addidit Zoroastres, deinde Hystaspes rex prudentissimus, Darei pater.", "st": "23.6"}, {"sp": "N", "t": "Qui cum superioris Indiae secreta fidentius penetraret, ad nemorosam quandam venerat solitudinem, cuius tranquillis silentiis praecelsa Brachmanorum ingenia potiuntur, eorumque monitu, rationes mundani motus et siderum, purosque sacrorum ritus (quantum colligere potuit) eruditus, ex his, quae didicit, aliqua sensibus magorum infudit, quae illi cum disciplinis praesentiendi futura, per suam quisque progeniem, posteris aetatibus tradunt.", "st": "23.6"}, {"sp": "N", "t": "Ex eo per saecula multa ad praesens, una eademque prosapia, multitudo creata deorum cultibus dedicatur. Feruntque (si iustum est credi), etiam ignem caelitus lapsum apud se sempiternis foculis custodiri, cuius portionem exiguam (ut faustam) praeisse quondam Asiaticis regibus dicunt.", "st": "23.6"}, {"sp": "N", "t": "Huius originis apud veteres numerus erat exilis, eiusque ministeriis Persicae potestates in faciendis rebus divinis sollemniter utebantur. Eratque piaculum aras adire, vel hostiam contrectare, antequam magus, conceptis precationibus, libamenta diffunderet praecursoria. Verum aucti paulatim, in amplitudinem gentis solidae concesserunt et nomen, villasque inhabitantes, nulla murorum firmitudine communitas, et legibus suis uti permissi, religionis respectu sunt honorati.", "st": "23.6"}, {"sp": "N", "t": "Ex hoc magorum semine septem post mortem Cambysis, regnum inisse Persidos antiqui memorant libri, docentes eos Darei factione oppresses, imperitandi initium equino hinnitu sortiti.", "st": "23.6"}, {"sp": "N", "t": "In hac regione oleum conficitur Medicum, quo illitum telum, si emissum lentius laxiore arcu (nam ictu exstinguitur rapido) haeserit usquam, tenaciter cremat, et si aqua voluerit obruere quisquam, aestus excitat acriores incendiorum, nec remedio ullo quam iactu pulveris consopitur.", "st": "23.6"}, {"sp": "N", "t": "Paratur autem hoc modo. Oleum usus communis herba quadam infectum, condiunt harum rerum periti, ad diuturnitatem servantes et coalescens, dum ex materia venenatur. Alia similis oleo crassiori species gignitur apud Persas, quam (ut diximus) naphtam vocabulo appellavere gentili.", "st": "23.6"}, {"sp": "N", "t": "Per haec loca civitates dispersae sunt plures, quis omnibus praestant Zombis et Patigran et Gazaca. Inter quas opibus et magnitudine moenium conspicuae sunt Heraclia et Arsacia et Europos et Cyropolis et Ecbatana, sub Iasonio monte in terris sitae Syromedorum.", "st": "23.6"}, {"sp": "N", "t": "Amnes has regiones praetereunt multi quorum maximi sunt Choaspes et Gyndes et Amardus et Charinda et Cambyses et Cyrus, cui magno et specioso, Cyrus ille superior rex amabilis, abolito vetere, id vocabulum dedit, cum ereptum ire regna Scythica festinaret, quod et fortis est (ut ipse etiam ferebatur), et vias sibi ut ille impetu ingenti molitus in Caspium delabitur mare.", "st": "23.6"}, {"sp": "N", "t": "Per tractus meridianos expansa post haec confinia litoribus proxima Persis habitatur antiqua, minutis frugibus dives et palmite, aquarumque copia iucundissima. Amnes quippe multi per eam ante dictum influunt sinum, quorum maximi sunt Batradites et Rogomanius et Brisoana atque Bagrada.", "st": "23.6"}, {"sp": "N", "t": "Oppida vero mediterranea sunt ampliora—incertum enim qua ratione per oras maritimas nihil condiderunt insigne—inter quae Persepolis est clara et Ardea et Obroatis atque Tragonice. Insulae vero visuntur ibi tres tantum, Tabiana et Fara et Alexandria.", "st": "23.6"}, {"sp": "N", "t": "His propinquant Parthyaei, siti sub aquilone, colentes nivales terras et pruinosas, quorum regiones Choatres fluvius interscindit ceteris abundantior: et haec potiora residuis sunt oppida: Oenunia, Moesia, Charax, Apamia, Artacana et Hecatompylos a cuius finibus per Caspia litora ad usque portarum angustias stadia quadraginta numerantur et mille.", "st": "23.6"}, {"sp": "N", "t": "Feri sunt illic habitatores pagorum omnium atque pugnaces, eosque ita certamina iuvant et bella, ut iudicetur inter alios omnes beatus, qui in proelio profuderit animam. Excedentes enim e vita morte fortuita conviciis insectantur ut degeneres et ignavos.", "st": "23.6"}, {"sp": "N", "t": "Quibus ab orientali australique plaga Arabes beati conterminant, ideo sic appellati quod frugibus iuxta et fetibus et palmite odorumque suavitate multiplici sunt locupletes, magnaeque eorum partes mare rubrum a latere dextro contingunt, laeva Persico mari collimitant, elementi utriusque potiri bonis omnibus assueti.", "st": "23.6"}, {"sp": "N", "t": "Ubi et stationes et portus tranquilli sunt plures, et emporia densa, et diversoria regum ambitiosa nimium et decora, aquarumque suapte natura calentium saluberrimi fontes et rivorum fluminumque multitude perspicua, sospitalisque temperies caeli, ut recte spectantibus nihil eis videatur ad felicitatem deesse supremam.", "st": "23.6"}, {"sp": "N", "t": "Ac licet abundet urbibus mediterraneis atque maritimis, campisque copiosis et vallibus, has tamen civitates habet eximias: Geapolim et Nascon et Baraba, itidemque Nagara et Maepham et Tapphara et Dioscurida. Insulas autem complures habet per utrumque proximas mare, quas dinumerare non refert. Insignior tamen aliis Turgana est, in qua Serapidis maximum esse dicitur templum.", "st": "23.6"}, {"sp": "N", "t": "Post huius terminos gentis, Carmania maior verticibus celsis erigitur, ad usque Indicum pertinens mare, fructuariis arboreisque fetibus culta, sed obscurior Arabum terris multo et minor. Fluminibus tamen ipsa quoque non minus abundans, caespiteque ubere iuxta fecunda.", "st": "23.6"}, {"sp": "N", "t": "Amnes autem sunt hic ceteris notiores, Sagareus et Saganis et Hydriacus. Sunt etiam civitates, licet numero paucae, victu tamen et cultu perquam copiosae, inter quas nitet Carmana omnium mater et Portospana et Alexandria et Hermupolis.", "st": "23.6"}, {"sp": "N", "t": "Interius vero pergenti occurrunt Hyrcani, quos eiusdem nominis alluit mare. Apud quos glebae macie internecante sementes, ruris colendi cura est levior, sed vescuntur venatibus, quorum varietate immane quantum exuberant. Ubi etiam tigridum milia multa cernuntur, feraeque bestiae plures, quae cuiusmodi solent capi commentis, dudum nos meminimus rettulisse.", "st": "23.6"}, {"sp": "N", "t": "Nec ideo tamen stivam ignorant, sed seminibus teguntur aliquae partes, ubi solum est pinguius, nec arbusta desunt in locis habilibus ad plantandum, et marinis mercibus plerique sustentantur.", "st": "23.6"}, {"sp": "N", "t": "Hic amnes duo pervulgat sunt nominis, Oxus et Maxera, quos urgente inedia, superantes natatu, aliquotiens tigres improvisae finitima populantur. Habent etiam civitates inter minora municipia validas, duas quidem maritimas, Socanda et Saramanna, mediterraneas alias Asmurnam et Salen et his nobiliorem Hyrcanam.", "st": "23.6"}, {"sp": "N", "t": "Contra hanc gentem sub aquilone dicuntur Abii versari, genus piissimum, calcare cuncta mortalia consuetum, quos (ut Homerus fabulosius canit) Iuppiter ab Idaeis montibus contuetur.", "st": "23.6"}, {"sp": "N", "t": "Sedes vicinas post Hyrcanos sortiti sunt Margiani, omnes paene collibus altis undique circumsaepti, ideo a mari discreti. Et quamquam pleraque sunt ibi deserta soli aquarum penuria, quaedam tamen habent oppida; sed Iasonion et Antiochia et Nigaea sunt aliis notiora.", "st": "23.6"}, {"sp": "N", "t": "Proximos his limites possident Bactriani, natio antehac bellatrix et potentissima, Persisque semper infesta, antequam circumsitos populos omnes ad dicionem gentilitatemque traheret nominis sui, quam rexere veteribus saeculis etiam Arsaci formidabiles reges.", "st": "23.6"}, {"sp": "N", "t": "Eius pleraeque partes ita ut Margiana, procul a litoribus sunt disparatae, sed humi gignentium fertiles, et pecus quod illic per campestria loca vescitur et montana, membris est magnis compactum et validis, ut indicio sunt cameli, a Mithridate exinde perducti, et primitus in obsidione Cyzicena visi Romanis.", "st": "23.6"}, {"sp": "N", "t": "Gentes eisdem Bactrianis oboediunt plures, quas exsuperant Tochari, et ad Italiae speciem crebris fluminibus inundantur, E quibus Artamis et Zariaspes ante sibi consociati, itidemque Ochus et Dargomanes, iuncti convenis aquis augent immania Oxi fluenta.", "st": "23.6"}, {"sp": "N", "t": "Sunt et hic civitates, quas amnes diversi perstringunt, his cedentes ut melioribus, Chatracharta et Alicodra et Astacana et Menapilae et Bactris ipsis, unde regnum et vocabulum nationis est institutum.", "st": "23.6"}, {"sp": "N", "t": "Hinc Sogdiani agunt sub imis montium pedibus, quos appellant Sogdios, inter quos amnes duo fluunt navium capacissimi, Araxates et Dymas, qui per iuga vallesque praecipites, in campestrem planitiem fluvii decurrentes, Oxiam nomine paludem efficiunt, late longeque diffusam. Hie inter alia oppida celebrantur Alexandria et Cyreschata et Drepsa metropolis.", "st": "23.6"}, {"sp": "N", "t": "His contigui sunt Sacae natio fera, squalentia incolens loca, solum pecori fructuosa, ideo nec civitatibus culta. Cui Ascanimia mons imminet et Comedus. Praeter quorum radices et vicum, quem Lithinon pyrgon appellant, iter longissimum patet, mercatoribus pervium, ad Seras subinde commeantibus.", "st": "23.6"}, {"sp": "N", "t": "Circa defectus et crepidines montium, quos Imavos et Apurios vocant, Scythae sunt varii, intra Persicos fines Asianis contermini Sarmatis, Halanorumque latus tangentes extremum. Qui velut agentes quodam secessu, coalitique solitudine, per intervalla dispersi sunt longa, assueti victu vili et paupertino.", "st": "23.6"}, {"sp": "N", "t": "Et gentes quidem variae hos incolunt tractus, quas nunc recensere, alio properans, superfluum puto. Illud tamen sciendum est, inter has nationes paene ob asperitatem nimiam inaccessas homines esse quosdam mites et pios, ut Iaxartae sunt et Galactophagi, quorum meminit vates Homerus in hoc versu<br>γλακτοφάγων Ἀβίων τε δικαιοτάτων ἀνθρώπων.", "st": "23.6"}, {"sp": "N", "t": "Inter flumina vero multa, quae per has terras vel potioribus iungit natura, vel lapsu ipso trahit in mare, Rhymmus celebris est et Iaxartes, et Daicus. Civitates autem non nisi tres solas habere noscuntur, Aspabota et Chauriana et Saga.", "st": "23.6"}, {"sp": "N", "t": "Ultra haec utriusque Scythiae loca, contra orientalem plagam in orbis speciem consertae, celsorum aggerum summitates ambiunt Seras, ubertate regionum et amplitudine circumspectos, ab occidentali latere Scythis adnexos, a septentrione et orientali nivosae solitudini cohaerentes: qua meridiem spectant ad usque Indiam porrectos et Gangen. Appellantur autem ibidem montes Anniba et Auzacium et Asmira et Emodon et Oporocorra.", "st": "23.6"}, {"sp": "N", "t": "Hanc itaque planitiem undique prona declivitate praeruptam, terrasque lato situ distentas, duo famosi nominis flumina Oechardes et Bautis lentiore meatu percurrunt. Et dispar est tractuum diversorum ingenium: hic patulum alibi molli devexitate subductum, ideoque satietate frugum et pecoribus et arbustis exuberat.", "st": "23.6"}, {"sp": "N", "t": "Incolunt autem fecundissimam glebam variae gentes, e quibus Anthropophagi et Annibi et Sizyges et Chardi aquilonibus obiecti sunt et pruinis. Exortum vero solis suspiciunt Rabannae et Asmirae, et Essedones omnium splendidissimi, quibus Athagurae ab occidentali parte cohaerent et Aspacarae. Baetae vero australi celsitudine montium inclinati, urbibus licet non multis, magnis tamen celebrantur et opulentis, inter quas maximae Asmira et Essedon et Aspacara et Sera nitidae sunt et notissimae.", "st": "23.6"}, {"sp": "N", "t": "Agunt autem ipsi quietius Seres, armorum semper et proeliorum expertes, utque hominibus sedatis et placidis otium est voluptabile, nulli finitimorum molesti. Caeli apud eos iucunda salubrisque temperies, aeris facies munda, leniumque ventorum commodissimus flatus, et abunde silvae sublucidae, a quibus arborum fetus aquarum asperginibus crebris, velut quaedam vellera molientes, ex lanugine et liquore mixtam subtilitatem tenerrimam pectunt, nentesque subtegmina conficiunt sericum, ad usus nobilium antehac, nunc etiam infimorum sine ulla discretione proficiens.", "st": "23.6"}, {"sp": "N", "t": "Ipsi praeter alios frugalissimi pacatioris vitae cultores, vitantes reliquorum mortalium coetus. Cumque ad coemenda fila vel quaedam alia fluvium transierint advenae, nulla sermonum vice propositarum rerum pretia solis oculis aestimantur, et ita sunt abstinentes, ut apud se tradentes gignentia, nihil ipsi comparent adventicium.", "st": "23.6"}, {"sp": "N", "t": "Ariani vivunt post Seras, Boreae obnoxii flatibus, quorum terras amnis vehendis sufficiens navibus, Arias perfluit nomine, faciens lacum ingentem, eodem vocabulo dictitatum. Abundat autem haec eadem Aria oppidis, inter quae sunt celebria Vitaxa Sarmatina et Sotira et Nisibis et Alexandria, unde naviganti ad Caspium mare quingenta stadia numerantur et mille.", "st": "23.6"}, {"sp": "N", "t": "His locis Paropanisadae sunt proximi, Indos ab oriente, Caucasumque ab occidentali latere prospectantes, ipsi quoque montium defectibus inclinati, quos residuis omnibus maior, Gordomaris interluit fluvius a Bactrianis exsurgens. Habent autem etiam civitates aliquas, quibus clariores sunt Agazaca et Naulibus et Ortospana, unde litorea navigatio ad usque Mediae fines, portis proximos Caspiis stadiorum sunt duo milia et ducenta.", "st": "23.6"}, {"sp": "N", "t": "Ante dictis continui sunt Drangiani collibus cohaerentes, quos flumen alluit Arabium nomine ideo appellatum, quod inde exoritur, interque alia duobus municipiis exultantes, Prophthasia et Ariaspe, ut opulentis et claris.", "st": "23.6"}, {"sp": "N", "t": "Post quos exadversum Arachosia visitur, dextrum vergens in latus, Indis obiecta, quam ab Indo fluviorum maximo (unde regiones cognominatae sunt) amnis multo minor exoriens, aquarum alluit amplitudine, efficitque paludem quam Arachotoscrenen appellant. Hic quoque civitates sunt inter alias viles, Alexandria et Arbaca et Choaspa.", "st": "23.6"}, {"sp": "N", "t": "At in penitissima parte Persidos, Gedrosia est dextra terminos contingens Indorum, inter minores alios Arabio uberior flumine, ubi montes deficiunt Arbitani, quorum ex pedibus imis emergentes alii fluvii Indo miscentur, amittentes nomina magnitudine potioris. Civitates autem etiam hic sunt inclyta epraeter insulas, sed Ratira et Gynaecon limen meliores residuis aestimantur.", "st": "23.6"}, {"sp": "N", "t": "Ne igitur orae maritimae spatia alluentia Persidos extremitates per minutias demonstrantes, a proposito longius aberremus, id sufficiet dici, quod mare praetentum a Caspiis montibus per borium latus ad usque memoratas angustias, novem milium stadiorum, australe vero ab ostiis Nili fluminis ad usque principia Carmanorum, quattuordecim milium stadiorum numero definitur.", "st": "23.6"}, {"sp": "N", "t": "Per has nationes dissonas et multiplices, hominum quoque diversitates sunt ut locorum. Sed ut generaliter corpora describamus, et mores, graciles paene sunt omnes, subnigri vel livido colore pallentes, caprinis oculis torvi, et superciliis in semiorbium speciem curvatis iunctisque, non indecoribus barbis, capillisque promissis hirsuti, omnes tamen promiscue vel inter epulas festosque dies gladiis cincti cernuntur. Quem Graecorum veterum morem abiecisse primos Athenienses, Thucydides est auctor amplissimus.", "st": "23.6"}, {"sp": "N", "t": "Effusius plerique soluti in venerem, aegreque contenti multitudine pelicum, puerilium stuprorum expertes, pro opibus quisque adsciscens matrimonia plura vel pauca. Unde apud eos per libidines varias caritas dispersa torpescit, munditias conviviorum et luxum maximeque potandi aviditatem vitante ut luem.", "st": "23.6"}, {"sp": "N", "t": "Nec apud eos extra regales mensas hora est praestituta prandendi, sed venter uni cuique velut solarium est, eoque monente quod incident editur, nec quisquam post satietatem superfluos sibi ingerit cibos.", "st": "23.6"}, {"sp": "N", "t": "Inmane quantum restricti et cauti, ut inter hostiles hortos gradientes non numquam et vineta, nec cupiant aliquid nec contingant, venenorum et secretarum artium metu.", "st": "23.6"}, {"sp": "N", "t": "Super his nec stando mingens nec ad requisita naturae secedens, facile visitur Persa: ita observantius haec aliaque pudenda declinant.", "st": "23.6"}, {"sp": "N", "t": "Adeo autem dissoluti sunt et artuum laxitate, vagoque incessu se iactitantes, ut effeminatos existimes, cum sint acerrimi bellatores, sed magis artifices quam fortes, eminusque terribiles, abundantes inanibus verbis, insanumque loquentes et ferum, magnidici et graves ac taetri, minaces iuxta in adversis rebus et prosperis, callidi superbi crudeles, vitae necisque potestatem in servos et plebeios vindicantes obscuros: cutes vivis hominibus detrahunt, particulatim vel solidas, nec ministranti apud eos famulo mensaeque adstanti, hiscere vel loqui licet vel spuere: ita praestratis pellibus labra omnium vinciuntur.", "st": "23.6"}, {"sp": "N", "t": "Leges apud eos impendio formidatae, inter quas diritate exsuperant latae contra ingratos et desertores, et abominandae aliae per quas ob noxam unius, omnis propinquitas perit.", "st": "23.6"}, {"sp": "N", "t": "Ad iudicandum autem usu rerum spectati destinantur et integri, parum alienis consiliis indigentes, unde nostram consuetudinem rident, quae interdum facundos, iurisque publici peritissimos, post indoctorum collocat terga. Nam quod supersidere corio damnati ob iniquitatem iudicis, iudex alius cogebatur, aut finxit vetustas, aut olim recepta consuetudo cessavit.", "st": "23.6"}, {"sp": "N", "t": "Militari cultu ac disciplina proludiisque continuis rei castrensis et armaturae, quam saepe formavimus, metuendi vel exercitibus maximis, equitatus virtute confisi, ubi desudat nobilitas omnis et splendor. Pedites enim in speciem mirmillonum contecti, iussa faciunt ut calones. Sequiturque semper haec turba, tamquam addicta perenni servitio, nec stipendiis aliquando fulta nec donis. Et gentes plurimas praeter eas quas abunde perdomuit, sub iugum haec natio miserat, ita audax et ad pulveres Martios erudita, ni bellis civilibus externisque assidue vexarentur.", "st": "23.6"}, {"sp": "N", "t": "Indumentis plerique eorum ita operiuntur lumine colorum fulgentibus vario, ut (licet sinus lateraque dissuta relinquant flatibus agitari ventorum) inter calceos tamen et verticem nihil videatur intectum. Armillis uti monilibusque aureis, et gemmis, praecipue margaritis, quibus abundant, assuefacti post Lydiam victam et Croesum.", "st": "23.6"}, {"sp": "N", "t": "Restat ut super ortu lapidis huius, pauca succinctius explicentur. Apud Indos et Persas, margaritae reperiuntur in testis marinis robustis et candidis, permixtione roris anni tempore praestituto conceptae. Cupientes enim velut coitum quendam, humores ex lunari aspergine capiunt, densius oscitando. Exindeque gravidulae, edunt minutas binas aut ternas, vel uniones, ideo sic appellatas quod evisceratae conchulae singulas aliquotiens pariunt, sed maiores.", "st": "23.6"}, {"sp": "N", "t": "Idque indicium est aetheria potius derivatione, quam saginis pelagi hos oriri fetus et vesci, quod guttae matutini roris eisdem infusae, claros efficiunt lapillos et teretes, vespertini vero flexuosos contra et rutilos et maculosos interdum. Minima autem vel magna pro qualitate haustuum figurantur, casibus variatis. Conclusae vero saepissime metu fulgurum inanescunt, aut debilia pariunt, aut certe vitiis diffluunt abortivis.", "st": "23.6"}, {"sp": "N", "t": "Capturas autem difficiles et periculosas, et amplitudines pretiorum illa efficit ratio, quod frequentari sueta litora propter piscantium insidias declinantes, ut quidam coniciunt, circa devios scopulos et marinorum canum receptacula delitescunt.", "st": "23.6"}, {"sp": "N", "t": "Quod genus gemmae etiam in Britannici secessibus maris gigni legique (licet dignitate dispari) non ignoramus.", "st": "23.6"}, {"sp": "HDR", "t": "Liber XXIV", "st": "24"}, {"sp": "N", "t": "Post exploratam alacritatem exercitus, uno parique ardore impetrabilem principem superari non posse, deum usitato clamore testati, Iulianus summae rei finem imponendum maturius credens, restricta quiete nocturna, itinerarium sonare lituos iubet et praestructis omnibus quae difficultates arduae belli poscebant, candente iam luce, Assyrios fines ingressus, celso praeter alios spiritu obequitans ordinibus, aemulatione sui cunctos ad officia fortitudinis incendebat.", "st": "24.1"}, {"sp": "N", "t": "Utque ductor usu et docilitate firmatus, metuens ne per locorum insolentiam insidiis caperetur occultis, agminibus incedere quadratis exorsus est. Excursatores quidem quingentos et mille sensim praeire disposuit, qui cautius gradientes ex utroque latere, itidemque a fronte, nequis repentinus irrueret, prospectabant. Ipse vero medios pedites regens, quod erat totius roboris firmamentum, dextra legiones aliquas cum Nevitta, supercilia fluminis praestringere iussit Euphratis. Cornu vero laevum cum equitum copiis Arintheo tradidit et Ormizdae, ducendum confertius, per plana camporum et mollia. Agmina vero postrema Dagalaifus cogebat et Victor, ultimusque omnium Osdruenae dux Secundinus.", "st": "24.1"}, {"sp": "N", "t": "Deinde ut hostibus (si erupissent usquam) vel conspicantibus procul timorem multitudinis maioris incuteret, laxatis cuneis iumenta dilatavit et homines, ut decimo paene lapide postremi dispararentur a signiferis primis, quod arte mira saepe fecisse, Pyrrhus ille rex dicitur Epirotes, opportunis in locis castra metandi, armorumque speciem diffundendi ex industria vel attenuandi perquam scientissimus, ut ubi convenisset plures aestimarentur aut pauci.", "st": "24.1"}, {"sp": "N", "t": "Sarcinas vero et calones et apparationem imbellem, impedimentorumque genus omne inter utrumque latus instituit procedentium ordinatim, nequa vi subita raperentur (ut saepe contigit) improtecta. Classis autem licet per flumen ferebatur assiduis flexibus tortuosum, nec residere nec praecurrere sinebatur.", "st": "24.1"}, {"sp": "N", "t": "Emenso itaque itinere bidui, prope civitatem venimus Duram desertam, marginibus amnis impositam. In quo loco greges cervorum plures inventi sunt, quorum alii confixi missilibus, alii ponderibus inlisi remorum, ad satietatem omnes paverunt; pars maxima natatu assueta veloci, alveo penetrate, incohibili cursu evasit ad solitudines notas.", "st": "24.1"}, {"sp": "N", "t": "Exin dierum quattuor itinere levi peracto vespera incedente, cum expeditis mille impositis navibus, Lucillianus comes imperatu principis mittitur Anathan munimentum expugnaturus, quod (ut pleraque alia) circumluitur fluentis Euphratis. Et navibus (ut praeceptum est) per opportuna dispersis, insula obsidebatur nebulosa nocte obumbrante impetum clandestinum.", "st": "24.1"}, {"sp": "N", "t": "Sed postquam advenit lux certa, aquatum quidam egressus, visis subito hostibus, ululabili clamore sublato, excitos tumultuosis vocibus propugnatores armavit. Et mox a specula quadam altissima explorato situ castrorum, quam ocissime cum duarum praesidio navium, amnem supermeat imperator, pone sequentibus navigiis multis, quae obsidionales machinas advehebant.", "st": "24.1"}, {"sp": "N", "t": "Iamque muris propinquans, cum non absque discriminibus multis consideraret esse certandum, sermone cum leni tum aspero et minaci, hortabatur ad deditionem defensores, qui ad colloquium petito Ormizda, promissis eius et iuramentis illecti, multa sibi de lenitudine Romana spondebant.", "st": "24.1"}, {"sp": "N", "t": "Denique prae se bovem coronatum agentes, quod est apud eos susceptae pacis indicium, descendere suppliciter, et statim munimento omni incenso, Pusaeus eius praefectus, dux Aegypti postea, honore tribunatus affectus est. Reliqui vero cum caritatibus suis et supellectili, humaniore cultu ad Syriacam civitatem Chalcida transmissi sunt.", "st": "24.1"}, {"sp": "N", "t": "Inter hos miles quidam, cum Maximianus perrupisset quondam Persicos fines, in his locis aeger relictus, prima etiam tum lanugine iuvenis, ut aiebat, uxores sortitus gentis ritu complures cum numerosa subole tunc senex incurvus, exultans, proditionisque auctor, ducebatur ad nostra, testibus affirmans et praescisse se olim et praedixisse, quod centenario iam contiguus, sepelietur in solo Romano. Post quae Saraceni procursatores partis cuiusdam hostium obtulere laetissimo principi, et munerati ad agenda similia sunt remissi.", "st": "24.1"}, {"sp": "N", "t": "Acciderat aliud postridie dirum. Ventorum enim turbo exortus, pluresque vertigines concitans, ita confuderat omnia, ut tabernacula multa conscinderentur, et supini plerique milites sternerentur vel proni, venti spiritu stabilitatem vestigii subvertente. Nec minus eodem die aliud periculosum evenit. Amne enim repente extra margines evagato, mersae sunt quaedam frumentariae naves, cataractis avulsis, ad defundendas reprimendasque aquas rigare suetas opere saxeo structis: quod utrum per insidias an magnitudine acciderit fluentorum, sciri non potuit.", "st": "24.1"}, {"sp": "N", "t": "Post perruptam incensamque urbem omnium primam, et captivos transmissos, certiore iam spe provectus exercitus ad fiduciam, elatis vocibus in favores principis consurgebat, adfore sibi etiam deinde dei caelestis existimans curam.", "st": "24.1"}, {"sp": "N", "t": "Et cui per regiones ignotas de obscuris erat suspectior cura, astus gentis et ludificandi varietas timebatur. Ideoque imperator nunc antesignanus nunc agminibus cogendis insistens, cum expeditis velitibus, nequid lateret abstrusum, frutecta squalida vallesque scrutabatur, licentiores militum per longinqua discursus affabilitate nativa prohibendo vel minis.", "st": "24.1"}, {"sp": "N", "t": "Hostiles tamen agros omni frugum genere divites, cum segetibus et tuguriis inflammari permisit, ita demum cum usui necessaria abunde sibi quisque collegisset, et hoc modo sauciabatur salus hostium nesciorum.", "st": "24.1"}, {"sp": "N", "t": "Bellatores enim libenter quaesitis dextris propriis utebantur, alia virtutis suae horrea repperisse existimantes, et laeti quod vitae subsidiis affluentes, alimenta servabant, quae navigiis vehebantur.", "st": "24.1"}, {"sp": "N", "t": "Hic vino gravis quidam temerarius miles ad ulteriorem ripam nullo urgente transgressus, in conspectu nostro ab hostilibus captus, occisus est.", "st": "24.1"}, {"sp": "N", "t": "Quibus tali casu patratis, ad castra pervenimus nomine Thilutha, in medio fluminis sita, locum immenso quodam vertice tumescentem, et potestate naturae, velut manu circumsaeptum humana, cuius ad deditionem incolae temptati mollius (ut decebat), quoniam asperitas edita vim superabat armorum, intempestivam tunc defectionem esse firmabant. Sed hactenus responderunt, quod cum interiora occupaverint protinus gradientes Romani, se quoque utpote regnorum sequellas, victoribus accessuros.", "st": "24.2"}, {"sp": "N", "t": "Et post haec praetermeantes moenia ipsa, naves nostras verecunda quiete spectabant immobiles. Quo transito cum ad munimentum aliud Achaiachalam nomine venissemus, fluminis circumitione vallatum, arduumque transcensu, refutati pari responso discessimus. Alia postridie castra ob muros invalidos derelicta, praetereuntur incensa.", "st": "24.2"}, {"sp": "N", "t": "Postera igitur et insequenti die stadiis ducentis emensis, ventum est ad locum Baraxmalcha. Unde amne transito miliario septimo disparata, Diacira invaditur civitas, habitatoribus vacua, frumento et salibus nitidis plena, in qua templum alti culminis arci vidimus superpositum, qua incensa caesisque mulieribus paucis, quae repertae sunt, traiecto fonte scatenti bitumine, Ozogardana occupavimus oppidum, quod formidine advenientis exercitus itidem deseruere cultores. In quo principis Traiani tribunal ostendebatur.", "st": "24.2"}, {"sp": "N", "t": "Hac quoque exusta, biduo ad refectionem corporum dato, prope extremum noctis quae secundum diem secuta est, Surena post regem apud Persas promeritae dignitatis, et Malechus Podosacis nomine, phylarchus Saracenorum Assanitarum, famosi nominis latro, omni saevitia per nostros limites diu grassatus, structis Ormizdae insidiis, quem ad speculandum exiturum (incertum unde) praesenserant, ideo sunt temptamento frustrati, quod angusta fluminis interluvies et praealta transiri vado non potuit.", "st": "24.2"}, {"sp": "N", "t": "Et primo lucis exordio, cum essent hostes iam in contuitu, visi tune primitus corusci galeis et horrentes indutibus rigidis, milites in procinctum impetu veloci tendentes, eos involavere fortissime. Et quamvis arcus validis viribus flecterentur, et splendor ferri intermicans, Romanorum metum augeret, ira tamen acuente virtutem, clipeorum densitate contecti, ne possint emittere, coegerunt.", "st": "24.2"}, {"sp": "N", "t": "Animatus his vincendi primitiis, miles ad vicum Macepracta pervenit, in quo semiruta murorum vestigia videbantur, qui priscis temporibus in spatia longa protenti, tueri ab externis incursibus Assyriam dicebantur.", "st": "24.2"}, {"sp": "N", "t": "Hinc pars fluminis scinditur, largis aquarum agminibus ducens ad tractus Babylonios interiores, usui agris futura et civitatibus circumiectis, alia Naarmalcha nomine, quod fluvius regum interpretatur, Ctesiphonta praetermeat, cuius in exordio turris in modum Phari celsior surgit. Hanc peditatus omnis pontibus caute digestis, transivit.", "st": "24.2"}, {"sp": "N", "t": "Equites vero cum iumentis armati, clementiores gurgites fluminis obliquati transnarunt, pars flumine absumpta interierunt, alia multitudine subita petiti telorum hostilium. Quos egressi auxiliares ad cursum levissimi, fugientiumque cervicibus insistentes. laniatu avium prostraverunt.", "st": "24.2"}, {"sp": "N", "t": "Quo negotio itidem gloriose perfecto, ad civitatem Pirisaboram ventum est, amplam et populosam, ambitu insulari circumvallatam. Cuius obequitans moenia imperator et situm, obsidium omni cautela coeptabat, quasi sola formidine oppidanos a propugnandi studio summoturus. Quibus per colloquia saepe temptatis, cum nec promissis quisquam flecteretur nec minis, suscipitur oppugnandi exordium, et armatorum triplici corona circumdatis muris, a die primo ad usque noctis initium, missilibus certabatur.", "st": "24.2"}, {"sp": "N", "t": "Tum defensores animo praestantes et viribus, per propugnacula ciliciis undique laxius pansis, quae telorum impetus cohiberent, obtecti scutis vimine firmissimo textis et crudorum tergorum densitate vestitis, validissime resistebant, ferrea nimirum facie omni: quia lamminae singulis membrorum lineamentis cohaerenter aptatae, fido operimento, totam hominis speciem contegebant.", "st": "24.2"}, {"sp": "N", "t": "Et aliquotiens Ormizdae ut indigenae et regalis colloquia petentes obnixe, propinquantem probris atque conviciis ut male fidum incessebant et desertorem. Hac lenta cavillatione diei maxima parte exempta, tenebrarum silentio primo, multiformes admotae sunt machinae, coeptaque altitudo complanari fossarum.", "st": "24.2"}, {"sp": "N", "t": "Quae vixdum ambigua luce, defensores intentius contemplati, eo accedente quod angularem turrim ictus foravit arietis violentior, relictis civitatis duplicibus muris, continentem occupant arcem, asperi montis interrupta planitie superpositam, cuius medietas in sublime consurgens, tereti ambitu Argolici scuti speciem ostendebat, nisi quod e septemtrione, id quod rotunditati defuerat, in Euphratis fluenta proiectae cautes eminentius tuebantur, in qua excellebant minae murorum, bitumine et coctilibus laterculis fabricatae, quo aedificii genere nihil esse tutius constat.", "st": "24.2"}, {"sp": "N", "t": "Iamque ferocior miles, pervasa urbe quam viderat vacuam, adversus oppidanos ab arce multimoda tela fundentes, acri contentione pugnabat. Cum enim idem prohibitores catapultis nostrorum urgerentur atque ballistis, ipsi quoque ex edito arcus erigebant fortiter tensos, quibus panda utrimque surgentia cornua ita lentius flectebantur, ut nervi digitorum acti pulsibus violentis, harundines ferratas emitterent, quae corporibus illisae contrariis, letaliter figebantur.", "st": "24.2"}, {"sp": "N", "t": "Dimicabatur nihilo minus utrubique saxorum manualium nimbis, et neutrubi inclinato momento, proelium atrox a lucis ortu ad initium noctis destinatione magna protractum, pari sorte diremptum est. Proinde die secuto, cum certaretur asperrime, multique funderentur altrinsecus, et aequi vigores gesta librarent, imperator omnes aleae casus inter mutuas clades experiri festinans, cuneatim stipatus, densetisque clipeis ab ictu sagittarum defensus, veloci saltu comitantibus promptis, prope portam venit hostilem, crasso ferro crustatam.", "st": "24.2"}, {"sp": "N", "t": "Et licet saxis et glande, ceterisque telis, cum periculi sociis premeretur, fodicare tamen paratos valvarum latera ut aditum patefacerent, vocibus increpans crebris, non ante discessit, quam telorum congerie, quae superiaciebantur, se iam cerneret obruendum.", "st": "24.2"}, {"sp": "N", "t": "Evasit cum omnibus tamen, paucis levius vulneratis, ipse innoxius, verecundo rubore suffusus. Legerat enim Aemilianum Scipionem, cum historiarum conditore Polybio, Megalopolitano Arcade, et triginta militibus, portam Carthaginis impetu simili subfodisse. Sed fides recepta scriptorum veterum recens factum defendit.", "st": "24.2"}, {"sp": "N", "t": "Aemilianus enim testudine lapidea tectam successerat portam, sub qua tutus et latens, dum moles saxeas detegunt hostes, urbem nudatam irrupit, Iulianus vero locum patentem aggressus, obumbrata caeli facie fragmentis montium et missilibus aegre repulsus, abscessit.", "st": "24.2"}, {"sp": "N", "t": "His raptim ac tumultuarie agitatis, cum operositas vinearum et aggerum impeditissima ceteris urgentibus cerneretur, machinam quae cognominatur helepolis, iussit expeditius fabricari, qua (ut supra docuimus) rex usus Demetrius, superatis oppidis pluribus, Poliorcetes appellatus est.", "st": "24.2"}, {"sp": "N", "t": "Ad hanc molem ingentem, superaturam celsarum turrium minas, prohibitores oculorum aciem intentius conferentes, itidemque instantiam obsidentium perpensantes, subito vertuntur ad preces, circumfusique per turres ac moenium minas, et fidem Romanam pansis manibus protestantes, vitam cum venia postulabant.", "st": "24.2"}, {"sp": "N", "t": "Cumque cessasse opera et munitores nihil temptare viderent ulterius, quod quietis erat indicium certum, copiam sibi dari conferendi sermonis cum Ormizda poscebant.", "st": "24.2"}, {"sp": "N", "t": "Hocque impetrato, Mamersidis praesidiorum praefectus, demissus per funem, ductusque ad imperatorem (ut obsecravit), vita cum impunitate sibi consortibusque suis firmiter pacta, redire permissus est. Gestisque nuntiatis, plebs omnis utriusque sexus ad sententiam suam cunctis acceptis, pace foederata cum religionum consecrationibus fidis, patefactis egreditur portis, salutarem genium affulsisse sibi clamitans Caesarem, magnum et lenem.", "st": "24.2"}, {"sp": "N", "t": "Numerata sunt autem dediticiorum duo milia et quingenti; nam cetera multitudo obsidium ante suspectans, navigiis parvis permeato amne discessit. In hac arce armorum alimentorumque copia reperta est maxima, unde necessariis sumptis, reliqua cum loco ipso exussere victores.", "st": "24.2"}, {"sp": "N", "t": "Postera die quam haec acta erant, perfertur ad imperatorem, cibos per otium capientem, nuntius gravis, Surenam Persicum ducem, procursatorum partis nostrae tres turmas inopinum aggressum paucissimos trucidasse, inter quos strato tribuno, unum rapuisse vexillum.", "st": "24.3"}, {"sp": "N", "t": "Statimque concitus ira immani, cum armigera manu, festinatione ipsa tutissimus pervolavit, et grassatoribus foeda consternatione depulsis, residuos duos tribunos sacramento solvit (ut desides et ignavos): decem vero milites ex his qui fugerant, exauctoratos, capitali addixit supplicio, secutus veteres leges.", "st": "24.3"}, {"sp": "N", "t": "Incensa denique urbe (ut memoratum est), constructo tribunali insistens, actis gratiis exercitui convocato, cunctos ad paria facienda deinceps hortabatur, et argenteos nummos centenos viritim pollicitus, cum eos parvitate promissi percitos tumultuare sensisset, ad indignationem plenam gravitatis erectus:", "st": "24.3"}, {"sp": "N", "t": "“En” inquit “Persae, circumfluentes rerum omnium copiis: ditare vos poterit opimitas gentis, si unum spirantibus animis fortiter fecerimus. Ex immensis opibus egentissima est—tandem credite Romana res publica, per eos qui (ut augerent divitias) docuerunt principes auro quietem a barbaris redemptare.", "st": "24.3"}, {"sp": "N", "t": "“Direptum aerarium est, urbes exinanitae, populatae provinciae: mihi nec facultates nec propinquitas generis suppetit, quamvis ortus sim nobilis, praeter pectus omni liberum metu: nec pudebit imperatorem, cuncta bona in animi cultu ponentem, profiteri paupertatem honestam. Nam et Fabricii familiari re pauperes, rexere bella gravissima, gloria locupletes.", "st": "24.3"}, {"sp": "N", "t": "“Haec vobis cuncta poterunt abundare, si imperterriti deo meque (quantum humana ratio patitur), caute ductante, mitius egeritis: sin resistitis ad seditionum revoluti dedecora pristinarum, iam pergite.", "st": "24.3"}, {"sp": "N", "t": "“Ut imperatorem decet, ego solus confecto tantorum munerum cursu, moriar stando, contempturus animam quam mihi febricula eripiet una, aut certe discedam; nec enim ita vixi, ut non possim aliquando esse privatus. Praeque me fero et laetor, ductores spectatissimos esse nobiscum, perfectos bellicarum omni genere doctrinarum.”", "st": "24.3"}, {"sp": "N", "t": "Hac modesta imperatoris oratione, inter secunda et aspera medii, miles pro tempore delenitus, assumpta cum meliorum exspectatione fiducia, regibilem se fore pollicitus et morigerum, cunctorum adspirante consensu, auctoritatem eius sublimitatemque cordis extollebat in caelum, quod cum vere atque ex animo dicitur, solet armorum crepitu leni monstrari.", "st": "24.3"}, {"sp": "N", "t": "Repetitis post haec tentoriis, pro copia rei praesentis victu se recreavit et quiete nocturna. Animabat autem Iulianus exercitum, cum non per caritates, sed per inchoatas negotiorum magnitudines deieraret assidue: “Sic sub iugum mitteret Persas, ita quassatum recrearet orbem Romanum.” Ut Traianus fertur aliquotiens iurando dicta consuesse firmare “Sic in provinciarum speciem redactam videam Daciam; sic pontibus Histrum et Euphratem, superem,” et similia plurima.", "st": "24.3"}, {"sp": "N", "t": "Post haec decursis milibus passuum quattuordecim, ad locum quendam est ventum arva aquis abundantibus fecundantem, quo itinere nos ituros Persae praedocti, sublatis cataractis undas evagari fusius permiserunt.", "st": "24.3"}, {"sp": "N", "t": "Itaque humo late stagnante, altero die militi requie data, imperator ipse praegressus, constratis periculis multis ex utribus pro copia pontibus, itidemque navibus confectis e palmarum trabibus exercitum non sine difficultate traduxit.", "st": "24.3"}, {"sp": "N", "t": "In his regionibus agri sunt plures, consiti vineis varioque pomorum genere, ubi oriri arbores assuetae palmarum, per spatia ampla ad usque Mesenen et mare pertinent magnum, instar ingentium nemorum. Et quaqua incesserit quisquam, termites et spadica cernit assidua, quorum ex fructu mellis et vini conficitur abundantia, et maritari palmae ipsae dicuntur facileque sexus posse discerni.", "st": "24.3"}, {"sp": "N", "t": "Additur etiam generare feminas seminibus illitas marium, feruntque eas amore mutuo delectari, hocque inde clarere, quod contra se vicissim nutantes, ne turgidis quidem flatibus avertuntur. Et si ex more femina maris non illita fuerit semine, abortus vitio fetus amittit intempestivos. Et siqua femina cuius arboris amore perculsa sit ignoretur, unguento ipsius inficitur truncus, et arbor alia naturaliter odoris dulcedinem concipit, hisque indiciis velut coeundi quaedam proditur fides.", "st": "24.3"}, {"sp": "N", "t": "Qua cibi copia satur exercitus, plures praetergressus est insulas, et ubi formidabatur inopia, ibi timor saginae gravis incessit. Sagittariorum denique hostilium impetu latenti temptatus, neque inultus, prope locum venit ubi pars maior Euphratis in rivos dividitur multifidos.", "st": "24.3"}, {"sp": "N", "t": "In hoc tractu civitas ob muros humiles ab incolis Iudaeis deserta, iratorum manu militum conflagravit. Quibus actis pergebat ulterius imperator, placida ope numinis (ut arbitrabatur), erectior.", "st": "24.4"}, {"sp": "N", "t": "Cumque Maiozamalcham venisset, urbem magnam et validis circumdatam moenibus, tentoriis fixis providit sollicite, ne castra repentino equitatus Persici turbarentur accursu, cuius fortitudo in locis patentibus, immane quantum gentibus est formidata.", "st": "24.4"}, {"sp": "N", "t": "Et hoc disposito stipatus velitibus paucis, ipse quoque pedes civitatis situm diligenti inquisitione exploraturus, in perniciosas praecipitatus insidias, ex ipso vitae discrimine tandem emersit.", "st": "24.4"}, {"sp": "N", "t": "Namque per latentem oppidi portam, Persae decem armati degressi, imaque clivorum pervadentes, poplitibus subsidendo, repentino impetu nostros aggressi sunt. E quibus duo conspectiorem habitu principem gladiis petiere districtis, sed occurrit ictibus erectum altius scutum, quo contectus magna elataque fiducia unius lateri ferrum infixit, alterum stipatores multiplicatis ictibus occiderunt. Residuis e quibus vulnerati sunt aliqui, disiectis in fugam, spoliatisque ambobus, reducens incolumes socios, cum exuviis remeavit ad castra, omnium laetitia magna susceptus.", "st": "24.4"}, {"sp": "N", "t": "Sustulit in hoste prostrato aureum colli monile Torquatus, fudit confidentissimum Gallum alitis propugnatione Valerius, postea cognomento Corvinus, hacque gloria posteritati sunt commendati; non invidemus: accedat hoc quoque monumentis veteribus facinus pulchrum.", "st": "24.4"}, {"sp": "N", "t": "Constratis postridie pontibus, exercituque travecto, et metatis alibi salubrius castris, vallo duplici circumductis, quoniam (ut diximus) timebantur solitudines planae, oppidi suscepit obsidium, periculosum fore existimans, si gradiens prorsus, a tergo relinqueret quos timeret.", "st": "24.4"}, {"sp": "N", "t": "Haec dum magno molimine comparantur, Surena hostium dux iumenta adortus, quae in lucis palmaribus vescebantur, a cohortibus nostris repulsoriis cum paucorum exitio habitus frustra discessit.", "st": "24.4"}, {"sp": "N", "t": "Et duarum incolae civitatum, quas amnes amplexi faciunt insulas, parva sui fiducia trepidi, ad Ctesiphontis moenia se contulerunt, pars per silvarum densa, alii per paludes vicinas, alveis arborum cavatarum invecti, ad unicum auxilium et potissimum itineris longi, quod supererat, dilabuntur, ulteriora petituri terrarum.", "st": "24.4"}, {"sp": "N", "t": "E quibus resistentes aliquos nostri milites trucidabant, ipsi quoque lintribus et cymbis per varia discurrentes, captivos alios subinde perducebant. Id enim erat librata ratione dispositum, ut, dum copiae pedestres muros oppugnant, equestres turmae divisae per globos, abigendis insisterent praedis: hocque proviso, nullo provincialium damno, miles visceribus hostium pascebatur.", "st": "24.4"}, {"sp": "N", "t": "Iamque imperator munitum muris duplicibus oppidum, ordine circumdatum trino scutorum, spe patrandi incepti, maximis viribus oppugnabat. Sed ut erat necessarius appetitus, ita effectu res difficillima. Nam accessus undique rupibus anfractu celsiore discissis, flexuosisque excessibus ob periculum anceps, adeundi copiam denegabat, maxime quoniam turres crebritate et altitudine formidandae, montem saxeum arcis naturaliter editum, aequabant, et proclivis planities flumini imminens, propugnaculorum firmitate muniebatur.", "st": "24.4"}, {"sp": "N", "t": "Accedebat his haut levius malum, quod lecta manus et copiosa (quae obsidebatur) nullis ad deditionem illecebris flectebatur, sed tamquam superatura, vel devota cineribus patriae, resistebat. Adversus eam aegre retentabatur, inferens se protervius miles, et pugnam vel aequo campo, iustoque proelio poscens, cumque receptui caneretur, assidue animosis hostem urgendi conatibus urebatur.", "st": "24.4"}, {"sp": "N", "t": "Vicit tamen nostrorum consilium contentionem virium maximam, divisisque operibus, officia quisque distributa capessit ocissime. Hinc enim ardui suggestus erigebantur, inde fossarum altitudines alii complanabant, terrarum latibula concava oblongis tramitibus alibi struebantur, locabant etiam artifices tormenta muralia, in funestos sonitus proruptura,", "st": "24.4"}, {"sp": "N", "t": "Et cuniculos quidem cum vineis, Nevitta et Dagalaifus curabant, ineundis autem conflictibus, et defendendis ab incendio vel eruptionibus machinis, praeerat imperator.", "st": "24.4"}, {"sp": "N", "t": "Cumque apparatu omni excindendae urbis labore multiplici consummato, pugna flagitaretur, Victor nomine dux reversus est ad usque Ctesiphonta, itineribus exploratis, nulla obstacula nuntians offendisse.", "st": "24.4"}, {"sp": "N", "t": "Quo efferati gaudio milites omnes, elatique firmioribus animis, ad certandum signum operiebantur armati.", "st": "24.4"}, {"sp": "N", "t": "Iamque clangore Martio sonantibus tubis, strepebant utrimque partes, et primi Romani hostem undique lamminis ferreis in modum tenuis plumae contectum, fidentemque, quod tela rigentis ferri lapsibus impacta resiliebant, crebris procursationibus et minaci murmure lacessebant: non numquam compage scutorum, qua velut testudine infigurabilium fornicum operiebantur aptissime, assiduis motibus laxius dehiscente. Contra Persae muris obstinatius adhaerentes, quantum facere nitique poterant, eludere et frustrari exitiales impetus conabantur.", "st": "24.4"}, {"sp": "N", "t": "Verum ubi vimineas crates prae se ferentes, oppugnatores iam moenia perurgerent, cum sagittariis funditores, alii quin etiam saxa volventes ingentia, cum facibus et malleolis eos longius propulsabant, tum aptatae ligneis sagittis ballistae, flexus stridore torquebantur, creberrima spicula funditantes, et scorpiones quocumque manus peritae duxissent, rotundos lapides evibrabant.", "st": "24.4"}, {"sp": "N", "t": "Iterum deinde ac saepe geminatis congressibus, aestus in meridiem crescens, effervescente vaporatius sole, apparatu operum et studio proeliandi intentos, cunctos revocaverat fatigatos et sudore perfusos.", "st": "24.4"}, {"sp": "N", "t": "Eodem mentis proposito, secuto quoque die, per varia certaminum genera controversae partes dimicantes instanter, aequis manibus et pari fortuna discedunt. Verum in omne discrimen armatis proximus princeps civitatis urgebat excidium, ne circa muros diu excubans, omitteret maiora quae temptabat.", "st": "24.4"}, {"sp": "N", "t": "Sed in districtis necessitatibus, nihil tam leve est quod non interdum etiam contra sperata, rerum adferat momenta magnarum. Cum enim (ut saepe) discessurae partes levius concertarent, abusive incusso ariete, qui paulo ante erat admotus, sternitur residuis omnibus altior turris, latere coctili firmissime structa, cuius ruina muri contiguum latus secum immani fragore protraxit.", "st": "24.4"}, {"sp": "N", "t": "Ibi tum varietate casuum obsidentium labor, obsessorumque industria vicissim facinoribus speciosis inclaruit. Nihil enim asperum ira et dolore succenso militi videbatur, nihil prohibitoribus erat pro salute concurrentibus, metuendum aut dirum. Nam cum anceps proelium diutius fervens, sanguine utrimque multis caedibus fuso, diei finisset occasus, tum fatigationi consulitur.", "st": "24.4"}, {"sp": "N", "t": "Dumque haec luce agerentur ac palam, nuntiatur imperatori, pervigili cura distento, legionarios milites, quibus cuniculorum erant fodinae mandatae, cavatis tramitibus subterraneis, sublicibusque suspensis, ima penetrasse fundamentorum, iam (si ipse disposuerit) evasuros.", "st": "24.4"}, {"sp": "N", "t": "Cum itaque noctis plerumque processisset, aeneatorum accentu, signo dato progrediendi ad pugnam, ad arma concursum est: et consulto murorum invaduntur utrimque frontes, ut dum propulsaturi pericula, defensores ultro citroque discurrunt, nec proxima fodientis audiretur ferri tinnitus, nec quoquam intrinsecus obsistente, cuniculariorum subito manus emergat.", "st": "24.4"}, {"sp": "N", "t": "Quibus ita (ut convenerat) ordinatis, et occupatis prohibitoribus, patefactisque latebris, evolat Exsuperius, de Victorum numero miles, post quem Magnus tribunus, et Iovianus notarius, quos audax multitudo secuta, his prius confossis, quos in aede per quam in lucem prodierant, invenerunt, suspensis gradibus procedentes obtruncarunt vigiles omnes, ex usu moris gentici iustitiam felicitatemque regis sui canoris vocibus extollentes.", "st": "24.4"}, {"sp": "N", "t": "Existimabatur Mars ipse (si misceri hominibus numina maiestatis iura permittunt), adfuisse castra Lucanorum invadenti Luscino. Hocque ideo creditum est quod in congressu flagranti, scalas vehens visus formidandae vastitatis armatus, postridie cum recenseretur exercitus, praecipuo studio quaesitus, reperiri non potuit, cum se ultro offerret, si miles fuisset, memorabilis conscius facti. Sed ut tunc qui esset pulchri facinoris auctor penitus est ignoratum, ita nunc enituerunt hi qui fecere fortissime, obsidionalibus coronis donati, et pro contione laudati, veterum more.", "st": "24.4"}, {"sp": "N", "t": "Tandem nudata, reseratis aditibus multis, lapsura invaditur civitas, et sine sexus discrimine vel aetatis, quicquid impetus repperit, potestas iratorum absumpsit, alii exitii imminentis timore, cum hinc ignis inde mucrones urgerent, ultimum flentes, e muris acti sua sponte praecipites, membrisque omnibus infirmati, vitam morte funestiorem paulisper, dum caederentur egerunt.", "st": "24.4"}, {"sp": "N", "t": "Extractus est autem vivus cum satellitibus octoginta Nabdates, praesidiorum magister, quem oblatum sibi cum aliis servari iussit intactum, serenus imperator et clemens.", "st": "24.4"}, {"sp": "N", "t": "Divisa itaque perpensis meritis et laboribus praeda, ipse (ut erat parvo contentus), mutum puerum oblatum sibi suscepit gesticularium, multa quae callebat, nutibus venustissimis explicantem, e tribus aureis nummis, partae victoriae praemium iucundum (ut existimabat) et gratum.", "st": "24.4"}, {"sp": "N", "t": "Ex virginibus autem, quae speciosae sunt captae ut in Perside, ubi feminarum pulcritudo excellit, nec contrectare aliquam voluit nec videre, Alexandrum imitatus et Africanum, qui haec declinabant, ne frangerentur cupiditate, qui se invictos a laboribus ubique praestiterunt.", "st": "24.4"}, {"sp": "N", "t": "Inter haec certamina nostrae partis architectus, cuius nomen non suppetit, post machinam scorpionis forte assistens, reverberate lapide quem artifex titubanter aptaverat fundae, obliso pectore supinatus, profudit animam disiecta compage membrorum, adeo ut ne signa quidem totius corporis noscerentur.", "st": "24.4"}, {"sp": "N", "t": "Exin profecturo imperatori, index nuntiaverat certus, circa muros subversi oppidi fallaces foveas et obscuras, quales in tractibus illis sunt plurimae, subsedisse manum insidiatricem latenter, ut inproviso inde exorta, agminis nostri terga feriret extrema.", "st": "24.4"}, {"sp": "N", "t": "Confestimque ad extrahendam eam missi sunt compertae fortitudinis pedites. Qui cum neque pervadere foraminum aditus, nec amendatos intus prolicere possent ad decernendum, collectam stipulam et sarmenta specuum faucibus aggesserunt. Unde fumus angustius penetrans, ideoque spissior, quosdam vitalibus obstructis necavit, alios ignium afflatu semustos, prodire in perniciem coegit abruptam, et ita omnibus ferro incendioque consumptis, ad signa repedavit ocius miles. Hoc modo civitas ampla et populosa virtute roboris excisa Romani, in pulverem concidit et ruinas.", "st": "24.4"}, {"sp": "N", "t": "Post quae tam gloriosa, transitis pontibus multorum amnium concursu continuatis, ad munimenta gemina venimus, aedificiis cautis exstructa, ubi Victorem comitem exercitus praevium, a transitu fluminis regis filius progressus a Ctesiphonte, cum optimatibus et multitudine armata, prohibere conatus, catervis sequentium militum visis, abscessit.", "st": "24.4"}, {"sp": "N", "t": "Pergentes itaque protinus, ad lucos venimus, agrosque pube variorum seminum laetos, ubi reperta regia Romano more aedificata, quoniam id placuerat, mansit intacta.", "st": "24.5"}, {"sp": "N", "t": "Erat etiam in hac eadem regione extentum spatium et rotundum, loricae ambitu circumclausum, destinatas regiis voluptatibus continens feras, cervicibus iubatis leones, armisque hispidos apros, et ursos (ut sunt Persici) ultra omnem rabiem saevientes, et alia lecta immania corpora bestiarum: quas omnes diffractis portarum obicibus, equites nostri venatoriis lanceis et missilium multitudine confoderunt.", "st": "24.5"}, {"sp": "N", "t": "Quae loca pinguia satis et cultu, quibus Coche (quam Seleuciam nominant) haut longius disparatur, ubi vallatis opere tumultuario castris, et exercitu omni per aquarum et pabuli opportuna biduo recreato, antegressus cum procursatoribus princeps, et civitatem desertam collustrans, a Caro principe quondam excisam, in qua perpetuus fons stagnum ingens eiectat, in Tigridem defluens, corpora vidit suffixa patibulis multa necessitudinum eius, quem prodidisse civitatem Pirisaboram rettulimus supra.", "st": "24.5"}, {"sp": "N", "t": "Hic et Nabdates vivus exustus est, quem extractum cum octoginta e latebris expugnatae docui civitatis, eo quod inter exordia obsidii coepti, clam pollicitus prodere, dimicavit acerrime, adeptusque veniam insperatam, ad id proruperat insolentiae, ut Ormizdam laceraret omnibus probris.", "st": "24.5"}, {"sp": "N", "t": "Itaque aliquantum progressi, tristi percellimur facto. Dum enim tres procursatorum cohortes expeditae cum cuneo Persico decertarent, quem patefactis subito portis, profuderat civitas, proruptores alii ex contraria fluminis ripa, iumenta nos sequentia cum pabulatoribus paucis, licenter palantibus, intercipiunt et obtruncant.", "st": "24.5"}, {"sp": "N", "t": "Unde profectus imperator iratus et frendens, iamque regionibus Ctesiphontis propinquans, celsum castellum offendit et munitissimum, ad quod explorandum ausus accedere, obscurior (ut ipse rebatur) cum paucis obequitans muros, pauloque avidius intra ictum telorum repertus, latere non potuit: statimque diversorum missilium nube exagitatus oppetisset tormento murali, ni vulnerato armigero, qui lateri eius haerebat, ipse scutorum densitate contectus, evitato magno discrimine, discessisset.", "st": "24.5"}, {"sp": "N", "t": "Qua causa concitus ira immani, munimentum disposuit obsidere, prohibitoribus acriter ad resistendum intentis, quod loco fidebant, propemodum inaccesso, quodque rex cum ambitiosis copiis passibus citis incedens, propediem affore credebatur.", "st": "24.5"}, {"sp": "N", "t": "Iamque vineis et residuis omnibus, quae poscebat obsidium, paratis, vigilia secunda praecipiti, cum nox casu tunc lunari nitens splendore, his qui propugnaculis insistebant, aperte cuncta monstraret, repente in unum pondus coacta, multitudo patefactis subito portis erupit, cohortemque nec opinantem adorta nostrorum, cecidit complures, inter quos etiam tribunus peremptus est, periculum propulsare conatus.", "st": "24.5"}, {"sp": "N", "t": "Quae dum ita aguntur, pari modo ut antea, Persae ex adversa fluminis ripa, partem adorti nostrorum, interfectis quibusdam vivos cepere non nullos. Et timore simul quia venisse in maiorem numerum copiae putabantur hostiles, egere nostri tune segnius, sed ubi animis in audaciam restitutis, armisque raptis inter tumultum, exercitus cantu concitus bucinarum, cum minaci murmure festinaret, eruptores perterriti reverterunt intacti.", "st": "24.5"}, {"sp": "N", "t": "Et imperator ira gravi permotus, reliquos ex ea cohorte, qui abiecte sustinuerant impetum grassatorum, ad pedestrem compegit militiam (quae onerosior est) dignitatibus imminutis.", "st": "24.5"}, {"sp": "N", "t": "Flagrans post haec ad eruendum castellum, ubi periclitatus est, operam convertit et curam, nusquam ab antesignanis ipse digrediens, ut inter primos dimicans militi ad fortiter faciendum esset exemplo, spectator probatorque gestorum. Quo inter discriminum vertices diu multumque versato, varietate munitionum atque telorum, et conspiratione oppugnatorum, idem castellum incenditur captum.", "st": "24.5"}, {"sp": "N", "t": "Post quae consideratis asperitatibus ante gestarum rerum et impendentium, requievit exercitus, labore nimio quassatus, multis victui congruis adfatim distributis. Vallum tamen sudibus densis et fossarum altitudine cautius deinde struebatur, cum a vicina iam Ctesiphonte, repentini excursus et alia formidarentur occulta.", "st": "24.5"}, {"sp": "N", "t": "Ventum est hinc ad fossile flumen, Naarmalcha nomine (quod amnis regum interpretatur), tunc aridum. Id antehac Traianus, posteaque Severus, egesto solo fodiri in modum canalis amplissimi, studio curaverat summo, ut aquis illuc ab Euphrate transfusis, naves ad Tigridem commigrarent.", "st": "24.6"}, {"sp": "N", "t": "Tutissimumque ad omnia visum est, eadem loca purgari, quae quondam similia Persae timentes, mole saxorum obruere multorum. Hacque valle purgata, avulsis cataractis undarum magnitudine classis secura, stadiis triginta decursis, in alveum eiecta est Tigridis, et contextis ilico pontibus transgressus exercitus iter Cochen versus promovit.", "st": "24.6"}, {"sp": "N", "t": "Utque lassitudini succederet quies opportuna, in agro consedimus opulento, arbustis et vitibus et cupressorum viriditate laetissimo, cuius in medio diversorium opacum est et amoenum, gentiles picturas per omnes aedium partes ostendens, regis bestias venatione multiplici trucidantis; nec enim apud eos pingitur vel fingitur aliud, praeter varias caedes et bella.", "st": "24.6"}, {"sp": "N", "t": "Proinde cunctis ex sententia terminatis, Augustus altius iam contra difficultates omnes incedens, tantumque a fortuna sperans nondum afflicta, ut propius temeritatem multa crebro auderet, validiores naves ex his quae alimenta portabant et machinas, deoneratas octogenis implevit armatis, retentoque secum classis robore firmiore, quam in tres diviserat partes, unam cum Victore comite quiete prima noctis emitti disposuit, ut flumine raptim transmisso, ripae occuparentur hostiles.", "st": "24.6"}, {"sp": "N", "t": "Quod cum acri metu territi duces, concordi precatu fieri prohibere temptarent, neque destinationem flecterent principis, sublato vexillo, ut iussum est, evolant e conspectu quinque subito naves, et cum ripas iam adventarent, facibus et omni materia, qua alitur ignis, petitae assiduis iactibus, cum militibus iam conflagrassent, ni veloci vigore pectoris excitus imperator, signum sibi datum nostros quod margines iam tenerent (ut mandatum est), erexisse proclamans, classem omnem properare citis remigiis adegisset.", "st": "24.6"}, {"sp": "N", "t": "Quo facto et naves incolumes sunt receptae, et residuus miles, quamquam saxis et varietate telorum ex edito vexaretur, post concertationem acerrimam, praealtas ripas et arduas supergressus, stabat immobilis.", "st": "24.6"}, {"sp": "N", "t": "Et miratur historia, Rhodanum arma et loricam retinente Sertorio, transnatatum, cum eo momento turbati quidam milites, veritique ne remanerent, post signum erectum, scutis, quae patula sunt et incurva, proni firmius adhaerentes, eaque licet imperite regendo, per voraginosum amnem velocitatem comitati sunt navium.", "st": "24.6"}, {"sp": "N", "t": "Contra haec Persae obiecerunt instructas cataphractorum equitum turmas, ita confertas, ut lamminis cohaerenter aptati corporum flexus, splendore praestringerent occursantes obtutus, operimentis scorteis equorum multitudine omni defensa, quorum in subsidiis manipuli locati sunt peditum, contecti scutis oblongis et curvis, quae texta vimine et coriis crudis gestantes densius se commovebant. Post hos elephanti gradientium collium specie, motuque immanium corporum, propinquantibus exitium intentabant, documentis praeteritis formidati.", "st": "24.6"}, {"sp": "N", "t": "Hinc imperator catervis peditum infirmis medium inter acies spatium secundum Homericam dispositionem praestituit, ne locati priores, cedentesque deformiter, cunctos averterent secum, aut postsignani pone omnes reiecti centurias, nullo retinente licentius verterent terga, ipse cum levis armaturae auxiliis, per prima postremaque discurrens.", "st": "24.6"}, {"sp": "N", "t": "Ergo ubi vicissim contiguae se cernerent partes, cristatis galeis corusci Romani, vibrantesque clipeos, velut pedis anapaesti praecinentibus modulis, lenius procedebant, et praepilatis missilibus per procursatores principiis pugnae temptatis, excita undique humus rapido turbine portabatur.", "st": "24.6"}, {"sp": "N", "t": "Et cum undique solito more conclamaretur, virorumque alacritatem sonans classicum iuvaret, hastis et mucronibus strictis, hinc inde comminus pugnabatur: sagittarum periculo miles erat immunis, quantum interiora festinatius occupabat. Inter quae Iulianus pulsos fulcire subsidiis, incitareque tardantes, quasi conturmalis strenuus properabat et rector.", "st": "24.6"}, {"sp": "N", "t": "Laxata itaque acies prima Persarum, leni ante, dein concito gradu, calefactis armis retrorsus gradiens propinquam urbem petebat, quam sequebatur miles itidem fessus in campis torridis ad usque diei finem a lucis ortu decernens, eiusque occipitiis pertinacius haerens, omnem cum Pigrane et Surena et Narseo, potissimis ducibus, ad usque Ctesiphontis muros egit praecipitem, adversorum feriens suras et terga.", "st": "24.6"}, {"sp": "N", "t": "Perrupissetque civitatis aditus lapsorum agminibus mixtus, ni dux Victor nomine manibus erectis prohibuisset et vocibus, et ipse umerum sagitta praestrictus, et timens ne intra moenium ambitus rapidus miles inconsulte repertus nullosque inveniens exitus, multitudinis pondere circumveniretur.", "st": "24.6"}, {"sp": "N", "t": "Sonent Hectoreas poetae veteres pugnas, fortitudinem Thessali ducis extollant, longae loquantur aetates Sophanem et Aminiam et Callimachum et Cynaegirum, Medicorum egregia culmina illa bellorum: non minus illo die quorundam ex nostris inclaruisse virtutem, omnium confessione monstratur.", "st": "24.6"}, {"sp": "N", "t": "Post timorem depositum, calcatasque ruinas hostilium corporum, iusto sanguine miles etiam tum cruentus, ad imperatoris tentoria congregatus, laudes ei perhibebat et gratias, quod ignoratus ubique dux esset an miles, magis aliorum quam suum respiciens commodum, ita rem prospere gesserat ut caesis Persarum plus minusve duobus milibus et quingentis, septuaginta caderent soli nostrorum.", "st": "24.6"}, {"sp": "N", "t": "Qui appellans plerosque nominatim, quos stabili mente aliquid clarum fecisse, ipse arbiter perspexit, navalibus donavit coronis et civicis et castrensibus.", "st": "24.6"}, {"sp": "N", "t": "Abunde ratus post haec prosperitates similis adventare, complures hostias Marti parabat ultori, et ex tauris pulcherrimis decem ad hoc perductis, nondum aris admoti, voluntate sua novem procubuere tristissimi, decimus vero, qui diffractis vinculis lapsus aegre reductus est, mactatus ominosa signa monstravit. Quibus visis, exclamavit indignatus acriter Iulianus Iovemque testatus est, nulla Marti iam sacra facturum: nec resecravit, celeri morte praereptus.", "st": "24.6"}, {"sp": "N", "t": "Digesto itaque consilio cum primatibus super Ctesiphontis obsidio, itum est in voluntatem quorundam, facinus audax et importunum esse noscentium id aggredi, quod et civitas situ ipso inexpugnabilis defendebatur, et cum metuenda multitudine protinus rex adfore credebatur.", "st": "24.7"}, {"sp": "N", "t": "Vicit sententia melior, cuius utilitate princeps sollertissimus approbata, Arintheum cum manu peditum expedita, ad populandas regiones circumsitas misit, armentis laetas et frugibus, hostes pari persecuturum industria, quos dispalatos nuper densi tramites et latebrae texere notissimae.", "st": "24.7"}, {"sp": "N", "t": "Sed ille avidae semper ad ulteriora cupiditatis, parvi habitis vetantium dictis, et increpitis optimatibus, quod ob inertiam otiique desiderium, amitti suaderent prope iam parta regna Persidis, flumine laeva relicto, infaustis ductoribus praeviis, mediterraneas vias arripere citato proposuit gradu.", "st": "24.7"}, {"sp": "N", "t": "Et tamquam funesta face Bellonae subiectis ignibus exuri cunctas iusserat naves, praeter minores duodecim, quas profuturas pangendis pontibus disposuit vehi carpentis, idque putabat utiliter ordinasse, ne relicta classis usui hostibus foret, aut certe (ut ab expeditionis primordio factum est), armatorum fere viginti milia in trahendis occuparentur eisdem navibus et regendis.", "st": "24.7"}, {"sp": "N", "t": "Dein cum metuens sibi quisque mussaret, monstraretque perspicua veritas, quod repulsus forsitan ariditate vel altitudine montium, ad aquas redire non poterit miles, tortique perfugae aperte faterentur se fefellisse, concursu maximo exstingui iussae sunt flammae. Et quoniam ignis auctus immaniter plerasque consumpsit, duodecim tantum modo naves potuerunt intactae servari, quae ut possint custodiri discretae sunt.", "st": "24.7"}, {"sp": "N", "t": "Hoc casu classe cum non oporteret abolita, Iulianus consociato fretus exercitu, cum armatorum nulli per diversa distringerentur, numero potior ad interiora tendebat, alimenta adfatim opulentis suggerentibus locis.", "st": "24.7"}, {"sp": "N", "t": "Quo cognito hostes, ut inedia nos cruciarent, herbas cum adultis segetibus incenderunt, et conflagratione procedere vetiti, stativis castris dum flammae senescerent tenebamur. Insultantesque nobis longius Persae, nunc de industria se diffundebant, aliquotiens confertius resistentes, ut procul conspicantibus viderentur advenisse iam regis auxilia, ideoque eos aestimaremus erupisse ad audaces excursus, et insolita temptamenta.", "st": "24.7"}, {"sp": "N", "t": "Maerebat tamen ob haec imperator et miles, quod nec contabulandi pontis erat facultas, amissis navibus temere, nec occurri poterat hostis adventicii motibus, quem adesse coruscus nitor indicabat armorum, arte pro singulis membris inflexus. Hisque accedebat aliud haud exiguum malum, quod nec adminicula quae praestolabamur cum Arsace et nostris ducibus apparebant, ob causas impedita praedictas.", "st": "24.7"}, {"sp": "N", "t": "Has ob res ut solaretur anxios milites princeps, captives graciles suapte natura, ut omnes paene sunt Persae, et macie iam confectos, iussit in medium duci, nostrosque respiciens, “En” inquit “quos Martia ista pectora viros existimant, deformes illuvie capellas et taetras, utque crebri docuerunt eventus, antequam manus conferant abiectis armis vertentes semet in fugam.”", "st": "24.8"}, {"sp": "N", "t": "Quibus dictis remotisque captivis, super rerum summa consultabatur. Et multis ultro citroque dictitatis, cum reverti debere per loca qua venimus, plebs vociferaretur imprudens, resistebat intentius princeps, multis cum eo id nequaquam fieri posse monstrantibus, per effusam planitiem pabulo absumpto et frugibus, vicorumque reliquiis exustorum inopia squalentibus ultima: quodque liquentibus iam brumae pruinis, omne immaduerat solum, et ruptis riparum terminis aucti, inhorruere torrentes.", "st": "24.8"}, {"sp": "N", "t": "Eo etiam ad difficultatem accedente negotii, quod per eas terras vapore sideris calescentes, muscarum et culicum multitudine referta sunt omnia, earumque volatu dies et astrorum noctu micantium facies obumbratur.", "st": "24.8"}, {"sp": "N", "t": "Et cum nihil humani proficerent sensus, diu fluctuantes et dubii, exstructis aris caesisque hostiis, consulta numinum scitabamur, utrum nos per Assyriam reverti censerent, an praeter radices montium lenius gradientes, Chiliocomum prope Corduenam sitam ex improviso vastare: quorum neutrum extis inspectis, confore dicebatur.", "st": "24.8"}, {"sp": "N", "t": "Sedit tamen sententia, ut omni spe meliorum succisa, Corduenam arriperemus, et sextum decimum Kalendas Iulias promotis iam signis, progresso imperatore cum lucis exordio, fumus vel vis quaedam turbinata pulveris apparebat, ut opinari daretur asinorum esse greges agrestium, quorum multitudo in tractibus est illis innumera, ideo simul incedens, ut constipatione densa feroces leonum frustrentur assultus.", "st": "24.8"}, {"sp": "N", "t": "Quidam arbitrabantur, Arsacen ac duces adventare iam nostros, rumoribus percitos, quod imperator Ctesiphonta magnis viribus oppugnaret, non nulli Persas nobis viantibus incubuisse firmabant.", "st": "24.8"}, {"sp": "N", "t": "Ideo inter haec ita ambigua, nequid adversum accideret, revocantibus agmina classicis, in valle graminea prope rivum, multiplicato scutorum ordine in orbiculatam figuram metatis tutius quievimus castris. Nec enim ad usque vesperam, aere concreto, discerni potuit quidnam esset, quod squalidius videbatur.", "st": "24.8"}, {"sp": "HDR", "t": "Liber XXV", "st": "25"}, {"sp": "N", "t": "Et hanc quidem noctem nullo siderum fulgore splendentem, ut solet in artis rebus et dubiis, exegimus, nec sedere quoquam auso, nec flectere in quietem lumina prae timore. Ubi vero primum dies inclaruit, radiantes loricae limbis circumdatae ferreis, et corusci thoraces, longe prospecti, adesse regis copias indicabant.", "st": "25.1"}, {"sp": "N", "t": "Hocque viso accensum, properantem congredi militem, dirimente fluvio brevi, prohibuit imperator, et non procul a vallo ipso inter excursatores nostros et Persicos, proelio acri conserto, Machameus cecidit, ductor unius agminis nostri. Cui propugnaturus Maurus frater (dux postea Phoenices) cum germani trucidasset interfectorem, obvium quemque perterrens, infirmatus et ipse umerum telo, pallescentem morte propinqua, Machameum extrahere pugna viribus valuit magnis.", "st": "25.1"}, {"sp": "N", "t": "Et cum fatiscerent vix toleranda aestuum magnitudine, crebrisque congressibus partes, ad ultimum hostiles turmae gravi sunt repulsa discussae. Hinc recedentibus nobis, longius Saraceni secuti sunt et nostrorum metu peditum repedare compulsi, paulo post innexi Persarum multitudini tutius irruebant, Romana impedimenta rapturi, verum viso imperatore, ad alas subsidiarias reverterunt.", "st": "25.1"}, {"sp": "N", "t": "Qua ex regione profecti ad Hucumbra nomine villam pervenimus, ubi per biduum omnibus ad usum congruis et satietate quaesita frumenti, ultra spem recreati discessimus, et confestim absque his, quae tempus vehi permisit, reliqua flammis exusta sunt.", "st": "25.1"}, {"sp": "N", "t": "Postridie exercitu sedatius procedente, extremos qui eo die forte cogendorum agminum officia sustinebant, necopinantes Persae adorti, negotio levi interfecissent, ni proximus equitatus noster hoc citius intellecto, per patulas valles late diffusus, tantam molem discriminis, vulneratis qui supervenerant, reppulisset.", "st": "25.1"}, {"sp": "N", "t": "In hac cecidit pugna Adaces, nobilis satrapa, legatus quondam ad Constantium principem missus, ac benigne susceptus, cuius exuviis interfector Iuliano oblatis, remuneratus est ut decebat.", "st": "25.1"}, {"sp": "N", "t": "Eodem die Tertiacorum equestris numerus a legionibus incusatus est, quod cum ipsae hostium adversas irrumperent acies, illi paulatim dilapsi, alacritatem paene totius minuissent exercitus.", "st": "25.1"}, {"sp": "N", "t": "Unde ad indignationem iustam imperator erectus, ademptis signis hastisque diffractis, omnes eos qui fugisse arguebantur, inter impedimenta et sarcinas et captivos agere iter imposuit, ductore eorum, qui solus fortiter decertarat, aliae turmae apposito, cuius tribunus turpiter proelium deservisse convincebatur.", "st": "25.1"}, {"sp": "N", "t": "Abiecti sunt autem sacramento etiam alii quattuor ob flagitium simile vexillationum tribuni: hoc enim correctionis moderamine leniori, impendentium consideratione difficultatum, contentus est imperator.", "st": "25.1"}, {"sp": "N", "t": "Progressi itaque stadia septuaginta, attenuata rerum omnium copia, herbis frumentisque crematis, ex flammis ipsis raptas fruges et pabula, ut quisque vehere potuit, conservavit.", "st": "25.1"}, {"sp": "N", "t": "Hoc etiam loco relicto, cum ad tractum Maranga appellatum, omnis venisset exercitus, prope lucis confinia immensa Persarum apparuit multitudo, cum Merene equestris magistro militiae, filiisque regis duobus, et optimatibus plurimis.", "st": "25.1"}, {"sp": "N", "t": "Erant autem omnes catervae ferratae, ita per singula membra densis lamminis tectae, ut iuncturae rigentes compagibus artuum convenirent, humanorumque vultuum simulacra, ita capitibus diligenter apta, ut inbracteatis corporibus solidis, ibi tantum incidentia tela possint haerere, qua per cavernas minutas, et orbibus oculorum affixas, parcius visitur, vel per supremitates narium angusti spiritus emittuntur.", "st": "25.1"}, {"sp": "N", "t": "Quorum pars contis dimicatura, stabat immobilis, ut retinaculis aereis fixam existimares, iuxtaque sagittarii, cuius artis fiducia ab incunabulis ipsis gens praevaluit maxima, tendebant divaricatis brachiis flexiles arcus, ut nervi mammas praestringerent dexteras, spicula sinistris manibus cohaererent, summaque peritia digitorum pulsibus argutum sonantes, harundines evolabant, vulnera perniciosa portantes.", "st": "25.1"}, {"sp": "N", "t": "Post hos elephantorum fulgentium formidandam speciem et truculentos hiatus, vix mentes pavidae perferebant, ad quorum stridorem odoremque et insuetum aspectum magis equi terrebantur.", "st": "25.1"}, {"sp": "N", "t": "Quibus insidentes magistri, manubriatos cultros dexteris manibus illigatos gestabant, acceptae apud Nisibin memores cladis, et si ferociens animal, vires exsuperasset regentis, ne reversum per suos (ut tunc acciderat) collisam sterneret plebem, venam quae caput a cervice disterminat, ictu maximo terebrabant. Exploratum est enim aliquando ab Hasdrubale Hannibalis fratre, ita citius vitam huius modi adimi beluarum.", "st": "25.1"}, {"sp": "N", "t": "Quibus non sine magno terrore perspectis, stipatus armatarum cohortium globis, cum primatibus fidentissimus imperator, ut flagitabat maior vis et atrocior, lunari acie sinuatisque lateribus, occursuros hosti manipulos instruebat.", "st": "25.1"}, {"sp": "N", "t": "Et ne sagittariorum procursus nostrorum cuneos disiectaret, illatis concitatius signis, spiculorum impetum fregit, datoque ad decernendum sollemniter signo, denseti Romani pedites confertas hostium frontes, nisu protruserunt acerrimo.", "st": "25.1"}, {"sp": "N", "t": "Et fervente certaminum mole, clipeorum sonitus et virorum, armorumque lugubre sibilantium fragor, nihil perpetiens iam remissum, campos cruore et corporum strage contexit, effusius cadentibus Persis, quibus saepe languidis in conflictu, artius pes pede collatus, graviter obsistebat, pugnare fortiter eminus consuetis, et si inclinatas suorum copias senserint, cedendo in modum imbrium pone versus directis sagittis, hostes a persequendi fiducia deterrere. Pulsis igitur pondere magnarum virium Parthis, miles solis cursu flammeo diu lassatus, signo in receptum dato ex more, in tentoria repedat ad audenda deinceps maiora sublatus.", "st": "25.1"}, {"sp": "N", "t": "In hoc proelio Persarum maior, ut dictum est, apparuit strages, nostrorum admodum levis. Eminuit tamen inter varies certaminum casus Vetranionis mors viri pugnacis, qui legionem Ziannorum regebat.", "st": "25.1"}, {"sp": "N", "t": "Post quae triduo indutiis destinato, dum suo quisque vulneri medetur vel proximi, commeatibus nos destitutos inedia cruciabat iam non ferenda: et quoniam frugibus exustis et pabulis, homines in discrimen ultimum venerant et iumenta, ex eo cibo, quem animalia tribunorum vehebant et comitum, imae quoque militum plebi penitus indigenti, pars distributa est magna.", "st": "25.2"}, {"sp": "N", "t": "Et imperator, cui non cuppediae ciborum, ex regio more, sed sub columellis tabernaculi parvis cenaturo, pultis portio parabatur exigua, etiam munifici fastidienda gregario quicquid ad ministeria postulabatur, per contubernia paupertina sui securus egessit.", "st": "25.2"}, {"sp": "N", "t": "Ipse autem ad sollicitam suspensamque quietem paulisper protractus, cum somno ut solebat depulso, ad aemulationem Caesaris Iulii quaedam sub pellibus scribens, obscuro noctis altitudine sensus cuiusdam philosophi teneretur, vidit squalidius, ut confessus est proximis, speciem illam Genii publici, quam cum ad Augustum surgeret culmen, conspexit in Galliis, velata cum capite Cornucopia per aulaea tristius discedentem.", "st": "25.2"}, {"sp": "N", "t": "Et quamquam ad momentum haesit stupore defixus, omni tamen superior metu, ventura decretis caelestibus commendabat, relictoque humi strato cubili, adulta iam excitus nocte, et numinibus per sacra depulsoria supplicans, flagrantissimam facem cadenti similem visam, aeris parte sulcata, evanuisse existimavit, horroreque perfusus est, ne ita aperte minax Martis apparuerit sidus.", "st": "25.2"}, {"sp": "N", "t": "Erat autem nitor igneus iste, quem διαίσσοντα nos appellamus, nec cadens umquam nec terram contingens. Corpora enim qui credit caelitus posse labi, profanus merito iudicatur, et demens. Fit autem hic habitus modis compluribus, e quibus sufficiet pauca monstrare.", "st": "25.2"}, {"sp": "N", "t": "Scintillas quidam putant ab aetherio candentes vigore, parumque porrectius tendere sufficientes, exstingui, vel certe radiorum flammas iniectas nubibus densis, acri scintillare contactu, aut cum lumen aliquod cohaeserit nubi. Id enim in stellae speciem figuratum, decurrit quidem, dum viribus ignium sustentatur: amplitudine vero spatiorum exinanitum in aerium solvitur corpus, ad substantiam migrans, cuius attritu incaluit nimio.", "st": "25.2"}, {"sp": "N", "t": "Confestim itaque ante lucis primitias, Etrusci haruspices accersiti, consultique quid astri species portenderet nova, vitandum esse cautissime responderunt nequid tunc temptaretur: ex Tarquitianis libris in titulo de rebus divinis, id relatum esse monstrantes, quod face in caelo visa committi proelium vel simile quicquam non oportebit.", "st": "25.2"}, {"sp": "N", "t": "Quo etiam id inter alia multa spernente, orabant haruspices, saltem aliquot horis profectionem differri, et ne hoc quidem sunt adepti, imperatore omni vaticinandi scientia reluctante, sed exorto iam die promota sunt castra.", "st": "25.2"}, {"sp": "N", "t": "Hinc nos egressos, Persae cum saepe afflicti, peditum stabiles pugnas horrerent, structis insidiis, occulte comitabantur, altrinsecus viantes catervas a celsis collibus explorando, ut id suspicans miles, ad usque perpetuum diem nec vallum erigeret nec sudibus se communiret.", "st": "25.3"}, {"sp": "N", "t": "Dumque teguntur firmiter latera, et exercitus pro locorum situ quadratis quidem sed laxis incedit agminibus, invasa subito terga pone versus arma cogentium principi indicatur, etiam tum inermi ad speculanda anteriora progresso.", "st": "25.3"}, {"sp": "N", "t": "Qua concitus clade, oblitus loricae, scuto inter tumultum adrepto, properans ultimis ferre suppetias, revocatur alio metu, qui etiam antesignanos, unde discesserat, paria perpeti nuntiabat.", "st": "25.3"}, {"sp": "N", "t": "Quae dum sine respectu periculi sui, redintegrare festinat, ex alia parte cataphractorum Parthicus globus centurias adoritur medias, ac sinistro cornu inclinato acriter superfusus, faetorem stridoremque elephantorum impatienter tolerantibus nostris, contis et multiplicatis missilibus decernebat.", "st": "25.3"}, {"sp": "N", "t": "Verum principe volitante inter prima discrimina proeliorum, exilivit nostra succinctior armatura, aversorumque Persarum et beluarum, suffragines concidebat et dorsa.", "st": "25.3"}, {"sp": "N", "t": "Quos cum Iulianus cavendi immemor, diffluxisse trepidos elatis vociferando manibus aperte demonstrans, irasque sequentium excitans, audenter effunderet semet in pugnam, clamabant hinc inde candidati (quos disiecerat terror) ut fugientium molem tamquam ruinam male compositi culminis declinaret, et (incertum unde) subita equestris hasta, cute brachii eius praestricta, costis perfossis, haesit in ima iecoris fibra.", "st": "25.3"}, {"sp": "N", "t": "Quam dum avellere dextra manu conatur, acuto utrimque ferro digitorum nervos sensit excisos, et provolutus iumento, praesentiumque veloci concursu, relatus in castra, medicinae ministeriis fovebatur.", "st": "25.3"}, {"sp": "N", "t": "Moxque ubi lenito paulisper dolore, timere desiit, magno spiritu contra exitium certans, arma poscebat et equum, ut reviso proelio suorum fiduciam repararet, ac videretur sui securus, alienae salutis sollicitudine vehementer adstringi: eo vigore, licet in negotio dispari, quo Epaminondas ille dux inclitus letaliter apud Mantiniam saucius et revectus ex acie cura quaerebat sollicita scutum. Quod cum vidisset propius laetior, vi vulneris interiit, et qui animam intrepidus amittebat, iacturam clipei formidavit.", "st": "25.3"}, {"sp": "N", "t": "Sed cum vires parum sufficerent voluntati, sanguinisque profluvio vexaretur, mansit immobilis, ideo spe deinceps vivendi absumpta, quod percunctando, Phrygiam appellari locum ubi ceciderat comperit. Hic enim obiturum se praescripta audierat sorte.", "st": "25.3"}, {"sp": "N", "t": "Sed reducto ad tentoria principe, incredibile dictu est, quo quantoque ardore, miles ad vindictam ira et dolore ferventior involabat, hastis ad scuta concrepans, etiam mori (si tulisset fors) obstinatus. Et quamvis offundebatur oculis altitudo pulveris et aestus calescens officeret alacritati membrorum, tamen velut exauctoratus, amisso ductore, sine parsimonia ruebat in ferrum.", "st": "25.3"}, {"sp": "N", "t": "Contra animosius Persae sagittarum volantium crebritate, conspectum sui rapiebant oppositis, quos elephanti tardius praecedentes, magnitudine corporum, cristarumque a horrore, pavorem iumentis incutiebant et viris. Concursus itaque armatorum, et cadentium gemitus, equorum flatus et tinnitus ferri procul audiebatur, quamdiu satietate vulnerum partibus fessis, nox diremit certamina iam tenebrosa.", "st": "25.3"}, {"sp": "N", "t": "Quinquaginta tum Persarum optimates et satrapae cum plebe maxima ceciderunt, inter has turbas Merena et Nohodare potissimis ducibus interfectis. Obstupescat magniloquentia vetustatis diversis in locis proelia viginti Marcelli: Sicinium Dentatum adiciat ornatum militarium multitudine coronarum: miretur super his Sergium, qui viciens et ter vulneratus est in variis pugnis (ut fertur), cuius posteritatis ultimus Catilina claras gloriarum adoreas, sempiternis maculis obumbravit. Deformabat tamen tristitia laetiores eventus.", "st": "25.3"}, {"sp": "N", "t": "Dum haec enim post discessum ducis ubique aguntur, exercitus cornu dextro defatigato, et Anatolio interfecto, qui tunc erat officiorum magister, Sallustius praefectus, actus in exitium praeceps, et opera sui apparitoris ereptus, Phosphorio amisso consiliario, qui ei aderat casu, evasit; palatini quidam militesque per multa discrimina, occupato castelli vicini praesidio, post diem denique tertium, iungi exercitui potuerunt.", "st": "25.3"}, {"sp": "N", "t": "Quae dum ita aguntur, Iulianus in tabernaculo iacens, circumstantes allocutus est demissos et tristes: “Advenit, o socii, nunc abeundi tempus e vita impendio tempestivum, quam reposcenti naturae, ut debitor bonae fidei redditurus, exulto, non (ut quidam opinantur) afflictus et maerens, philosophorum sententia generali perdoctus, quantum corpore sit beatior animus, et contemplans, quotiens condicio melior a deteriore secernitur, laetandum esse potius quam dolendum. Illud quoque advertens, quod etiam dii caelestes quibusdam piissimis mortem tamquam summum praemium persolverunt.", "st": "25.3"}, {"sp": "N", "t": "“Munus autem id mihi delatum optime scio, ne difficultatibus subcumberem arduis, neve me proiciam umquam, aut prosternam, expertus quod dolores omnes ut insultant ignavis, ita persistentibus cedunt.", "st": "25.3"}, {"sp": "N", "t": "“Nec me gestorum paenitet aut gravis flagitii recordatio stringit, vel cum in umbram et angustias amendarer, vel post principatum susceptum, animum tamquam a cognatione caelitum defluentem, immaculatum (ut existimo) conservavi et civilia moderatius regens, et examinatis rationibus, bella inferens et repellens, tametsi prosperitas simul utilitasque consultorum non ubique concordent, quoniam coeptorum eventus superae sibi vindicant potestates.", "st": "25.3"}, {"sp": "N", "t": "“Reputans autem iusti esse finem imperii, oboedientium commodum et salutem, ad tranquilliora semper (ut nostis) propensior fui, licentiam omnem actibus meis exterminans, rerum corruptricem et morum, gaudensque abeo, sciens quod ubicumque me velut imperiosa parens consideratis periculis obiecit res publica, steti fundatus, turbines calcare fortuitorum assuefactus.", "st": "25.3"}, {"sp": "N", "t": "“Nec fateri pudebit, interiturum me ferro, dudum didici fide fatidica praecinente. Ideoque sempiternum veneror numen, quod non clandestinis insidiis, nec longa morborum asperitate, vel damnatorum fine decedo, sed in medio cursu florentium gloriarum, hunc merui clarum ex mundo digressum. Aequo enim iudicio iuxta timidus est et ignavus, qui cum non oportet, mori desiderat, et qui refugiat cum sit opportunum.", "st": "25.3"}, {"sp": "N", "t": "“Hactenus loqui, vigore virium labente sufficiet. Super imperatore vero creando, caute reticeo, ne per imprudentiam dignum praeteream, aut nominatum quem habilem reor, anteposito forsitan alio, ad discrimen ultimum trudam. Ut alumnus autem rei publicae frugi, opto bonum post me reperiri rectorem.”", "st": "25.3"}, {"sp": "N", "t": "Post haec placide dicta, familiares opes iunctioribus velut supremo distribuens stilo, Anatolium quaesivit, officiorum magistrum, quem cum beatum fuisse Salutius respondisset praefectus, intellexit occisum, acriterque amici casum ingemuit, qui data mente contempserat suum.", "st": "25.3"}, {"sp": "N", "t": "Et flentes inter haec omnes qui aderant, auctoritate integra etiam tum increpabat, humile esse, caelo sideribusque conciliatum lugeri principem dicens.", "st": "25.3"}, {"sp": "N", "t": "Quibus ideo iam silentibus, ipse cum Maximo et Prisco philosophis super animorum sublimitate perplexius disputans, hiante latius suffossi lateris vulnere, et spiritum tumore cohibente venarum, epota gelida aqua quam petiit, medio noctis horrore, vita facilius est absolutus, anno aetatis altero et tricensimo, natus apud Constantinopolim, a pueritia usque parentis obitu destitutus Constanti, quem post fratris Constantini excessum, inter complures alios turba consumpsit imperii successorum, et Basilina matre iam inde a maioribus nobili.", "st": "25.3"}, {"sp": "N", "t": "Vir profecto heroicis connumerandus ingeniis, claritudine rerum et coalita maiestate conspicuus. Cum enim sint (ut sapientes definiunt), virtutes quattuor praecipuae, temperantia, prudentia, iustitia, fortitudo, eisque accedentes extrinsecus aliae, scientia rei militaris, auctoritas felicitas atque liberalitas, intento studio coluit omnes ut singulas.", "st": "25.4"}, {"sp": "N", "t": "Et primum ita inviolata castitate enituit, ut post amissam coniugem nihil umquam venereum attigisse eum constaret; illud advertens, quod apud Platonem legitur, Sophoclem tragoediarum scriptorem, aetate grandaevum, interrogatum ecquid adhuc feminis misceretur, negantem, id adiecisse, quod gauderet harum rerum amorem ut rabiosum quendam effugisse dominum et crudelem.", "st": "25.4"}, {"sp": "N", "t": "Item ut hoc propositum validius confirmaret, recolebat saepe dictum lyrici Bacchylidis, quem legebat iucunde, id asserentis, quod ut egregius pictor vultum speciosum effingit, ita pudicitia celsius consurgentem vitam exornat. Quam labem in adulto robore iuventutis, ita caute vitavit, ut ne suspicione quidem tenus libidinis ullius, vel citerioris vitae ministris incusaretur, ut saepe contingit.", "st": "25.4"}, {"sp": "N", "t": "Hoc autem temperantiae genus crescebat in maius, iuvante parsimonia ciborum et somni, quibus domi forisque tenacius utebatur. Namque in pace victus eius mensarumque tenuitas erat recte noscentibus admiranda, velut ad pallium mox reversuri, per varios autem procinctus, stans interdum more militiae, cibum brevem vilemque sumere visebatur.", "st": "25.4"}, {"sp": "N", "t": "Ubi vero exigua dormiendi quiete, recreasset corpus laboribus induratum, expergefactus, explorabat per semet ipsum vigiliarum vices et stationum, post haec seria ad artes confugiens doctrinarum.", "st": "25.4"}, {"sp": "N", "t": "Et si nocturna lumina, inter quae lucubrabat, potuissent voce ulla testari, profecto ostenderant, inter hunc et quosdam principes multum interesse, quem quidem norant voluptatibus ne ad necessitatem quidem indulsisse naturae.", "st": "25.4"}, {"sp": "N", "t": "Dein prudentiae eius indicia fuere vel plurima, e quibus explicari sufficiet pauca. Armatae rei scientissimus et togatae, civilitati admodum studens, tantum sibi arrogans quantum a contemptu et insolentia distare existimabat: virtute senior quam aetate: studiosus cognitionum omnium et indeclinabilis aliquotiens iudex: censor in moribus regendis acerrimus, placidus opum contemptor, mortalia cuncta despiciens, postremo id praedicabat, turpe esse sapienti, cum habeat animum, captare laudes ex corpore.", "st": "25.4"}, {"sp": "N", "t": "Quibus autem iustitiae inclaruit bonis, multa significant, primo quod erat pro rerum et hominum distinctione, sine crudelitate terribilis, deinde quod paucorum discrimine vitia cohibebat, tum autem quod minabatur ferro potius quam utebatur.", "st": "25.4"}, {"sp": "N", "t": "Postremo ut multa praeteream, constat eum in apertos aliquos inimicos insidiatores suos ita consurrexisse mitissime, ut poenarum asperitatem genuina lenitudine castigaret.", "st": "25.4"}, {"sp": "N", "t": "Fortitudinem certaminum crebritas ususque bellorum ostendit, et patientia frigorum immanium et fervoris. Cumque corporis munus a milite, ab imperatore vero animi poscitur, ipse trucem hostem ictu confecit, audacter congressus, ac nostros cedentes obiecto pectore suo, aliquotiens cohibuit solus: regnaque furentium Germanorum exscindens, et in pulvere vaporato Persidis, augebat fiduciam militis, dimicans inter primos.", "st": "25.4"}, {"sp": "N", "t": "Castrensium negotiorum scientiam, plura declarant et nota: civitatum oppugnationes et castellorum, inter ipsos discriminum vertices, acies figura multiformi compositae, salubriter et caute castra metata, praetenturae stationesque agrariae, tutis rationibus ordinatae.", "st": "25.4"}, {"sp": "N", "t": "Auctoritas adeo valuit, ut dilectus artissime, dum timetur, ac si periculorum socius et laborum, et inter concertationes acerrimas, animadverti iuberet in desides, et Caesar adhuc sine stipendio regeret militem, feris oppositum gentibus, ut dudum est dictum; allocutusque tumentes armatos, discessurum ad vitam minaretur privatam, ni tumultuare desisterent.", "st": "25.4"}, {"sp": "N", "t": "Denique id pro multis nosse sufficiet: exhortatum eum simplici contione militem Gallicanum, pruinis assuetum et Rheno, peragratis spatiis regionum extentis, per tepentem Assyriam ad usque confinia traxisse Medorum.", "st": "25.4"}, {"sp": "N", "t": "Felicitas ita eminuit, ut ipsis quodammodo cervicibus Fortunae aliquamdiu bonae gubernatricis evectus, victoriosis cursibus difficultates superstaret immensas. Et postquam ex occidua plaga digressus est, quoad fuit in terris, quievere nationes omnes immobiles, ac si quodam caduceo leniente mundano.", "st": "25.4"}, {"sp": "N", "t": "Liberalitatis eius testimonia plurima sunt et verissima, inter quae indicta sunt tributorum admodum levia, coronarium indultum, remissa debita multa, diuturnitate congesta, aequata fisci iurgia cum privatis, vectigalia civitatibus restituta cum fundis, absque his quos velut iure vendidere praeteritae potestates, quodque numquam augendae pecuniae cupidus fuit, quam cautius apud dominos servari existimabat, id aliquotiens praedicans, Alexandrum Magnum, ubi haberet thesauros interrogatum, “apud amicos” benivole respondisse.", "st": "25.4"}, {"sp": "N", "t": "Digestis bonis quae scire potuimus, nunc ad explicanda eius vitia veniamus, licet dicta sint carptim. Levioris ingenii, verum hoc institute rectissimo temperabat, emendari se cum deviaret a fruge bona permittens.", "st": "25.4"}, {"sp": "N", "t": "Linguae fusioris, et admodum raro silentis, praesagiorum sciscitationi nimium deditus, ut aequiperare videretur in hac parte principem Hadrianum, superstitiosus magis quam sacrorum legitimus observator, innumeras sine parsimonia pecudes mactans, ut aestimaretur (si revertisset de Parthis), boves iam defuturos, Marci illius similis Caesaris, in quem id accipimus dictum:<br>οἱ βόες οἱ λευκοὶ Μάρκῳ τῷ Καίσαρι χαίρειν.<br>ἄν πάλι νικήσῃς, ἄμμες ἀπωλόμεθα.", "st": "25.4"}, {"sp": "N", "t": "Vulgi plausibus laetus, laudum etiam ex minimis rebus intemperans appetitor, popularitatis cupiditate, cum indignis loqui saepe affectans.", "st": "25.4"}, {"sp": "N", "t": "Verum tamen cum haec ita essent, aestimari poterat (ut ipse aiebat), vetus illa Iustitia, quam offensam vitiis hominum, Aratus extollit in caelum, eo imperante redisse rursus ad terras, ni quaedam ad arbitrium agens, interdum ostenderet se dissimilem sui.", "st": "25.4"}, {"sp": "N", "t": "Namque et iura condidit non molesta, absolute quaedam iubentia fieri vel arcentia, praeter pauca. Inter quae erat illud inclemens, quod docere vetuit magistros rhetoricos et grammaticos Christianos, ni transissent ad numinum cultum.", "st": "25.4"}, {"sp": "N", "t": "Illud quoque itidem parum ferendum, quod municipalium ordinum coetibus, patiebatur iniuste quosdam annecti vel peregrinos, vel ab his consortiis privilegiis aut origine longe discretos.", "st": "25.4"}, {"sp": "N", "t": "Figura tali situque membrorum. Mediocris erat staturae, capillis tamquam pexis et mollibus, hirsuta barba in acutum desinente vestitus, venustate oculorum micantium flagrans, qui mentis eius argutias indicabant, superciliis decoris, et naso rectissimo, ore paulo maiore, labro inferiore demisso, opima et incurva cervice, umeris vastis et latis, ab ipso capite usque unguium summitates, liniamentorum recta compage, unde viribus valebat et cursu.", "st": "25.4"}, {"sp": "N", "t": "Et quoniam eum obtrectatores novos bellorum tumultus, ad perniciem rei communis, insimulant concitasse, sciant docente veritate perspicue, non Iulianum, sed Constantinum ardores Parthicos succendisse, cum Metrodori mendaciis avidius acquiescit, ut dudum rettulimus plene.", "st": "25.4"}, {"sp": "N", "t": "Unde caesi ad internecionem exercitus nostri, capti militares aliquotiens numeri, urbes excisae, rapta munimenta vel diruta, provinciae gravibus impensis exhaustae, et ad effectum tendentibus minis, cuncta petebantur a Persis, ad usque Bithynos et litora Propontidis.", "st": "25.4"}, {"sp": "N", "t": "At in Galliis barbarico tumore gliscente, diffusis per nostra Germanis, iamque Alpibus ad vastandam Italiam perrumpendis nihil (multa et nefanda perpessis hominibus), praeter lacrimas supererat et terrores, ubi et praeteritorum recordatio erat acerba, et expectatio tristior impendentium. Quae omnia iuvenis iste, ad occiduam plagam specie Caesaris missus, regesque pro mancipiis agitans ignobilibus, cuncta paene mira dictu celeritate correxit.", "st": "25.4"}, {"sp": "N", "t": "Itaque ut Orientem pari studio recrearet, adortus est Persas, triumphum exinde relaturus, et cognomentum, si consiliis eius et factis illustribus decreta caelestia congruissent.", "st": "25.4"}, {"sp": "N", "t": "Et cum sciamus adeo experimenta quosdam ridere improvidos, ut bella interdum victi, et naufragi repetant maria, et ad difficultates redeant quibus succubuere saepissime, sunt qui reprehendant paria repetisse principem ubique victorem.", "st": "25.4"}, {"sp": "N", "t": "Nec fuit post haec lamentis aut fletibus locus. Corpore enim curato pro copia rerum et temporis, ut ubi ipse olim statuerat, conderetur, principio lucis secutae, quae erat quintum Kalendas Iulias, hostibus ex omni latere circumfusis, collecti duces exercitus, advocatisque legionum principiis et turmarum, super creando principe consultabant.", "st": "25.5"}, {"sp": "N", "t": "Discissique studiis turbulentis, Arintheus et Victor, et e palatio Constanti residui, de parte sua quendam habilem scrutabantur; contra Nevitta et Dagalaifus proceresque Gallorum virum talem ex commilitio suo quaeritabant.", "st": "25.5"}, {"sp": "N", "t": "Quae dum ambiguntur, nulla variante sententia, itum est voluntate omnium in Salutium, eoque causante morbos et senectutem, honoratior aliquis miles, advertens destinatius reluctantem, “Et quid ageretis,” ait “si id bellum vobis curandum, commisisset absens (ut saepe factum est) imperator? Nonne posthabitis ceteris, militem instantibus aerumnis eriperetis? Id nunc agite et si Mesopotamiam videre licuerit, utriusque exercitus consociata suffragia legitimum principem declarabunt.”", "st": "25.5"}, {"sp": "N", "t": "Inter has exiguas ad tantam rem moras, nondum pensatis sententiis, tumultuantibus paucis (ut in rebus extremis saepe est factum), Iovianus eligitur imperator, domesticorum ordinis primus, paternis meritis mediocriter commendabilis. Erat enim Varroniani, notissimi comitis, filius, haut dudum post depositum militiae munus ad tranquilliora vitae digressi.", "st": "25.5"}, {"sp": "N", "t": "Et confestim indumentis circumdatus principalibus, subitoque productus e tabernaculo, per agmina iam discurrebat, proficisci parantia.", "st": "25.5"}, {"sp": "N", "t": "Et quoniam acies ad usque lapidem quartum porrigebatur, antesignani clamare quosdam Iovianum audientes Augustum, eadem multo maius sonabant: gentilitate enim prope perciti nominis, quod una littera discernebat, Iulianum recreatum arbitrati sunt deduci magnis favoribus ut solebat. Verum cum incurvus ille visus et longior adventaret, suspicati quod acciderat, in lacrimas effusi sunt omnes, et luctum.", "st": "25.5"}, {"sp": "N", "t": "Quod si gravis quidam aequitatis spectator, in ultimo rerum spiritu factum criminatur improvide, nauticos idem iustius incusabit, si amisso perito navigandi magistro, saevientibus flabris et mari, clavos regendae navis cuilibet periculi socio commiserunt.", "st": "25.5"}, {"sp": "N", "t": "His ita caeco quodam iudicio fortunae peractis, Iovianorum signifer quos Varronianus rexerat dudum, cum novo dissidens principe, etiam tum privato, ut patris eius obtrectator molestus, periculum ex inimico metuens iam communia supergresso, discessit ad Persas, ac data dicendi copia quae sciret, docet Saporem iam propinquantem, exstincto quem verebatur, turbine concitato calonum, ad umbram imperii Iovianum adhuc protectorem adscitum, inertem quendam et mollem. Hoc ille audito, quod semper trepidis votis optaverat et inopina prosperitate elatus, multitudine ex regio equitatu adiuncta his, qui dimicavere nobiscum, celeri disposuit gradu, agminis nostri invadi terga postremi.", "st": "25.5"}, {"sp": "N", "t": "Quae dum ultro citroque ordinantur, hostiis pro Ioviano caesis, extisque inspectis, pronuntiatum est eum omnia perditurum, si intra vallum remansisset (ut cogitabat), superiorem vero fore profectum.", "st": "25.6"}, {"sp": "N", "t": "Proinde egredi iam coeptantes, adoriuntur nos elephantis praeviis Persae, ad quorum fremitum inaccessum terribilemque, equis inter initia turbatis et viris, Ioviani et Herculiani, occisis beluis paucis, cataphractis equitibus acriter resistebant.", "st": "25.6"}, {"sp": "N", "t": "Dein legiones Ioviorum atque Victorum, laborantibus suis ferentes auxilium, elephantos duo straverunt cum hostium plebe non parva, et in laevo proelio viri periere fortissimi, Iulianus et Macrobius et Maximus, legionum tribuni, quae tunc primas exercitus obtinebant.", "st": "25.6"}, {"sp": "N", "t": "Hisque sepultis, ut rerum angustiae permiserunt, prope confinia noctis, cum ad castellum Sumere nomine, citis passibus tenderemus, iacens Anatolii corpus est agnitum quod tumultuaria opera terrae mandatum est. Hic et milites sexaginta cum palatinis recepimus, quos in munimentum vacuum confugisse rettulimus.", "st": "25.6"}, {"sp": "N", "t": "Secuto deinde die, pro captu locorum, reperta est in valle lata planities, in qua castra ponuntur, velut murali ambitu circumclausa, praeter unum exitum eundemque patentem, undique in modum mucronum praeacutis sudibus fixis.", "st": "25.6"}, {"sp": "N", "t": "Hocque viso, e saltibus nos hostes diversitate telorum et verbis turpibus incessebant, ut perfidos, et lectissimi principis peremptores: audierant enim ipsi quoque referentibus transfugis, rumore iactato incerto, Iulianum telo cecidisse Romano.", "st": "25.6"}, {"sp": "N", "t": "Ausi denique inter haec equitum cunei, porta perrupta praetoria, prope ipsum tabernaculum principis advenire, occisis multis suorum et vulneratis, vi repulsi sunt magna.", "st": "25.6"}, {"sp": "N", "t": "Egressi exinde proxima nocte, Charcham occupavimus locum, ideo tuti, quod riparum aggeribus humana manu instructis, ne Saraceni deinceps Assyriam persultarent, nostrorum agmina nullus ut ante vexabat.", "st": "25.6"}, {"sp": "N", "t": "Cumque hinc Kalendis Iuliis stadiis triginta confectis, civitatem nomine Duram adventaremus, fatigatis iumentis, vectores eorum novissimi pedibus incedentes, a Saracena multitudine circumsaepti, protinus interissent, ni expeditiores turmae nostrorum opem laborantibus attulissent.", "st": "25.6"}, {"sp": "N", "t": "Hos autem Saracenos ideo patiebamur infestos, quod salaria muneraque plurima a Iuliano, ad similitudinem praeteriti temporis, accipere vetiti, questique apud eum, solum audierant, imperatorem bellicosum et vigilantem ferrum habere, non aurum.", "st": "25.6"}, {"sp": "N", "t": "In hoc loco Persarum obstinatione tritum est quadriduum. Nam progredientes nos sequebantur, crebris lacessitionibus retrahentes; cum staremus ut pugnaturi, gradum sensim referentes moris diuturnis excruciabant. Iamque (ut solent extrema metuentibus etiam ficta placere), fama circumlata fines haud procul limitum esse nostrorum, exercitus vociferans immodeste, dari sibi copiam transeundi Tigridis flagitabat.", "st": "25.6"}, {"sp": "N", "t": "Quibus oppositus cum rectoribus imperator, tumentemque iam canis exortu sideris amnem ostendens, ne se periculosis committerent gurgitibus exorabat, nandi imperitos asserens esse complures, simulque adiciens, hostiles manus hinc inde margines superfusi fluminis occupasse.", "st": "25.6"}, {"sp": "N", "t": "Sed cum haec saepe congeminando, refragaretur in cassum, milesque conclamans magno contentionis fragore, minaretur extrema, id impetratur aegerrime, ut mixti cum arctois Germanis, Galli amnem primi omnium penetrarent, ut his magnitudine fluentorum abreptis residuorum pertinacia frangeretur, aut si id perfecissent innocui, transitus fidentior temptaretur.", "st": "25.6"}, {"sp": "N", "t": "Electique sunt ad id negotium habiles, qui maxima prae ceteris flumina transmeare in regionibus genuinis a prima pueritia sunt instituti, et cum latendi copiam nocturna quies daret, tamquam e transenna simul emissi, spe citius ripas occupavere contrarias, Persarumque conculcatis pluribus et truncatis, quos loca servare dispositos, securitas placido vinxerat somno, efficacis audaciae signum, elatis manibus contortisque sagulis, ostendebant.", "st": "25.6"}, {"sp": "N", "t": "Hoc longe conspecto, ardens ad transitum miles ea mora tantummodo tenebatur quod utribus e caesorum animalium coriis, coagmentare pontes architecti promittebant.", "st": "25.6"}, {"sp": "N", "t": "Quae dum vanis conatibus agitantur, rex Sapor et procul absens et cum prope venisset, exploratorum perfugarumque veris vocibus docebatur, fortia facta nostrorum, foedas suorum strages, et elephantos, quot numquam se regnante meminerat, interfectos, exercitumque Romanum continuis laboribus induratum post casum gloriosi rectoris non saluti suae (ut memorabat) consulere, sed vindictae, difficultatemque rerum instantium aut victoria summa aut morte memorabili finiturum.", "st": "25.7"}, {"sp": "N", "t": "Ob quae reputabat multa et formidanda, diffusum abunde militem per provincias, levi tessera colligi posse expertus, et sciens populum suum, post amissam maximam plebem, ultimis terroribus deformatum, simul comperiens, in Mesopotamia relictum haut multo minorem exercitum.", "st": "25.7"}, {"sp": "N", "t": "Quae super omnia hebetarunt eius anxiam mentem, uno parique natatu quingenti viri transgressi tumidum flumen incolumes, custodibusque confossis, reliquos consortes suos ad similem fiduciam concitasse.", "st": "25.7"}, {"sp": "N", "t": "Haec inter cum neque pontes compaginari, paterentur undae torrentes, et absumptis omnibus quae poterant mandi, sine utilibus ullis, acto miserabiliter biduo, furebat inedia iraque percitus miles, ferro properans quam fame, ignavissimo genere mortis, absumi.", "st": "25.7"}, {"sp": "N", "t": "Erat tamen pro nobis numen dei caelestis aeternum, et Persae praeter sperata priores, super fundanda pace oratores Surenam et optimatem alium mittunt, animos ipsi quoque despondentes, quos omnibus paene proeliis pars Romana superior gravius quassabat in dies.", "st": "25.7"}, {"sp": "N", "t": "Condiciones autem ferebant difficiles et perplexas, fingentes humanorum respectu, reliquias exercitus redire sinere clementissimum regem, si quae iubet impleverit cum primatibus Caesar.", "st": "25.7"}, {"sp": "N", "t": "Contra hos cum Salutio praefecto mittitur Arintheus, et dum deliberatur examinatius, quid finiri deberet, dies quattuor sunt evoluti. inedia cruciabiles, et omni supplicio tristiores.", "st": "25.7"}, {"sp": "N", "t": "Quo temporis spatio, antequam hi mitterentur, si exabusus princeps paulatim terris hostilibus excessisset, profecto venisset ad praesidia Corduenae, uberis regionis et nostrae, ex eo loco in quo haec agebantur, centesimo lapide disparatae.", "st": "25.7"}, {"sp": "N", "t": "Petebat autem rex obstinatius, ut ipse aiebat, sua dudum a Maximiano erepta, ut docebat autem negotium, pro redemptione nostra quinque regiones Transtigritanas: Arzanenam et Moxoenam et Zabdicenam, itidemque Rehimenam et Corduenam cum castellis quindecim, et Nisibin et Singaram et Castra Maurorum, munimentum perquam oportunum.", "st": "25.7"}, {"sp": "N", "t": "Et cum pugnari deciens expediret, ne horum quicquam dederetur, adulatorum globus instabat timido principi, Procopii metuendum subserens nomen, eumque affirmans, si redit cognito Iuliani interitu, cum intacto milite quem regebat, novas res nullo renitente facile moliturum.", "st": "25.7"}, {"sp": "N", "t": "Hac perniciosa verborum ille assiduitate nimia succensus, sine cunctatione tradidit omnia, quae petebantur, difficile hoc adeptus, ut Nisibis et Singara sine incolis transirent in iura Persarum, a munimentis vero alienandis, reverti ad nostra praesidia Romani permitterentur.", "st": "25.7"}, {"sp": "N", "t": "Quibus exitiale aliud accessit et impium, ne post haec ita composita, Arsaci poscenti, contra Persas ferretur auxilium, amico nobis semper et fido. Quod ratione gemina cogitatum est, ut puniretur homo qui Chiliocomum mandatu vastaverat principis, et remaneret occasio, per quam subinde licenter invaderetur Armenia. Unde postea contigit, ut vivus caperetur idem Arsaces, et Armeniae maximum latus, Medis conterminans, et Artaxata, inter dissensiones et turbamenta raperent Parthi.", "st": "25.7"}, {"sp": "N", "t": "Quo ignobili decreto firmato, nequid committeretur per indutias contrarium pactis, obsidatus specie viri celebres altrinsecus dantur Nemota et Victor ex parte nostrorum, et Bellovaedius, insignium numerorum tribuni, ex parte vero diversa, Bineses e numero nobilium optimatum, tresque alii satrapae non obscuri.", "st": "25.7"}, {"sp": "N", "t": "Foederata itaque pace annorum triginta, eaque iuris iurandi religionibus consecrata, reversi itineribus aliis, quoniam loca contigua flumini ut confragosa vitabantur et aspera, potus inopia premebamur et cibi.", "st": "25.7"}, {"sp": "N", "t": "Et pax specie humanitatis indulta, in perniciem est versa multorum, qui fame ad usque spiritum lacerati postremum, ideoque latenter progressi, aut imperitia nandi gurgite fluminis sorbebantur, aut si undarum vi superata venirent ad ripas, rapti a Saracenis vel Persis, quos (ut diximus paulo ante), exturbavere Germani, caedebantur ut pecora, vel longius amendati sunt venundandi.", "st": "25.8"}, {"sp": "N", "t": "Ubi vero transeundi amnis aperte signum dedere, bucinae concrepantes, immane quo quantoque ardore, temere rapiendo momenta periculorum, semet quisque reliquis omnibus anteponens, vitare multa et terribilia festinabat, et pars ratibus temere textis, iumenta retinentes hinc inde natantia, alii supersidentes utribus, quidam diversa in necessitatis abrupto versantes, undarum occursantium fluctus obliquis meatibus penetrabant.", "st": "25.8"}, {"sp": "N", "t": "Imperator ipse brevibus lembis, quos post exustam classem docuimus remansisse, cum paucis transvectus, eadem navigia ultro citroque discurrere statuit, dum omnes conveheremur. Tandemque universi (praeter mersos) ad ulteriores venimus margines, favore superi numinis, discrimine per difficiles casus extracti.", "st": "25.8"}, {"sp": "N", "t": "Dum nos impendentium aerumnarum opprimit timor, compertum est procursatorum indicio, Persas pontem iungere procul e nostro conspectu, ut post firmatam pacem et foedera, sopitis belli turbinibus, incuriosius gradientes aegros et animalia peterent, diu defatigata, verum cum se proditos advertissent, a conatu nefario destiterunt.", "st": "25.8"}, {"sp": "N", "t": "Hac etiam suspicione iam liberi, properantesque itineribus magnis, prope Hatram venimus, vetus oppidum in media solitudine positum, olimque desertum, quod eruendum adorti temporibus variis Traianus et Severus principes bellicosi, cum exercitibus paene deleti sunt, ut in eorum actibus has quoque digessimus partes.", "st": "25.8"}, {"sp": "N", "t": "Unde cognito per porrectam planitiem ad usque lapidem septuagensimum, in regionibus aridis nec aquam inveniri posse praeter salsam et faetidam, nec ad victum aliquid nisi abrotonum et absinthium et dracontium, aliaque herbarum genera ut tristissima, vasa quae portabantur, aquis impleta sunt dulcibus, et mactatis camelis, iumentisque aliis, alimenta quaesita sunt, licet noxia.", "st": "25.8"}, {"sp": "N", "t": "Et via sex dierum emensa, cum ne gramina quidem invenirentur, solacia necessitatis extremae, dux Mesopotamiae Cassianus, et tribunus Mauricius (pridem ob hoc missus) ad Ur nomine Persicum venere castellum, cibos ferentes, ex his quos relictus cum Procopio et Sebastiano, exercitus parcius victitans, conservarat.", "st": "25.8"}, {"sp": "N", "t": "Hinc Procopius alter, notarius, et Memoridus, militaris tribunus, ad tractus Illyricos mittuntur et Galliarum, nuntiaturi Iuliani mortem et Iovianum post eius obitum ad culmen augustum evectum.", "st": "25.8"}, {"sp": "N", "t": "Quibus id mandaverat princeps, ut Lucillianum, socerum suum post depositum militiae munus, digressum ad otium, morantemque eo tempore apud Sirmium, oblatis magisterii equitum et peditum codicillis, quos eisdem tradiderat, properare Mediolanum urgerent, res firmaturum ancipites, et (quod magis metuebatur), si casus novi quidam exsurgerent, opponendum.", "st": "25.8"}, {"sp": "N", "t": "Quibus imperator secretiores addiderat litteras, Lucillianum itidem monens, ut quosdam lectos exploratae industriae fideique, duceret secum, adminiculis eorum usurus, pro incidentium captu negotiorum.", "st": "25.8"}, {"sp": "N", "t": "Prudentique consilio Malarichum, ex familiaribus negotiis agentem etiam tum in Italia, missis insignibus, Iovino iussit succedere, armorum magistro per Gallias, gemina utilitate praespeculata, ut et dux meriti celsioris, ideoque suspectus, abiret e medio, et homo inferioris spei ad sublimiora provectus, auctoris sui nutantem adhuc statum studio fundaret ingenti.", "st": "25.8"}, {"sp": "N", "t": "Iussum est autem ad implenda haec perrecturis, extollere seriem gestorum in melius, et rumores quaqua irent, verbis diffundere concinentibus, procinctum Parthicum exitu prospero terminatum, additisque festinando itineri noctibus, provinciarum militiaeque rectoribus insinuare novi principis scripta, omniumque sententiis occultius sciscitatis, remeare velociter cum responsis, ut comperto quid in longinquis agatur, principatus corroborandi matura consilia quaerantur et cauta.", "st": "25.8"}, {"sp": "N", "t": "Hos tabellarios fama praegrediens, index tristiorum casuum velocissima, per provincias volitabat et gentes, maximeque omnium Nisibenos acerbo dolore perculsit, cum urbem Sapori deditam comperissent, cuius iram metuebant et simultates, recolentes quae assidue pertulerit funera, eam saepius oppugnare conatus.", "st": "25.8"}, {"sp": "N", "t": "Constabat enim orbem eoum in dicionem potuisse transire Persidis, ni illi haec civitas habili situ, et moenium magnitudine, restitisset. Miseri tamen, licet maiore venturi pavore constringerentur, spe tamen sustentari potuerunt exigua, hac scilicet velut suopte motu vel exoratus eorum precibus, imperator eodem statu retinebit urbem, Orientis firmissimum claustrum.", "st": "25.8"}, {"sp": "N", "t": "Dum gestorum seriem ubique rumores diffunditant varii, in exercitu absumptis commeatibus paucis, quos advectos praediximus, in corpora sua necessitas erat humana vertenda, ni iumentorum caro caesorum aliquatenus perdurasset, unde effectum est ut et armorum pleraque proicerentur et sarcinarum. Adeo enim atroci tabuimus fame, ut si usquam modius unus farinae fuisset repertus, quod raro contigerat, aureis decem mutaretur ut minus.", "st": "25.8"}, {"sp": "N", "t": "Profecti exinde Thilsaphata venimus, ubi Sebastianus atque Procopius, cum tribunis principiisque militum, sibi ad tuendam Mesopotamiam commissorum, ut poscebat sollemnitas, occurrerunt. Et sequebantur benigne suscepti.", "st": "25.8"}, {"sp": "N", "t": "Post quae itinere festinato, Nisibi cupide visa, extra urbem stativa castra posuit princeps, rogatusque enixe precante multiplici plebe, ut ingressus palatio more succederet principum, pertinaciter reluctatus est, erubescens agente se intra muros, urbem inexpugnabilem iratis hostibus tradi.", "st": "25.8"}, {"sp": "N", "t": "Ibi tunc vespera tenebrante, raptus a cena Iovianus, primus inter notarios omnes, quem in obsidione civitatis Maiozamalchae per cuniculum docuimus evasisse cum aliis, ductusque ad devium locum, et praeceps actus in puteum siccum, obrutus est saxorum multitudine superiacta, hanc profecto ob causam, quod Iuliano perempto, ipse quoque nominatus a paucis, ut imperio dignus, nec post creatum Iovianum egit modeste, sed susurrans super negotio quaedam audiebatur, invitabatque ad convivia subinde militares.", "st": "25.8"}, {"sp": "N", "t": "Postridie Bineses, unus ex Persis quem inter alios excellere diximus, mandata regis complere festinans, promissa flagitabat instanter, et principe permittente Romano, civitatem ingressus, gentis suae signum ab arce extulit summa, migrationem e patria civibus nuntians luctuosam.", "st": "25.9"}, {"sp": "N", "t": "Et vertere solum extemplo omnes praecepti, manusque tendentes flentesque, orabant ne imponeretur sibi necessitas abscedendi, ad defendendos penates se solos sufficere sine alimentis publicis affirmantes et milite, satis confisi adfuturam Iustitiam pro genitali sede dimicaturis, ut experti sunt saepe. Et haec quidem suppliciter ordo et populus precabatur, sed ventis loquebantur in cassum, imperatore (ut fingebat, alia metuens), periurii piacula declinante.", "st": "25.9"}, {"sp": "N", "t": "Tum Sabinus fortuna et genere inter municipes clarus, ore volubili replicabat, Constantium immani crudescente bellorum materia, superatum a Persis interdum, deductumque postremo per fugam cum paucis ad Hibitam stationem intutam, panis frusto vixisse precario, ab anu quadam agresti porrecto, nihil tamen ad diem perdidisse supremum, et Iovianum inter exordia principatus, provinciarum muro cessisse, cuius obices iam inde a vetustate innoxiae permanserunt.", "st": "25.9"}, {"sp": "N", "t": "Cumque nihil promoveretur, iuris iurandi religionem principe destinatius praetendente, cum oblatam ei coronam aliquamdiu recusans, coactus denique suscepisset, Silvanus quidam causarum defensor, confidentius exclamavit: “Ita” inquit, “imperator, a civitatibus residuis coroneris.” Quo verbo exasperatus, intra triduum omnes iussit excedere moenibus, detestantes rerum praesentium statum.", "st": "25.9"}, {"sp": "N", "t": "Appositis itaque compulsoribus, mortem siqui distulerit egredi minitantibus, moenia permixta sunt lamentis et luctu, et per omnia civitatis membra una vox cunctorum erat gementium, cum laceraret crines matrona, exsul fuganda laribus in quibus nata erat et educata, orbataque mater liberis vel coniuge viduata, procul ab eorum manibus pelleretur, et turba flebilis postes penatium amplexa vel limina, lacrimabat.", "st": "25.9"}, {"sp": "N", "t": "Exin variae complentur viae, qua quisque poterat dilabentium. Properando enim multi furabantur opes proprias quas vehi posse credebant, contempta reliqua supellectili, pretiosa et multa. Hanc enim reliquerunt penuria iumentorum.", "st": "25.9"}, {"sp": "N", "t": "Tu hoc loco (Fortuna orbis Romani) merito incusaris, quae, difflantibus procellis rem publicam, excussa regimenta perito rei gerendae ductori, consummando iuveni porrexisti, quem nullis ante actae vitae insignibus in huius modi negotiis cognitum, nec vituperari est aequum, nec laudari.", "st": "25.9"}, {"sp": "N", "t": "Illud tamen ad medullas usque bonorum pervenit, quod dum extimescit aemulum potestatis, dumque in animo per Gallias et Illyricum versat, quosdam saepe sublimiora coeptasse, famam adventus sui praevenire festinans, indignum imperio facinus amictu periurii fugiendi, commisit, Nisibi prodita, quae iam inde a Mithridatici regni temporibus, ne Oriens a Persis occuparetur, viribus restitit maximis.", "st": "25.9"}, {"sp": "N", "t": "Numquam enim ab urbis ortu inveniri potest annalibus replicatis (ut arbitror), terrarum pars ulla nostrarum ab imperatore vel consule hosti concessa, sed ne ob recepta quidem quae direpta sunt, verum ob amplificata regna triumphales glorias fuisse delatas.", "st": "25.9"}, {"sp": "N", "t": "Unde Publio Scipioni ob recuperatas Hispanias, Fulvio Capua post diuturna certamina superata, et Opimio post diversos exitus proeliorum, Fregellanis tunc internecivis hostibus ad deditionem compulsis, triumphi sunt denegati.", "st": "25.9"}, {"sp": "N", "t": "Id etiam memoriae nos veteres docent in extremis casibus icta cum dedecore foedera, postquam partes verbis iuravere conceptis, repetitione bellorum ilico dissoluta, ut temporibus priscis apud Furcas Caudinas sub iugum legionibus missis in Samnio, et per Albinum in Numidia sceleste pace excogitata, et auctore turpiter pactionis festinatae Mancino dedito Numantinis.", "st": "25.9"}, {"sp": "N", "t": "Proinde extractis civibus et urbe tradita missoque tribuno Constantio, qui munimenta praesidiaria cum regionibus, Persicis optimatibus assignaret, cum Iuliani supremis Procopius mittitur, ea ut superstes ille mandarat, humaturus in suburbano Tarsensi.", "st": "25.9"}, {"sp": "N", "t": "Qui ad exsequendum profectus, confestim corpore sepulto discessit, nec inveniri usquam potuit, studio quaesitus ingenti, nisi quod multo postea apud Constantinopolim visus est subito, purpuratus.", "st": "25.9"}, {"sp": "N", "t": "His hoc modo peractis, discursisque itineribus, Antiochiam venimus, ubi per continuos dies, velut offenso numine multa visebantur et dira, quorum eventus fore luctificos, gnari rerum prodigialium praecinebant.", "st": "25.10"}, {"sp": "N", "t": "Nam et Maximiani statua Caesaris, quae locata est in vestibulo regiae, amisit repente sphaeram aeream formatam in speciem poli, quam gestabat, et cum horrendo stridore sonuerunt in consistorio trabes, et visa sunt interdiu sidera cometarum, super quorum natura ratiocinantes physici variant.", "st": "25.10"}, {"sp": "N", "t": "Quidam enim eos hoc nomine ideo existimant appellari, quod tortos ignes spargunt ut crines, in unum stellis multiplicibus congregatis. Alii eos arbitrantur ex halitu sicciore terrarum ignescere, paulatim in sublimiora surgentes. Quidam currentes radios solis, densiore nube obiecta, degredi ad inferiora prohibitos, splendore infuso, corpori crasso, lucem velut stellis distinctam mortali conspectu, monstrare. Sedit quorundam opinioni, hanc speciem tunc apparere, cum erecta solito celsius nubes, aeternorum ignium vicinitate colluceat, vel certe stellas esse quasdam, ceteris similes, quarum ortus obitusque, quibus sint temporibus praestituti, humanis mentibus ignorari. Plura alia de cometis apud peritos mundanae rationis sunt lecta, quae digerere nunc vetat aliorsum oratio properans.", "st": "25.10"}, {"sp": "N", "t": "Moratum paulisper Antiochiae principem, curarumque ponderibus diversis afflictum, exeundi mira cupiditas agitabat: proinde nec iumento parcens nec militi, flagrante hieme die profectus, signis (ut dictum est), vetantibus plurimis, Tarsum urbem Cilicum nobilem introiit, cuius originem docuimus supra.", "st": "25.10"}, {"sp": "N", "t": "Exindeque egredi nimium properans, exornari sepulchrum statuit Iuliani, in pomerio situm itineris, quod ad Tauri montis angustias ducit, cuius suprema et cineres, siqui tune iuste consuleret, non Cydnus videre deberet, quamvis gratissimus amnis et liquidus, sed ad perpetuandam gloriam recte factorum praeterlambere Tiberis, intersecans urbem aeternam divorumque veterum monumenta praestringens.", "st": "25.10"}, {"sp": "N", "t": "Deinde Tarso profectus, extentis itineribus venit oppidum Cappadociae Tyana, ubi ei reversi Procopius notarius et Memoridus tribunus occurrunt, gestorumque aperiunt textum, hinc (ut ordo poscebat) exorsi, quod Lucillianus Mediolanum ingressus, cum Seniaucho et Valentiniano tribunis, quos duxerat secum, cognito quod Malarichus recusavit suscipere magisterium, effuso cursu petierat Remos.", "st": "25.10"}, {"sp": "N", "t": "Et tamquam in alto gentis silentio, extra calcem (ut dicitur) procurrebat, et intempestive, parum etiam tum firmatis omnibus, ex actuario ratiociniis scrutandis incubuit, qui fraudum conscius et noxarum, ad militaria signa confugit, finxitque Iuliano superstite in res novas quendam medium surrexisse, cuius fallaciis turbo militaris acerrime concitus, Lucillianum et Seniauchum occidit. Valentinianum enim paulo postea principem, trepidum, et quo confugeret ambigentem, Primitivus hospes tutius amendarat.", "st": "25.10"}, {"sp": "N", "t": "His ita tristibus laetum aliud addebatur, missos a Iovino milites adventare, quos capita scholarum ordo castrensis appellat, nuntiantes aequo animo Ioviani imperium amplecti exercitum Gallicanum.", "st": "25.10"}, {"sp": "N", "t": "Quibus compertis, Valentiniano qui cum eisdem redierat, regenda Scutariorum secunda committitur schola, et Vitalianus domesticorum consortio iungitur, Erulorum e numero miles, qui multo postea auctus comitis dignitate, male rem per Illyricum gessit, confestimque mittitur in Gallias Arintheus, ferens litteras ad Iovinum, ut constanter ageret suum obtinens locum, eique mandatum est ut animadverteretur in concitorem tumultus, auctoresque seditionis ad comitatum vincti transmitterentur.", "st": "25.10"}, {"sp": "N", "t": "Post quae (ut videbatur expedire) disposita, apud Aspuna Galatiae municipium breve, Gallicani militis visa principia, ingressique consistorium, post audita gratanter quae pertulerant munerati, redire iubentur ad signa.", "st": "25.10"}, {"sp": "N", "t": "Et cum introisset Ancyram imperator, paratis ad pompam pro tempore necessariis, consulatum iniit adhibito in societatem trabeae Varroniano, filio suo, admodum parvulo, cuius vagitus, pertinaciter reluctantis ne in curuli sella veheretur ex more, id quod mox accidit portendebat.", "st": "25.10"}, {"sp": "N", "t": "Hinc quoque Iovianum, celeri gradu, praescriptus vitae finiendae dies exegit. Cum enim venisset Dadastanam, qui locus Bithyniam distinguit et Galatas, exanimatus inventus est nocte. Super cuius obitu dubietates emersere complures.", "st": "25.10"}, {"sp": "N", "t": "Fertur enim recenti calce cubiculi illiti ferre odorem noxium nequivisse, vel extuberato capite perisse succensione prunarum immensa, aut certe ex colluvione ciborum, avida cruditate distentus. Decessit autem anno tricensimo aetatis et tertio. Cumque huic et Aemiliano Scipioni vitae exitus similis evenisset, super neutrius morte quaestionem comperimus agitatam.", "st": "25.10"}, {"sp": "N", "t": "Incedebat autem motu corporis gravi, vultu laetissimo, oculis caesiis, vasta proceritate et ardua, adeo ut diu nullum indumentum regium ad mensuram eius aptum inveniretur. Et aemulari malebat Constantium, agens seria quaedam aliquotiens post meridiem, iocarique palam cum proximis assuetus.", "st": "25.10"}, {"sp": "N", "t": "Christianae legis itidem studiosus et non numquam honorificus, mediocriter eruditus, magisque benivolus, et perpensius, ut apparebat ex paucis, quos promoverat iudices, electurus; edax tamen et vino Venerique indulgens, quae vitia imperiali verecundia forsitan correxisset.", "st": "25.10"}, {"sp": "N", "t": "Dicebatur autem Varronianus pater eius monitu cuiusdam somnii dudum praescisse quod evenit, idque duobus amicis commisisse fidissimis, illo adiecto, quod ipsi quoque deferetur trabea consularis. Sed impetrato uno adipisci non potuit aliud. Audita enim filii celsiore fortuna, antequam eum videret, fatali praeventus est morte.", "st": "25.10"}, {"sp": "N", "t": "Et quia huic nomini amplissimum magistratum portendi per quietem praedictum est seni, Varronianus nepos eius infans etiam tum, cum Ioviano patre declaratus est (ut supra rettulimus) consul.", "st": "25.10"}], []);})();
